// The sidebar and module chrome use Quest's own SVG sprite, not the icon font, so an
// icon pack could not reach them: choosing Google or Phosphor restyled the page but left
// every navigation icon as it was, which reads as the setting half working.
//
// Each sprite symbol has a Tabler counterpart — the module registry already declares both
// — so under a non-default pack the sprite is swapped for that class and the pack's own
// override applies to it like any other icon.
const SYMBOL_ICON_EQUIVALENT = {
  'q-symbol-analytics': 'ti-chart-bar',
  'q-symbol-approvals': 'ti-user-check',
  'q-symbol-automations': 'ti-automation',
  'q-symbol-calendar': 'ti-calendar',
  'q-symbol-clock': 'ti-clock-hour-4',
  'q-symbol-company-chat': 'ti-users',
  'q-symbol-crm': 'ti-building-community',
  'q-symbol-direct-chat': 'ti-user',
  'q-symbol-files': 'ti-folder',
  'q-symbol-finance': 'ti-book',
  'q-symbol-forms': 'ti-clipboard-list',
  'q-symbol-jobs': 'ti-hammer',
  'q-symbol-knowledge': 'ti-books',
  'q-symbol-messages': 'ti-messages',
  'q-symbol-role-chat': 'ti-users-group',
  'q-symbol-settings': 'ti-settings',
  'q-symbol-tasks': 'ti-clipboard-check',
  'q-symbol-team-chart': 'ti-hierarchy-3',
  'q-symbol-team-workload': 'ti-users',
  'q-symbol-templates': 'ti-layout-grid-add',
  'q-symbol-tickets': 'ti-ticket',
  'q-symbol-time': 'ti-clock',
  'q-symbol-users': 'ti-users',
  'q-search': 'ti-search',
  'q-empty': 'ti-inbox',
  'q-message-file': 'ti-file',
  'q-message-image': 'ti-photo',
  // q-logo and q-company are brand marks, not iconography. They stay as drawn whichever
  // pack is chosen — an icon set has no opinion about someone's logo.
};

// Mirrors the active pack so svgIcon does not read storage or the DOM per icon; there can
// be hundreds in one render. applyIconPack keeps it current.
let activeIconPack = 'quest';

function svgIcon(id, className = 'symbol-icon') {
  const equivalent = activeIconPack !== 'quest' && SYMBOL_ICON_EQUIVALENT[id];
  if (equivalent) return `<i class="ti ${equivalent} ${h(className)}" aria-hidden="true"></i>`;
  return `<svg class="${h(className)}" aria-hidden="true" focusable="false"><use href="#${h(id)}"></use></svg>`;
}

function questLogoImage(alt = 'Questbase') {
  // Only the first carries the alt text: to a screen reader this is one logo, not two.
  return `<img class="quest-logo-image quest-logo-on-light" src="${h(questLogoMarkUrl)}" alt="${h(alt)}" />`
    + `<img class="quest-logo-image quest-logo-on-dark" src="${h(questLogoMarkLightUrl)}" alt="" aria-hidden="true" />`;
}

function moduleSymbol(section = state.route?.section || 'jobs') {
  return MODULE_REGISTRY.find((module) => module.id === section)?.symbol || 'q-empty';
}

function metricSymbol(label) {
  const value = String(label || '').toLowerCase();
  if (value.includes('job') || value.includes('pipeline')) return 'q-symbol-jobs';
  if (value.includes('task') || value.includes('review')) return 'q-symbol-tasks';
  if (value.includes('file')) return 'q-symbol-files';
  if (value.includes('form')) return 'q-symbol-forms';
  if (value.includes('account') || value.includes('customer') || value.includes('member') || value.includes('user') || value.includes('lead')) return 'q-symbol-crm';
  if (value.includes('invoice') || value.includes('collected') || value.includes('expense') || value.includes('net') || value.includes('outstanding')) return 'q-symbol-finance';
  if (value.includes('time') || value.includes('today') || value.includes('days') || value.includes('timer') || value.includes('entries')) return 'q-symbol-clock';
  if (value.includes('approval') || value.includes('access')) return 'q-symbol-approvals';
  return moduleSymbol();
}

// ---- Companies ----------------------------------------------------------------
function renderCompanySwitch(companyId, extraClass = '', options = {}) {
  const companies = allowedCompanies();
  const current = companies.find((company) => company.id === companyId) || companyById(companyId) || companies[0] || {};
  const menuCompanies = companies.filter((company) => company.id === current.id).concat(companies.filter((company) => company.id !== current.id));
  const interactive = options.interactive !== false;
  const deckMode = extraClass.split(' ').includes('deck-company-select');
  const className = ['company-switch', extraClass, companies.length <= 1 ? 'single-company' : ''].filter(Boolean).join(' ');
  if (deckMode && interactive) {
    const workspaces = allowedOperationalWorkspaces(current.id);
    const currentWorkspaceId = activeWorkspaceId();
    const visibleWorkspaces = state.workspaceMenuOpen ? workspaces : workspaces.slice(0, WORKSPACE_RAIL_VISIBLE_LIMIT);
    const hasMore = workspaces.length > WORKSPACE_RAIL_VISIBLE_LIMIT;
    const canManageWorkspaces = canManageOperationalWorkspaces(current.id);
    const workspaceListCollapsed = state.collapsedNavGroups.has('Workspaces');
    return `
      <section class="workspace-rail workspace-menu ${state.workspaceMenuOpen ? 'open' : ''} ${workspaceListCollapsed ? 'list-collapsed' : ''}" aria-label="${h(companyLabel(current))} workspaces">
        <div class="company-account-header" data-company-account-id="${h(current.id)}">
          ${workspaceIconMarkup(current, 'company-account-icon')}
          <span class="company-account-copy">
            <strong>${h(companyLabel(current))}</strong>
            <small>Company account</small>
          </span>
          ${companies.length > 1 ? `
            <button class="company-account-switcher" type="button" data-action="open-company-picker"
                    aria-haspopup="dialog" title="Switch company account"
                    aria-label="Switch company account — currently ${h(companyLabel(current))}">
              <i class="ti ti-selector" aria-hidden="true"></i>
            </button>
          ` : ''}
        </div>
        <div class="workspace-rail-head">
          <button class="workspace-rail-toggle" type="button" data-action="toggle-nav-group" data-group="Workspaces"
                  aria-expanded="${workspaceListCollapsed ? 'false' : 'true'}"
                  title="${workspaceListCollapsed ? 'Show workspaces' : 'Hide workspaces'}">
            <span>Workspaces</span>
            <span class="workspace-rail-count">${workspaces.length}</span>
            <i class="ti ti-chevron-down side-label-chevron" aria-hidden="true"></i>
          </button>
          ${canManageWorkspaces ? `
            <button class="workspace-rail-add" type="button"
                    data-action="open-create-operational-workspace-modal"
                    aria-haspopup="dialog" title="Add workspace" aria-label="Add a workspace">
              <i class="ti ti-plus" aria-hidden="true"></i>
            </button>
          ` : ''}
        </div>
        <div class="workspace-rail-list"${canManageWorkspaces ? ' data-workspace-reorder' : ''}>
          ${visibleWorkspaces.map((workspace) => `
            <div class="workspace-rail-item ${workspace.id === currentWorkspaceId ? 'active' : ''}"${canManageWorkspaces ? ` draggable="true" data-workspace-id="${h(workspace.id)}"` : ''}>
              <button class="workspace-rail-open" type="button" data-action="select-workspace" data-workspace-id="${h(workspace.id)}" aria-label="Open ${h(workspace.name)} workspace" aria-current="${workspace.id === currentWorkspaceId ? 'true' : 'false'}">
                ${workspaceIconMarkup(workspace)}
                <span class="workspace-rail-copy">
                  <strong>${h(workspace.name)}</strong>
                  <small>${h(workspaceRoleLabel(workspace.id))}</small>
                </span>
                <i class="ti ti-check workspace-rail-check" aria-hidden="true"></i>
              </button>
              ${canManageWorkspaces ? `
                <button class="workspace-rail-settings" type="button"
                        data-action="open-edit-operational-workspace-modal"
                        data-workspace-id="${h(workspace.id)}" aria-haspopup="dialog"
                        title="Workspace settings" aria-label="Settings for ${h(workspace.name)}">
                  <i class="ti ti-adjustments" aria-hidden="true"></i>
                </button>
              ` : ''}
            </div>
          `).join('') || '<div class="workspace-rail-empty">No workspace assigned</div>'}
        </div>
        ${hasMore ? `
          <button class="workspace-rail-more" type="button" data-action="toggle-workspace-menu" aria-expanded="${state.workspaceMenuOpen ? 'true' : 'false'}">
            <i class="ti ti-chevron-down" aria-hidden="true"></i>
            <span>${state.workspaceMenuOpen ? 'Show fewer' : 'More workspaces'}</span>
          </button>
        ` : ''}
      </section>
    `;
  }
  if (companies.length <= 1 || !interactive) {
    return `
      <div class="${h(className)}" aria-label="Active company">
        ${workspaceIconMarkup(current)}
        <span class="company-switch-copy"><strong>${h(companyLabel(current))}</strong>${deckMode ? `<small>${h(roleForCompany(companyId))} workspace</small>` : ''}</span>
      </div>
    `;
  }
  return `
    <label class="${h(className)}">
      ${workspaceIconMarkup(current)}
      <select data-company-switch aria-label="Active company">
        ${companies.map((company) => `<option value="${h(company.id)}" ${company.id === companyId ? 'selected' : ''}>${h(companyLabel(company))}</option>`).join('')}
      </select>
    </label>
  `;
}


