function renderMobileStatusRail(companyId) {
  const activeUsers = companyAccessUsers(companyId).filter((user) => user.status === 'active').length;
  const overdueTasks = companyTasks(companyId).filter((task) => task.status !== 'done' && task.due && new Date(task.due) < startOfToday()).length;
  const health = subscriptionAllowsCompany(companyId) ? 'Good' : 'Pending';
  return `
    <div class="mobile-status-rail" aria-label="Workspace status">
      <a href="${appHref(companyPath('admin', { tab: 'billing' }, companyId))}" data-router>
        ${svgIcon('q-symbol-approvals')}<span>${h(subscriptionLabel(companyId))}</span>
      </a>
      <a href="${appHref(companyPath('users', {}, companyId))}" data-router>
        ${svgIcon('q-symbol-users')}<span>${h(String(activeUsers))} active</span>
      </a>
      <a href="${appHref(companyPath('tasks', {}, companyId))}" data-router>
        ${svgIcon('q-symbol-tasks')}<span>${h(String(overdueTasks))} overdue</span>
      </a>
      <a href="${appHref(companyPath('admin', { tab: 'diagnostics' }, companyId))}" data-router>
        ${svgIcon('q-symbol-settings')}<span>Health: ${h(health)}</span>
      </a>
    </div>
  `;
}

function renderMobileTabbar(route, companyId) {
  const showMessages = isModuleInstalled('messages', companyId) && can('messages.view', companyId);
  const showFiles = isModuleInstalled('files', companyId) && can('files.view', companyId);
  const unreadMessages = showMessages ? companyMessageUnreadCount(companyId) : 0;
  const files = showFiles ? companyFiles(companyId).length : '';
  const workBadge = companyJobs(companyId).length + companyTasks(companyId).filter((task) => task.status !== 'done').length;
  const workSections = installedModulesForMobileWork(companyId);
  return `
    <nav class="mobile-tabbar" aria-label="Mobile workspace navigation">
      ${mobileTabItem(route, companyPath('dashboard', {}, companyId), 'ti-layout-dashboard', 'Dashboard', '', ['dashboard'])}
      ${mobileTabItem(route, companyPath('jobs', {}, companyId), 'ti-layout-grid', 'Work', workBadge, workSections)}
      ${showMessages ? mobileTabItem(route, companyPath('messages', {}, companyId), 'ti-message-circle', 'Messages', unreadMessages, ['messages']) : ''}
      ${showFiles ? mobileTabItem(route, companyPath('files', {}, companyId), 'ti-folder', 'Files', files, ['files']) : ''}
      <button class="${state.mobileMenuOpen ? 'active' : ''}" type="button" data-action="toggle-mobile-menu" aria-haspopup="true" aria-expanded="${state.mobileMenuOpen ? 'true' : 'false'}" aria-label="More navigation">
        <i class="ti ti-dots"></i>
        <span>More</span>
      </button>
    </nav>
  `;
}

function renderMobileMoreSheet(route, companyId) {
  const modulesById = new Map(MODULE_REGISTRY.map((module) => [module.id, module]));
  const groups = NAV_GROUPS.map((group) => {
    const items = group.ids
      .map((id) => modulesById.get(id))
      .filter((module) => module && module.status !== 'planned' && canViewModule(module, companyId))
      .map((module) => {
        const path = companyPath(module.id, {}, companyId);
        const active = isActiveNav(route, path);
        const count = moduleBadgeCount(module.id, companyId);
        return `
          <a class="more-sheet-item ${active ? 'active' : ''}" href="${appHref(path)}" data-router>
            ${svgIcon(module.symbol)}
            <span>${h(navigationLabel(module.id, module.label))}</span>
            ${count !== '' ? `<b>${h(String(count))}</b>` : ''}
          </a>
        `;
      });
    if (!items.length) return '';
    return `
      <div class="more-sheet-group">
        <div class="more-sheet-label">${h(group.label)}</div>
        <div class="more-sheet-items">${items.join('')}</div>
      </div>
    `;
  }).join('');
  return `
    <div class="mobile-more ${state.mobileMenuOpen ? 'open' : ''}">
      <button class="mobile-more-backdrop" type="button" data-action="toggle-mobile-menu" aria-label="Close menu"></button>
      <div class="mobile-more-sheet" role="dialog" aria-modal="true" aria-label="More navigation">
        <div class="mobile-more-head">
          <strong>Menu</strong>
          <button class="mobile-more-close" type="button" data-action="toggle-mobile-menu" aria-label="Close menu"><i class="ti ti-x"></i></button>
        </div>
        <div class="mobile-more-scroll">${groups}</div>
      </div>
    </div>
  `;
}

function mobileTabItem(route, path, icon, label, count, sections) {
  const active = route.name === 'company' && sections.includes(route.section);
  return `
    <a class="${active ? 'active' : ''}" href="${appHref(path)}" data-router>
      <i class="ti ${h(icon)}"></i>
      ${count ? `<b>${h(String(Math.min(Number(count) || 0, 99)))}</b>` : ''}
      <span>${h(label)}</span>
    </a>
  `;
}


/**
 * A miniature side menu for the preset picker: the background, two quiet rows and one
 * active row. A flat colour square would not answer the question actually being asked,
 * which is whether the highlight reads against the background.
 *
 * `null` means the shipped default, which has no variables to preview, so its own colours
 * are named here — the one place they are duplicated, and only at swatch size.
 */


function renderNotificationCenter(companyId) {
  const notifications = companyNotifications(companyId);
  const unreadCount = notifications.filter((item) => !item.read_at).length;
  return `
    <div class="notification-center ${state.notificationMenuOpen ? 'open' : ''}">
      <button class="icon-button notification-button" type="button" data-action="toggle-notifications" aria-label="Open notifications" aria-expanded="${state.notificationMenuOpen ? 'true' : 'false'}">
        <i class="ti ti-bell"></i>
        ${unreadCount ? `<b>${h(String(Math.min(unreadCount, 99)))}</b>` : ''}
      </button>
      <div class="notification-popover" role="dialog" aria-label="Notifications">
        <div class="notification-head">
          <!-- "Inbox" is the messages surface in the nav. This bell is notifications, and
               giving it the other feature's name sent people looking for their chats. -->
          <div><strong>Notifications</strong><span>${h(companyName(companyId))}</span></div>
          <button type="button" data-action="mark-all-notifications-read" ${unreadCount ? '' : 'disabled'}>Mark all read</button>
        </div>
        <div class="notification-list">
          ${notifications.slice(0, 12).map((item) => renderNotificationItem(item)).join('') || emptyState('No notifications yet.')}
        </div>
      </div>
    </div>
  `;
}

function renderNotificationItem(item) {
  return `
    <button class="notification-item ${item.read_at ? 'read' : 'unread'}" type="button" data-action="open-notification" data-notification-id="${h(item.id)}">
      <span></span>
      <div>
        <small>${h(notificationTypeLabel(item.type))} - ${h(item.title)} - ${h(timeAgo(item.created_at))}</small>
        <strong>${h(item.body)}</strong>
      </div>
    </button>
  `;
}

function renderRolePreviewBanner(companyId) {
  const role = rolePreviewForCompany(companyId);
  if (!role) return '';
  return `
    <div class="role-preview-banner" style="--role-color:${h(role.color)}">
      <span></span>
      <div>
        <strong>Viewing as ${h(role.name)}</strong>
        <small>Permission preview only. Your real account has not changed.</small>
      </div>
      <button class="btn" type="button" data-action="exit-role-preview"><i class="ti ti-eye-off"></i>Exit preview</button>
    </div>
  `;
}

function renderReadOnlyDemoBanner() {
  if (!isReadOnlyDemo()) return '';
  return `
    <div class="readonly-demo-banner">
      <i class="ti ti-eye"></i>
      <div>
        <strong>Read-only sample workspace</strong>
        <small>Create your own workspace to save leads, quotes, jobs, files, forms, billing, or team changes.</small>
      </div>
      <button class="btn" type="button" data-action="open-auth-modal" data-auth-mode="register">Create workspace</button>
    </div>
  `;
}

function renderInitialLoadFailureBanner() {
  const failures = state.initialLoadFailures || [];
  if (!failures.length) return '';
  const visible = failures.slice(0, 3).map((label) => h(label)).join(', ');
  const more = failures.length > 3 ? ` and ${failures.length - 3} more` : '';
  return `<div class="readonly-demo-banner" role="status" aria-live="polite"><i class="ti ti-alert-triangle" aria-hidden="true"></i><div><strong>Some data did not load</strong><small>Missing: ${visible}${more}</small></div><button class="btn" type="button" data-action="refresh-data">Retry</button></div>`;
}

function renderDeck(route) {
  const companyId = activeCompanyId();
  const session = activeSession();
  const modulesById = new Map(MODULE_REGISTRY.map((module) => [module.id, module]));
  const groups = sidebarGroupsForScope(route);
  return `
    <div class="deck-brand">
      <a class="logo logo-image-mark" href="${appHref(companyPath('dashboard', {}, companyId))}" data-router aria-label="Questbase dashboard">
        ${questLogoImage()}
      </a>
      <span><strong>Questbase</strong><small>workspace</small></span>
      <button class="deck-toggle" type="button" data-action="toggle-sidebar" aria-label="${state.sidebarCollapsed ? 'Expand navigation' : 'Collapse navigation'}" aria-expanded="${state.sidebarCollapsed ? 'false' : 'true'}">
        <i class="ti ti-chevron-left" aria-hidden="true"></i>
      </button>
    </div>
    <div class="company-card">
      ${renderCompanySwitch(companyId, 'deck-company-select')}
    </div>
    <div class="deck-nav-tools">
      <div class="sidebar-scope-toggle" role="group" aria-label="Navigation scope">
        <button class="${state.sidebarScope === 'my-work' ? 'active' : ''}" type="button" data-action="set-sidebar-scope" data-sidebar-scope="my-work" aria-pressed="${state.sidebarScope === 'my-work' ? 'true' : 'false'}">My work</button>
        <button class="${state.sidebarScope === 'company' ? 'active' : ''}" type="button" data-action="set-sidebar-scope" data-sidebar-scope="company" aria-pressed="${state.sidebarScope === 'company' ? 'true' : 'false'}">Company</button>
      </div>
    </div>
    <div class="deck-scroll">
      ${groups.map((group) => {
        const visible = group.ids
          .map((id) => modulesById.get(id))
          .filter((module) => module && canViewModule(module, companyId));
        const items = visible.map((module) => {
          const navLabel = navigationLabel(module.id, module.label);
          if (module.status === 'planned') return plannedNavItem(module.symbol, navLabel);
          if (module.id === 'contacts') return navItemSalesLifecycle(route, module, companyId);
          if (module.id === 'jobs' || module.id === 'deals') return navItemPipeline(route, module, companyId);
          return navItem(route, companyPath(module.id, {}, companyId), module.symbol, navLabel, moduleBadgeCount(module.id, companyId));
        });
        // Apps sit directly beneath the Workspaces row that built them, so the deck reads
        // the way the product does: the builder, then what it produced. Anything else in
        // the group is unrelated to either and follows.
        if (group.label === 'Workspace') {
          const at = visible.findIndex((module) => module.id === 'workspaces');
          // -1 + 1 = 0: with the builder itself hidden, apps lead rather than vanish.
          items.splice(at + 1, 0, ...navItemsForApps(route, companyId));
        }
        return navGroup(group.label, items);
      }).join('')}
    </div>
    ${renderRailClock(companyId)}
  `;
}

/**
 * The running clock, pinned to the bottom of the rail.
 *
 * Only drawn while a clock is actually running: an idle rail should not carry a permanent
 * 00:00, and the Clock dashboard is one click away for starting one. It ticks through the
 * shared live-clock interval rather than re-rendering the sidebar every second.
 */
function renderRailClock(companyId) {
  const timer = activeTimerForCompany(companyId);
  if (!timer) return '';
  const started = timer.started_at;
  return `
    <a class="rail-clock" href="${appHref(companyPath('clock', {}, companyId))}" data-router title="${h(`Clocked in since ${formatDateTime(started)}`)}">
      <span class="rail-clock-dot" aria-hidden="true"></span>
      <span class="rail-clock-body">
        <b data-live-clock="${h(started)}">${h(formatClock(Date.now() - Date.parse(started)))}</b>
        <small>${h(timer.task_title || 'On the clock')}</small>
      </span>
    </a>
  `;
}

function sidebarGroupsForScope(route) {
  const routeKey = `${route?.name || ''}:${route?.section || ''}`;
  if (state.sidebarScopeRoute !== routeKey) {
    const activeGroup = NAV_GROUPS.find((group) => group.ids.includes(route?.section));
    state.sidebarScope = SIDEBAR_SCOPE_GROUPS.company.has(activeGroup?.label) ? 'company' : 'my-work';
    state.sidebarScopeRoute = routeKey;
  }
  const allowedGroups = SIDEBAR_SCOPE_GROUPS[state.sidebarScope] || SIDEBAR_SCOPE_GROUPS['my-work'];
  return NAV_GROUPS.filter((group) => allowedGroups.has(group.label));
}

/**
 * The builder entry for the active operational workspace, WITHOUT creating one.
 *
 * wbCompanyWorkspace() pushes an entry and renames it to match the operational workspace.
 * That is right on the builder page, which is about to render it, and wrong in the deck,
 * which paints on every route: navigation must not write to the document it describes.
 */
function wbCompanyWorkspacePeek(companyId) {
  const doc = wbDoc(companyId);
  if (!doc) return null;
  const canonical = canonicalCompanyId(companyId);
  const opsId = workspaceIdForCompany(companyId);
  return doc.workspaces.find((ws) => ws.id === (opsId ? `ws-${opsId}` : `ws-${canonical}`))
    || doc.workspaces.find((ws) => ws.id === `ws-${canonical}`)
    || null;
}

/**
 * One deck entry per app in the current workspace, stages nested underneath.
 *
 * An app somebody built is a section of the product to them, so it belongs in the deck
 * beside the built-in modules rather than behind a tile. The rows underneath are the
 * options of the app's own status field -- the same field the board, the table and the
 * status pill already read -- so these counts cannot drift from what the app shows.
 *
 * Silent when the builder document has not loaded. The deck paints on every route, and
 * deciding what to draw must never trigger a fetch.
 */
function navItemsForApps(route, companyId) {
  if (!can('workspaces.view', companyId)) return [];
  const doc = wbDoc(companyId);
  const workspace = doc ? wbCompanyWorkspacePeek(companyId) : null;
  if (!workspace) return [];
  const byId = new Map(wbWorkspaceApps(doc, workspace).map(({ app }) => [app.id, app]));
  // The deck mirrors the workspace home: an app is in the sidebar exactly when it has a
  // tile there. Putting the tile on the page puts the app in the deck, and taking the tile
  // off takes it out again -- one control, in the place you were already arranging things,
  // rather than a second list to keep in step by hand.
  const seen = new Set();
  return wbSidebarTiles(workspace)
    .filter((tile) => tile.type === 'app')
    .map((tile) => byId.get(tile.config?.appId))
    // A tile can point at an app that has since been deleted, and nothing stops two tiles
    // pointing at the same one. Neither should put a broken or a doubled row in the deck.
    .filter((app) => app && !seen.has(app.id) && seen.add(app.id))
    .map((app) => navItemApp(route, app, companyId));
}

/** The unset-stage bucket needs a routable id; a bare '' would read as "no filter". */
const NAV_STAGE_NONE = '__none';

function navItemApp(route, app, companyId) {
  const key = `app:${app.id}`;
  const expanded = state.expandedNav.has(key);
  const onApp = route.name === 'company' && route.section === 'workspaces'
    && route.params.get('app_id') === app.id;
  const stage = onApp ? (route.params.get('stage') || '') : '';
  // An app with no status field still gets its row -- just no disclosure, because it would
  // open onto nothing.
  const field = pipelineField(app);
  const columns = field ? boardColumns(app.items || [], field, null) : [];
  const total = (app.items || []).length;
  const href = (stageId) => appHref(companyPath('workspaces', {
    app_id: app.id, tab: 'items', ...(stageId ? { stage: stageId } : {}),
  }, companyId));
  // The app's own row opens its dashboard; the rows underneath are stages, and a stage only
  // means anything on the list.
  const appHome = appHref(companyPath('workspaces', { app_id: app.id }, companyId));
  const allOn = onApp && !stage;
  return `
    <div class="side-pipe ${expanded ? 'expanded' : ''}">
      <div class="side-pipe-head">
        <a class="side-item ${allOn ? 'active' : ''}" href="${appHome}" data-router title="${h(app.name)}" aria-label="${h(app.name)}" aria-current="${allOn ? 'page' : 'false'}">
          <i class="ti ${h(app.icon || 'ti-apps')}" aria-hidden="true"></i>
          <span>${h(app.name)}</span>
          ${total ? `<b>${h(String(total))}</b>` : ''}
        </a>
        ${columns.length ? `<button class="side-pipe-toggle" type="button" data-action="toggle-nav-expand" data-module="${h(key)}" aria-expanded="${expanded ? 'true' : 'false'}" aria-label="${expanded ? 'Collapse' : 'Expand'} ${h(app.name)} stages">
          <i class="ti ti-chevron-down" aria-hidden="true"></i>
        </button>` : ''}
      </div>
      ${expanded && columns.length ? `
        <div class="side-sub">
          <a class="side-sub-link ${allOn ? 'active' : ''}" href="${href('')}" data-router aria-current="${allOn ? 'page' : 'false'}">
            <span class="side-sub-dot all"></span>
            <span class="side-sub-name">All items</span>
            <span class="side-sub-ct">${h(String(total))}</span>
          </a>
          ${columns.map((col) => {
    const id = col.id == null ? NAV_STAGE_NONE : col.id;
    const on = onApp && stage === id;
    return `<a class="side-sub-link ${on ? 'active' : ''}" href="${href(id)}" data-router aria-current="${on ? 'page' : 'false'}">
              <span class="side-sub-dot" style="background:${h(col.color)}"></span>
              <span class="side-sub-name">${h(col.label)}</span>
              <span class="side-sub-ct">${h(String(col.count))}</span>
            </a>`;
  }).join('')}
        </div>
      ` : ''}
    </div>
  `;
}

