function navGroup(label, items) {
  if (!items.length) return '';
  const collapsed = state.collapsedNavGroups.has(label);
  return `
    <section class="side-group ${collapsed ? 'collapsed' : ''}">
      <button class="side-label" type="button" data-action="toggle-nav-group" data-group="${h(label)}" aria-expanded="${collapsed ? 'false' : 'true'}" title="${collapsed ? 'Expand' : 'Collapse'} ${h(label)}">
        <span>${h(label)}</span>
        <i class="ti ti-chevron-down side-label-chevron" aria-hidden="true"></i>
      </button>
      <div class="side-items">${items.join('')}</div>
    </section>
  `;
}

function navItem(route, path, symbol, label, count = '') {
  const active = isActiveNav(route, path);
  return `
    <a class="side-item ${active ? 'active' : ''}" href="${appHref(path)}" data-router title="${h(label)}" aria-label="${h(label)}" aria-current="${active ? 'page' : 'false'}">
      ${svgIcon(symbol)}
      <span>${h(label)}</span>
      ${count !== '' ? `<b>${h(String(count))}</b>` : ''}
    </a>
  `;
}

function pipelineStageCounts(kind, companyId = activeCompanyId()) {
  const rows = kind === 'contacts' ? companyContacts(companyId) : kind === 'deals' ? companyDeals(companyId) : companyJobs(companyId);
  const counts = {};
  rows.forEach((row) => {
    const stage = resolvePipelineStage(kind, row.stage, companyId);
    counts[stage] = (counts[stage] || 0) + 1;
  });
  return counts;
}

function salesLifecycleStageForContact(contact, companyId = contact?.company_id || activeCompanyId()) {
  const linkedDeals = companyDeals(companyId)
    .filter((deal) => deal.primary_contact_id === contact?.id || (contact?.account_id && deal.account_id === contact.account_id))
    .sort((a, b) => String(b.updated_at || b.created_at || '').localeCompare(String(a.updated_at || a.created_at || '')));
  const deal = linkedDeals[0];
  const dealSignal = `${deal?.status || ''} ${deal?.stage || ''}`.toLowerCase();
  if (dealSignal.includes('lost')) return underwriterStageByKey('lost');
  if (dealSignal.includes('won')) return underwriterStageByKey('won');
  if (/contract|waiting|sign/.test(dealSignal)) return underwriterStageByKey('contract');
  if (dealSignal.includes('negotiat')) return underwriterStageByKey('negotiating');
  if (/estimate|proposal/.test(dealSignal)) return underwriterStageByKey('estimate');
  if (dealSignal.includes('underwrit')) return underwriterStageByKey('underwriting');

  const contactSignal = String(contact?.stage || '').toLowerCase();
  if (contactSignal.includes('lost')) return underwriterStageByKey('lost');
  if (contactSignal.includes('won')) return underwriterStageByKey('won');
  if (/contract|waiting|sign/.test(contactSignal)) return underwriterStageByKey('contract');
  if (contactSignal.includes('negotiat')) return underwriterStageByKey('negotiating');
  if (/estimate|proposal/.test(contactSignal)) return underwriterStageByKey('estimate');
  if (contactSignal.includes('underwrit')) return underwriterStageByKey('underwriting');
  if (/follow|nurtur/.test(contactSignal)) return underwriterStageByKey('followup');
  if (contactSignal.includes('prospect')) return underwriterStageByKey('prospects');
  return underwriterStageByKey('leads');
}

function salesLifecycleStageCounts(companyId = activeCompanyId()) {
  const counts = Object.fromEntries(QUEST_SALES_LIFECYCLE_STAGES.map((stage) => [stage.key, 0]));
  companyContacts(companyId).forEach((contact) => {
    const key = salesLifecycleStageForContact(contact, companyId).key;
    counts[key] = (counts[key] || 0) + 1;
  });
  return counts;
}

function navItemSalesLifecycle(route, module, companyId) {
  const kind = module.id;
  const navLabel = navigationLabel(module.id, module.label);
  const path = companyPath(kind, {}, companyId);
  const active = isActiveNav(route, path);
  // Jobs stays open. Its stages are the way people navigate production -- collapsing them
  // means one extra click before every single move, and there is nothing else competing for
  // the room. The other pipelines keep their disclosure.
  const expanded = state.expandedNav.has(kind);
  const count = moduleBadgeCount(kind, companyId);
  const activeLifecycle = route.name === 'company' && route.section === 'contacts' ? route.params.get('lifecycle') || '' : '';
  const counts = salesLifecycleStageCounts(companyId);
  return `
    <div class="side-pipe sales-lifecycle-nav ${expanded ? 'expanded' : ''}">
      <div class="side-pipe-head">
        <a class="side-item ${active ? 'active' : ''}" href="${appHref(path)}" data-router data-action="pipeline-open" data-module="${kind}" title="${h(navLabel)}" aria-label="${h(navLabel)}" aria-current="${active ? 'page' : 'false'}">
          ${svgIcon(module.symbol)}
          <span>${h(navLabel)}</span>
          ${count !== '' ? `<b>${h(String(count))}</b>` : ''}
        </a>
        <button class="side-pipe-toggle" type="button" data-action="toggle-nav-expand" data-module="${kind}" aria-expanded="${expanded ? 'true' : 'false'}" aria-label="${expanded ? 'Collapse' : 'Expand'} ${h(navLabel)} stages">
          <i class="ti ti-chevron-down" aria-hidden="true"></i>
        </button>
      </div>
      ${expanded ? `
        <div class="side-sub">
          ${QUEST_SALES_LIFECYCLE_STAGES.map((stage, index) => `
            ${index === 7 ? '<span class="side-sub-divider" aria-hidden="true"></span>' : ''}
            <a class="side-sub-link ${activeLifecycle === stage.key ? 'active' : ''}" href="${appHref(companyPath('contacts', { lifecycle: stage.key }, companyId))}" data-router aria-current="${activeLifecycle === stage.key ? 'page' : 'false'}">
              <span class="side-sub-dot" style="background:${h(stage.color)}"></span>
              <span class="side-sub-name">${h(stage.name)}</span>
              <span class="side-sub-ct">${h(String(counts[stage.key] || 0))}</span>
            </a>
          `).join('')}
        </div>
      ` : ''}
    </div>
  `;
}

/**
 * Calendar, above the status buckets.
 *
 * Jobs is the one pipeline with a screen that is not a filtered list, and it belongs here
 * rather than behind opening the module first and then finding a tab.
 *
 * The Dashboard is deliberately NOT here: it moved to the workspace home as a tile you
 * arrange yourself, so there is no separate page of it to link to.
 */
function jobsNavViews(route, companyId) {
  const onJobs = route.name === 'company' && route.section === 'jobs';
  const on = onJobs && route.params.get('tab') === 'calendar';
  const path = companyPath('jobs', { tab: 'calendar' }, companyId);
  return `<a class="side-sub-link ${on ? 'active' : ''}" href="${appHref(path)}" data-router aria-current="${on ? 'page' : 'false'}">
    <i class="ti ti-calendar side-sub-icon" aria-hidden="true"></i>
    <span class="side-sub-name">Calendar</span>
  </a>`;
}

function navItemPipeline(route, module, companyId) {
  const kind = module.id;
  const navLabel = navigationLabel(module.id, module.label);
  const path = companyPath(kind, {}, companyId);
  const active = isActiveNav(route, path);
  // Production is the section people live in, and its sub-views are the whole point of the
  // rail. Collapsing them behind a chevron was a click for nothing, so Jobs stays open.
  const alwaysOpen = kind === 'jobs';
  const expanded = alwaysOpen || state.expandedNav.has(kind);
  const count = moduleBadgeCount(kind, companyId);
  const onSection = route.name === 'company' && route.section === kind;
  const filter = kind === 'contacts' ? state.contactStageFilter : kind === 'deals' ? state.stageFilterDeals : state.stageFilter;
  // Jobs lists no stages in the rail. The Jobs page already carries the same filters as chips
  // -- same stages, same counts, the same `pipeline-stage` action -- so the rail was a second
  // copy of them: eight rows deep, mostly zeros, in the section people live in. Removing them
  // takes nothing away, and it stops pipelineStageCounts scanning every job on a paint that
  // happens on every route. Deals keeps its list, which is collapsed behind a chevron anyway.
  //
  // Emptied rather than branched in the markup: the template below maps over `stages` and an
  // empty list renders nothing, so there is one shape for both instead of two.
  const showStages = kind !== 'jobs';
  const stages = showStages ? pipelineStages(kind, companyId) : [];
  const counts = showStages ? pipelineStageCounts(kind, companyId) : {};
  return `
    <div class="side-pipe ${expanded ? 'expanded' : ''}">
      <div class="side-pipe-head">
        <a class="side-item ${active ? 'active' : ''}" href="${appHref(path)}" data-router data-action="pipeline-open" data-module="${kind}" title="${h(navLabel)}" aria-label="${h(navLabel)}" aria-current="${active ? 'page' : 'false'}">
          ${svgIcon(module.symbol)}
          <span>${h(navLabel)}</span>
          ${count !== '' ? `<b>${h(String(count))}</b>` : ''}
        </a>
        ${alwaysOpen ? '' : `<button class="side-pipe-toggle" type="button" data-action="toggle-nav-expand" data-module="${kind}" aria-expanded="${expanded ? 'true' : 'false'}" aria-label="${expanded ? 'Collapse' : 'Expand'} ${h(navLabel)} stages">
          <i class="ti ti-chevron-down" aria-hidden="true"></i>
        </button>`}
      </div>
      ${expanded ? `
        <div class="side-sub">
          ${kind === 'jobs' ? jobsNavViews(route, companyId) : ''}
          <button class="side-sub-link ${onSection && filter === 'all' ? 'active' : ''}" type="button" data-action="pipeline-stage" data-module="${kind}" data-stage="all" aria-current="${onSection && filter === 'all' ? 'page' : 'false'}">
            <span class="side-sub-dot all"></span>
            <span class="side-sub-name">All ${h(navLabel.toLowerCase())}</span>
            <span class="side-sub-ct">${h(String(count || 0))}</span>
          </button>
          ${stages.map((stage) => `
            <button class="side-sub-link ${onSection && filter === stage.name ? 'active' : ''}" type="button" data-action="pipeline-stage" data-module="${kind}" data-stage="${h(stage.name)}" aria-current="${onSection && filter === stage.name ? 'page' : 'false'}">
              <span class="side-sub-dot" style="background:${h(stage.color)}"></span>
              <span class="side-sub-name">${h(stage.name)}</span>
              <span class="side-sub-ct">${h(String(counts[stage.name] || 0))}</span>
            </button>
          `).join('')}
        </div>
      ` : ''}
    </div>
  `;
}

function plannedNavItem(symbol, label) {
  return `
    <button class="side-item planned" type="button" disabled aria-disabled="true" title="${h(label)}" aria-label="${h(label)}">
      ${svgIcon(symbol)}
      <span>${h(label)}</span>
      <b>Planned</b>
    </button>
  `;
}

