// ---- Tasks ----------------------------------------------------------------
function renderEmbeddedTasksPage(route, companyId) {
  const job = route.jobId ? jobById(route.jobId) : null;
  const workspaceId = workspaceIdForCompany(companyId);
  // The vendored task module at /taskmanagement/ replaces the former native
  // placeholder. It runs embedded: ?embed=1 makes it hide its own topbar
  // (.embedded-in-job-center) so Questbase's chrome is the only chrome, and
  // project_id scopes it to the job. The session is shared automatically — same
  // origin, same Supabase project — so there is no second login.
  // The module authenticates against the same Supabase project as the host, so it
  // needs a REAL session. Demo/local sessions have no Supabase user, and embedding
  // it anyway just renders a sign-in page inside the frame (confusing) or loops.
  // Say so plainly instead.
  if (state.session?.auth !== 'supabase') {
    return `
      ${workspaceHeader(job ? `${job.name} tasks` : 'Tasks', 'Task execution, timers and reminders.', '')}
      <section class="task-layout task-layout-flat">
        <article class="panel task-main">
          ${emptyState(state.session?.auth === 'demo-readonly'
            ? 'Tasks need a real account. You are exploring in demo mode — sign in with your Questbase account to use task execution, timers and reminders.'
            : 'Tasks need a signed-in Questbase account. Sign in to continue.')}
        </article>
      </section>
    `;
  }

  if (!workspaceId) {
    return `
      ${workspaceHeader('Tasks', 'Task execution, timers and reminders.', '')}
      <section class="task-layout task-layout-flat">
        <article class="panel task-main">
          ${emptyState('Open Tasks from an active Questbase workspace. No operational workspace is available for this route.')}
        </article>
      </section>
    `;
  }

  const params = new URLSearchParams({ embed: '1' });
  params.set('workspace_id', workspaceId);
  if (job) params.set('project_id', job.id);
  params.set('return_url', window.location.href);
  // Forward CC's deep-link params to the task app's own hash routes so every
  // existing "open this task" link across Questbase keeps working:
  //   ?task_id=X -> #/task/X      ?new=1 / ?edit=1 -> #/new
  const taskId = route.params.get('task_id');
  const wantsNew = route.params.get('new') === '1' || route.params.get('edit') === '1';

  const hash = taskId ? `#/task/${encodeURIComponent(taskId)}` : (wantsNew ? '#/new' : '');
  const src = `${window.location.origin}/taskmanagement/app.html?${params.toString()}${hash}`;
  // No workspace header: the task module carries its own toolbar, so CC's header
  // row held nothing but a Jobs shortcut and cost ~78px above the frame. With no
  // actions passed, workspaceHeader() renders nothing at all for a non-notice
  // title, so the module starts at the top of the work surface. (Jobs is still
  // one click away in the sidebar.)
  return `
    <section class="task-layout task-layout-flat taskapp-shell">
      <article class="panel task-main taskapp-panel">
        <iframe class="taskapp-frame" src="${h(src)}" title="Task management"></iframe>
      </article>
    </section>
  `;
}


function renderTaskToolbar(companyId, job) {
  const jobs = companyJobs(companyId);
  return `
    <section class="workspace-toolbar">
      <label>
        <span>Job</span>
        <select data-task-job-filter>
          <option value="">All jobs</option>
          ${jobs.map((item) => `<option value="${h(item.id)}" ${job?.id === item.id ? 'selected' : ''}>${h(item.name)}</option>`).join('')}
        </select>
      </label>
      <label>
        <span>Status</span>
        <select data-task-status-filter>
          ${['all'].concat(TASK_STATUSES).map((status) => `<option value="${h(status)}" ${state.taskStatusFilter === status ? 'selected' : ''}>${h(status === 'all' ? 'All statuses' : statusLabel(status))}</option>`).join('')}
        </select>
      </label>
      <label>
        <span>Priority</span>
        <select data-task-priority-filter>
          ${['all'].concat(TASK_PRIORITIES).map((priority) => `<option value="${h(priority)}" ${state.taskPriorityFilter === priority ? 'selected' : ''}>${h(priority === 'all' ? 'All priorities' : titleCase(priority))}</option>`).join('')}
        </select>
      </label>
      <div class="segmented" role="group" aria-label="Task view">
        <button class="${state.taskView === 'table' ? 'active' : ''}" type="button" data-action="set-task-view" data-view="table"><i class="ti ti-table"></i>Table</button>
        <button class="${state.taskView === 'board' ? 'active' : ''}" type="button" data-action="set-task-view" data-view="board"><i class="ti ti-layout-kanban"></i>Board</button>
      </div>
    </section>
  `;
}

function taskContextLabel(task, companyId) {
  const labels = [
    jobById(task.project_id)?.name,
    contactById(task.contact_id)?.name,
    dealById(task.deal_id)?.name,
  ].filter(Boolean);
  return labels.join(' / ') || companyName(companyId);
}

function renderTaskTable(companyId, tasks) {
  return `
    <div class="data-table task-table">
      <div class="table-head"><span>Task</span><span>Context</span><span>Assignee</span><span>Priority</span><span>Status</span><span>Due</span></div>
      ${tasks.map((task) => `
        <button class="table-row ${task.id === state.selectedTaskId ? 'active' : ''}" type="button" data-select-task="${h(task.id)}">
          <span><strong>${h(task.title)}</strong><small>${h(task.description || taskTypeLabel(task.type))}${recurrenceBadge(task.recurrence)}</small></span>
          <span>${h(taskContextLabel(task, companyId))}</span>
          <span>${h(memberName(task.assignee_id))}</span>
          <span>${taskPriorityPill(task.priority)}</span>
          <span>${taskStatusPill(task.status)}</span>
          <span>${formatDate(task.due)}</span>
        </button>
      `).join('') || emptyState('No tasks match this workspace view.')}
    </div>
  `;
}

function renderTaskBoard(companyId, tasks) {
  return `
    <div class="task-board">
      ${TASK_STATUSES.map((status) => {
        const column = tasks.filter((task) => task.status === status);
        return `
          <section class="task-column">
            <h2><span>${h(statusLabel(status))}</span><b>${column.length}</b></h2>
            ${column.map((task) => `
              <button class="task-card priority-${h(task.priority)}" type="button" data-select-task="${h(task.id)}">
                <strong>${h(task.title)}</strong>
                <span>${h(taskContextLabel(task, companyId))}</span>
                <small>${h(memberName(task.assignee_id))} - ${formatDate(task.due)}</small>
                ${recurrenceBadge(task.recurrence)}
              </button>
            `).join('') || `<div class="lane-empty">No tasks</div>`}
          </section>
        `;
      }).join('')}
    </div>
  `;
}

function renderTaskContextLinks(task, companyId) {
  const job = task.project_id ? jobById(task.project_id) : null;
  const contact = task.contact_id ? contactById(task.contact_id) : null;
  const deal = task.deal_id ? dealById(task.deal_id) : null;
  const links = [
    job ? `<a class="task-context-link" href="${appHref(companyPath('jobs', { tab: 'profile', job_id: job.id }, companyId))}" data-router><i class="ti ti-hammer"></i><span><small>Job</small>${h(job.name)}</span></a>` : '',
    contact ? `<a class="task-context-link" href="${appHref(companyPath('contacts', { contact_id: contact.id }, companyId))}" data-router><i class="ti ti-user"></i><span><small>Contact</small>${h(contact.name)}</span></a>` : '',
    deal ? `<a class="task-context-link" href="${appHref(companyPath('deals', { tab: 'profile', deal_id: deal.id }, companyId))}" data-router><i class="ti ti-file-dollar"></i><span><small>Quote</small>${h(deal.name)}</span></a>` : '',
  ].filter(Boolean);
  return `<div class="task-context-links">${links.join('') || '<span class="muted">Company-level task</span>'}</div>`;
}

function renderTaskDetail(companyId, task) {
  if (!task) return emptyState('No task selected.');
  return `
    <div class="section-head">
      <div><h2>${h(task.title)}</h2><p>${h(taskContextLabel(task, companyId))}</p></div>
      <div class="detail-actions">
        ${can('tasks.manage', companyId) ? `
          <a class="btn" href="${appHref(taskPath({ ...(task.project_id ? { job_id: task.project_id } : {}), task_id: task.id, edit: '1' }, companyId))}" data-router>Edit</a>
          <button class="btn danger" type="button" data-action="task-delete" data-task-id="${h(task.id)}"><i class="ti ti-trash"></i>Delete</button>
        ` : ''}
      </div>
    </div>
    ${renderTaskContextLinks(task, companyId)}
    ${contractRows([
      ['Status', statusLabel(task.status)],
      ['Priority', titleCase(task.priority)],
      ['Type', taskTypeLabel(task.type)],
      ['Assignee', memberName(task.assignee_id)],
      ['Due', formatDate(task.due)],
      ['Repeats', describeRecurrence(task.recurrence) || 'Does not repeat'],
    ])}
    <div class="detail-copy"><strong>Description</strong><p>${h(task.description || 'No description yet.')}</p></div>
  `;
}

function renderTaskDeleteModal() {
  const task = (state.tasks || []).find((t) => t.id === state.taskDeleteId);
  const title = task?.title || 'this task';
  const content = `
    <p class="modal-lead">Delete <b>${h(title)}</b>? This cannot be undone.</p>
    <div class="modal-actions">
      <button class="btn" type="button" data-action="close-modal">Cancel</button>
      <button class="btn danger" type="button" data-action="task-delete-confirm"><i class="ti ti-trash"></i>Delete task</button>
    </div>`;
  return renderModalShell('Task', 'Delete task', content, '');
}

const AUTOMATION_OBJECT_LABELS = [['deal', 'Deal / quote'], ['contact', 'Contact'], ['task', 'Task'], ['job', 'Job']];
const AUTOMATION_EVENT_LABELS = [
  ['stage_is', 'reaches a stage'],
  ['status_is', 'changes to a status'],
  ['completed', 'is completed'],
  ['created', 'is created'],
];

function renderAutomationsPage(route, companyId) {
  const canManage = can('settings.manage', companyId);
  const rules = companyAutomations(companyId);
  const ui = state.automationUi;
  const editing = ui.creating || ui.editingId
    ? (ui.editingId ? rules.find((r) => r.id === ui.editingId) : null)
    : null;

  if (ui.creating || ui.editingId) {
    return `
      <section class="tool-page automations-page">
        ${workspaceHeader('Automations', 'Trigger → action rules that run when your CRM records change.', '')}
        <section class="panel automation-editor">
          ${renderAutomationEditor(companyId, editing)}
        </section>
      </section>`;
  }

  const list = rules.length ? rules.map((rule) => `
    <div class="automation-card ${rule.enabled ? '' : 'disabled'}">
      <div class="automation-card-main">
        <div class="automation-card-head">
          <strong>${h(rule.name)}</strong>
          ${rule.enabled ? '' : '<span class="automation-off">Off</span>'}
        </div>
        <p class="automation-desc">${h(describeAutomation(rule))}</p>
      </div>
      ${canManage ? `<div class="automation-card-acts">
        <button class="btn btn-compact" type="button" data-action="automation-toggle" data-id="${h(rule.id)}">${rule.enabled ? 'Disable' : 'Enable'}</button>
        <button class="btn btn-compact" type="button" data-action="automation-edit" data-id="${h(rule.id)}"><i class="ti ti-pencil"></i>Edit</button>
        <button class="btn btn-compact danger" type="button" data-action="automation-delete" data-id="${h(rule.id)}" aria-label="Delete automation"><i class="ti ti-trash"></i></button>
      </div>` : ''}
    </div>`).join('') : emptyState('No automations yet. Create one to auto-create tasks when deals, contacts, or jobs change.');

  return `
    <section class="tool-page automations-page">
      ${workspaceHeader('Automations', 'Trigger → action rules that run when your CRM records change.',
        canManage ? '<button class="btn btn-primary" type="button" data-action="automation-new"><i class="ti ti-plus"></i>New automation</button>' : '')}
      <section class="automation-list">${list}</section>
    </section>`;
}

// Inline create/edit form. A rule = one trigger + one create_task action (the
// highest-value shape); the engine supports more, but the editor stays focused.
function renderAutomationEditor(companyId, rule) {
  const t = rule?.trigger || { object: 'deal', event: 'stage_is', value: '' };
  const action = (rule?.actions || []).find((a) => a.type === 'create_task') || { title: '', due_offset_days: 2, priority: 'medium' };
  return `
    <form class="automation-form" data-automation-form>
      <input type="hidden" name="id" value="${h(rule?.id || '')}" />
      ${field('Automation name', 'name', rule?.name || '', true)}
      <div class="automation-when">
        <span class="automation-when-label">When a</span>
        ${selectField('Record', 'object', t.object, AUTOMATION_OBJECT_LABELS)}
        ${selectField('Event', 'event', t.event, AUTOMATION_EVENT_LABELS)}
        ${field('Target stage / status', 'value', t.value || '', false, 'text', '', 'placeholder="e.g. Won"')}
      </div>
      <p class="automation-hint muted">Leave the target blank for “is created” / “is completed”. A stage trigger fires once, when the record enters that stage.</p>
      <div class="automation-then">
        <span class="automation-then-label">Then create a task</span>
        ${field('Task title', 'task_title', action.title || '', true, 'text', '', 'placeholder="Kick off {{name}}"')}
        <div class="automation-then-row">
          ${field('Due in (days)', 'due_offset_days', String(action.due_offset_days ?? 2), false, 'number', '', 'min="0" max="365"')}
          ${selectField('Priority', 'priority', action.priority || 'medium', TASK_PRIORITIES.map((p) => [p, titleCase(p)]))}
        </div>
      </div>
      <p class="automation-hint muted">Use <code>{{name}}</code> in the title to insert the record’s name.</p>
      <div class="form-actions">
        <button class="btn btn-primary" type="submit"><i class="ti ti-check"></i>${rule ? 'Save automation' : 'Create automation'}</button>
        <button class="btn" type="button" data-action="automation-cancel">Cancel</button>
      </div>
    </form>`;
}

// A compact "repeats" chip for a task row. Empty string when the task is one-off.
function recurrenceBadge(recurrence) {
  const label = describeRecurrence(recurrence);
  if (!label) return '';
  return `<span class="task-repeat-badge" title="${h(label)}"><i class="ti ti-repeat" aria-hidden="true"></i>${h(label)}</span>`;
}

// Options for the task "Repeat" dropdown. Includes the task's current rule even
// when it's an uncommon one (e.g. a weekday variant from the command bar), so
// editing a task never silently drops its recurrence.
function recurrenceSelectOptions(current) {
  const base = [
    ['', 'Does not repeat'],
    ['daily:1', 'Every day'],
    ['weekly:1', 'Every week'],
    ['weekly:2', 'Every 2 weeks'],
    ['monthly:1', 'Every month'],
    ['monthly:3', 'Every 3 months'],
    ['yearly:1', 'Every year'],
  ];
  const cur = current ? serializeRecurrence(deserializeRecurrence(current)) : '';
  if (cur && !base.some(([value]) => value === cur)) base.push([cur, describeRecurrence(cur)]);
  return base;
}


function renderFilesPage(route, companyId) {
  const folder = route.params.get('folder') || state.driveFolder || 'home';
  state.driveFolder = folder;
  const job = route.jobId ? jobById(route.jobId) : null;
  const files = filteredDriveFiles(companyId, folder, job?.id || '');
  const canManageFiles = can('files.manage', companyId);
  ensureFileThumbnails(files);
  return `
    <section class="tool-page drive-page">
      <section class="drive-app panel">
        <header class="drive-topbar">
          <div class="drive-location">
            <span class="drive-logo"><i class="ti ti-folder"></i></span>
            <div>
              <strong>${h(job ? job.name : 'Company Drive')}</strong>
              <small>${h(job ? `${job.client_name || companyName(companyId)} file workspace` : `${companyName(companyId)} file manager`)}</small>
            </div>
          </div>
          <label class="drive-search">
            <i class="ti ti-search"></i>
            <input data-file-search value="${h(state.fileQuery)}" placeholder="Search drive" aria-label="Search drive" />
          </label>
          <div class="drive-actions">
            ${canManageFiles ? `
              <button class="btn" type="button" data-action="open-folder-form"><i class="ti ti-folder-plus"></i>New folder</button>
              <button class="btn" type="button" data-action="open-file-upload"><i class="ti ti-upload"></i>Upload</button>
            ` : ''}
            <button class="btn icon-only" type="button" data-action="refresh-data" title="Refresh" aria-label="Refresh"><i class="ti ti-refresh"></i></button>
          </div>
        </header>
        <div class="drive-shell drive-shell-compact">
          <div class="drive-main">
            <section class="drive-crumb-row">
              <nav class="breadcrumbs" aria-label="Drive location">
                <a href="${appHref(companyPath('files', {}, companyId))}" data-router>${h(companyName(companyId))}</a>
                ${folder !== 'home' ? driveBreadcrumbTrail(companyId, folder, job) : ''}
                ${job ? `<span>/</span><strong>${h(job.name)}</strong>` : ''}
              </nav>
              <div class="drive-compact-controls">
                <div class="segmented" role="group" aria-label="Drive view">
                  <button class="${state.driveView === 'grid' ? 'active' : ''}" type="button" data-action="set-drive-view" data-view="grid"><i class="ti ti-layout-grid"></i>Icons</button>
                  <button class="${state.driveView === 'list' ? 'active' : ''}" type="button" data-action="set-drive-view" data-view="list"><i class="ti ti-list-details"></i>Details</button>
                </div>
              </div>
            </section>
            ${renderDriveExplorer(companyId, folder, job, files)}
          </div>
        </div>
      </section>
    </section>
  `;
}

function renderDriveExplorer(companyId, folder, job, files) {
  const folders = driveExplorerFolders(companyId, folder, job);
  const items = folders.map((item) => ({ kind: 'folder', ...item })).concat(files.map((file) => ({ kind: 'file', file })));
  const title = job ? job.name : folder === 'home' ? 'This folder' : folderLabel(folder);
  const selCount = (state.selectedFileIds || []).filter((id) => files.some((f) => f.id === id)).length;
  const allSelected = files.length > 0 && selCount === files.length;
  return `
    <section class="drive-section-title">
      <div><h3>${h(title)}</h3><span>${folders.length} folder${folders.length === 1 ? '' : 's'} / ${files.length} file${files.length === 1 ? '' : 's'}</span></div>
      ${files.length ? `<div class="drive-select-bar">
        ${selCount ? `<span>${selCount} selected</span>` : ''}
        <button class="btn btn-compact" type="button" data-action="files-select-all"><i class="ti ti-checks"></i>${allSelected ? 'Deselect all' : 'Select all'}</button>
        ${selCount ? `<button class="btn btn-compact" type="button" data-action="files-clear-selection"><i class="ti ti-x"></i>Clear</button><button class="btn btn-compact" type="button" data-action="files-copy"><i class="ti ti-copy"></i>Copy</button><button class="btn btn-compact" type="button" data-action="files-move"><i class="ti ti-arrow-move-right"></i>Move</button><button class="btn btn-compact danger" type="button" data-action="files-delete"><i class="ti ti-trash"></i>Delete</button>` : ''}
      </div>` : ''}
    </section>
    ${state.driveView === 'list' ? renderExplorerDetails(items) : renderExplorerIcons(items)}
  `;
}

function renderExplorerDetails(items) {
  return `
    <div class="explorer-table" role="table" aria-label="File explorer">
      <div class="explorer-head" role="row">
        <span>Name</span>
        <span>Date modified</span>
        <span>Type</span>
        <span>Size</span>
      </div>
      ${items.map((item) => item.kind === 'folder' ? renderFolderRow(item) : renderFileRow(item.file)).join('') || emptyState('This folder is empty.')}
    </div>
  `;
}

function renderExplorerIcons(items) {
  return `
    <section class="drive-folder-grid explorer-grid">
      ${items.map((item) => item.kind === 'folder' ? renderFolderTile(item) : renderFileTile(item.file)).join('') || emptyState('This folder is empty.')}
    </section>
  `;
}

function renderFolderTile(folder) {
  return `
    <a class="drive-folder-card explorer-folder" href="${h(folder.href)}" data-router>
      <span class="drive-folder-icon">${folderIconAsset(folder, folder.name)}</span>
      <strong>${h(folder.name)}</strong>
      <em>${h(folder.countLabel || '0 items')}</em>
    </a>
  `;
}

function renderFolderRow(folder) {
  return `
    <a class="explorer-row folder-row-live" href="${h(folder.href)}" data-router role="row">
      <span class="explorer-name"><span class="file-type folder">${folderIconAsset(folder, folder.name)}</span><strong>${h(folder.name)}</strong></span>
      <span>${h(folder.updatedLabel || '')}</span>
      <span>Folder</span>
      <span>${h(folder.countLabel || '')}</span>
    </a>
  `;
}

function renderFileRow(file) {
  const selected = (state.selectedFileIds || []).includes(file.id);
  return `
    <div class="explorer-row ${selected ? 'selected ' : ''}${file.id === state.selectedFileId ? 'active' : ''}" role="row">
      <span class="explorer-name" role="cell">
        <button class="file-check ${selected ? 'on' : ''}" type="button" data-action="toggle-file-select" data-file-id="${h(file.id)}" title="Select file" aria-label="Select ${h(file.file_name)}" aria-pressed="${selected ? 'true' : 'false'}"><i class="ti ${selected ? 'ti-checkbox' : 'ti-square'}"></i></button>
        <button class="explorer-file-open" type="button" data-action="select-file" data-file-id="${h(file.id)}" aria-label="Open ${h(file.file_name)}">${fileTypeBadge(file)}<strong>${h(file.file_name)}</strong></button>
      </span>
      <span role="cell">${formatDate(file.updated_at || file.created_at)}</span>
      <span role="cell">${h(fileTypeLabel(file))}</span>
      <span role="cell">${formatBytes(file.size_bytes)}</span>
    </div>
  `;
}

function fileTypeBadge(file) {
  const kind = fileTypeKind(file);
  if (file.signed_url && kind === 'image') {
    return `<span class="file-type image-thumb"><img src="${h(file.signed_url)}" alt="" loading="lazy" /></span>`;
  }
  if (file.thumb_url && kind === 'pdf') {
    return `<span class="file-type image-thumb"><img src="${h(file.thumb_url)}" alt="" loading="lazy" /></span>`;
  }
  if (file.signed_url && kind === 'video') {
    return `<span class="file-type video-thumb"><video src="${h(file.signed_url)}#t=0.1" muted preload="metadata" playsinline></video><i class="ti ti-player-play-filled"></i></span>`;
  }
  return `
    <span class="file-type ${h(fileTypeClass(file))}">
      ${fileIconAsset(file, fileTypeLabel(file))}
      <small>${h(fileTypeShortLabel(file))}</small>
    </span>
  `;
}

function renderFileTile(file) {
  const selected = (state.selectedFileIds || []).includes(file.id);
  return `
    <article class="file-card-live ${selected ? 'selected ' : ''}${file.id === state.selectedFileId ? 'active' : ''}">
      <button class="file-check tile ${selected ? 'on' : ''}" type="button" data-action="toggle-file-select" data-file-id="${h(file.id)}" title="Select file" aria-label="Select ${h(file.file_name)}" aria-pressed="${selected ? 'true' : 'false'}"><i class="ti ${selected ? 'ti-checkbox' : 'ti-square'}"></i></button>
      <button class="file-card-open" type="button" data-action="select-file" data-file-id="${h(file.id)}" aria-label="Open ${h(file.file_name)}">
        <span class="file-thumb">${fileThumb(file)}</span>
        <strong>${h(file.file_name)}</strong>
        <span>${h(fileTypeLabel(file))} / ${formatBytes(file.size_bytes)}</span>
      </button>
    </article>
  `;
}

function renderFileDetails(file, companyId) {
  const canManageFiles = can('files.manage', companyId);
  if (!file) {
    return `
      <div class="file-detail-preview"><span class="file-doc-icon large">${folderIconAsset({ id: 'home', name: companyName(companyId) }, 'Company drive')}</span></div>
      <h3>${h(companyName(companyId))} Drive</h3>
      <p>Pick a file to see metadata, job context, storage path, and actions.</p>
      <div class="file-detail-list">
        ${detailRow('Company folders', DRIVE_FOLDERS.length)}
        ${detailRow('Job folders', companyJobs(companyId).length)}
        ${detailRow('Visible files', filteredDriveFiles(companyId, state.driveFolder).length)}
      </div>
    `;
  }
  return `
    <div class="file-detail-preview">${fileThumb(file, true)}</div>
    <h3>${h(file.file_name)}</h3>
    <p>${h(file.notes || jobById(file.job_id)?.name || folderLabel(file.folder))}</p>
    <div class="file-detail-list">
      ${detailRow('Category', file.category || folderLabel(file.folder))}
      ${detailRow('Job', jobById(file.job_id)?.name || 'Company shared')}
      ${detailRow('Uploaded by', file.uploaded_by_label || 'Questbase')}
      ${detailRow('Uploaded', formatDate(file.created_at))}
      ${detailRow('Size', formatBytes(file.size_bytes))}
      ${detailRow('Storage path', file.object_path || 'Metadata only')}
    </div>
    <div class="file-detail-actions">
      <button class="btn" type="button" data-action="download-file" data-file-id="${h(file.id)}"><i class="ti ti-download"></i>Download</button>
      ${canManageFiles ? `<button class="btn danger" type="button" data-action="delete-file" data-file-id="${h(file.id)}"><i class="ti ti-trash"></i>Delete</button>` : ''}
    </div>
  `;
}

function renderFileViewer(file, companyId) {
  if (file && !file.signed_url && file.object_path) ensureFileSignedUrl(file);
  const canManageFiles = can('files.manage', companyId);
  const zoomable = Boolean(file.signed_url) && ['image', 'video'].includes(fileTypeClass(file));
  return `
    <section class="file-viewer-layout">
      <div class="file-viewer-stage ${zoomable ? 'is-zoomable' : ''}" ${zoomable ? 'data-zoomable' : ''}>
        ${renderFilePreview(file)}
        ${zoomable ? `
          <span class="file-zoom-hint">Ctrl + scroll to zoom · drag to pan · double-click to reset</span>
          <div class="file-zoom-controls">
            <button type="button" data-zoom="out" title="Zoom out"><i class="ti ti-minus"></i></button>
            <span data-zoom-level>100%</span>
            <button type="button" data-zoom="in" title="Zoom in"><i class="ti ti-plus"></i></button>
            <button type="button" data-zoom="reset" title="Reset zoom"><i class="ti ti-arrows-minimize"></i></button>
          </div>` : ''}
      </div>
      <aside class="file-viewer-meta">
        <div class="file-open-head">
          ${fileThumb(file)}
          <div>
            <strong>${h(file.file_name)}</strong>
            <span>${h(fileTypeLabel(file))} / ${formatBytes(file.size_bytes)}</span>
          </div>
        </div>
        <div class="file-detail-list">
          ${detailRow('Location', folderLabel(file.folder))}
          ${detailRow('Job', jobById(file.job_id)?.name || 'Company shared')}
          ${detailRow('Uploaded by', file.uploaded_by_label || 'Questbase')}
          ${detailRow('Modified', formatDate(file.updated_at || file.created_at))}
          ${detailRow('Storage', file.object_path || 'Metadata only')}
        </div>
        <div class="file-detail-actions">
          <button class="btn" type="button" data-action="download-file" data-file-id="${h(file.id)}"><i class="ti ti-download"></i>Download</button>
          ${canManageFiles ? `<button class="btn danger" type="button" data-action="delete-file" data-file-id="${h(file.id)}"><i class="ti ti-trash"></i>Delete</button>` : ''}
        </div>
      </aside>
    </section>
  `;
}

function renderFilePreview(file) {
  const type = fileTypeClass(file);
  const url = file.signed_url;
  if (url && type === 'image') return `<img class="file-preview-media" src="${h(url)}" alt="${h(file.file_name)}" draggable="false" />`;
  if (url && type === 'video') return `<video class="file-preview-media file-preview-video" src="${h(url)}" controls playsinline preload="metadata"></video>`;
  if (url && type === 'audio') return `<div class="file-preview-audio-wrap"><div class="file-preview-audio-ico"><i class="ti ti-music"></i></div><strong>${h(file.file_name)}</strong><audio src="${h(url)}" controls preload="metadata"></audio></div>`;
  if (url && type === 'pdf') return `<iframe class="file-preview-frame" src="${h(url)}#toolbar=1&navpanes=0" title="${h(file.file_name)}"></iframe>`;
  if (url && type === 'text') return `<iframe class="file-preview-frame text" src="${h(url)}" title="${h(file.file_name)}"></iframe>`;
  if (['doc', 'sheet', 'presentation'].includes(type) && url) {
    return `<iframe class="file-preview-frame" src="https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(url)}" title="${h(file.file_name)}"></iframe>`;
  }
  if (file.object_path && !file._urlFailed) {
    return `
      <div class="file-preview-empty">
        <span class="btn-spinner file-preview-spinner"></span>
        <strong>Loading ${h(fileTypeLabel(file))} preview…</strong>
        <p>Fetching a secure link to this file.</p>
      </div>
    `;
  }
  if (file.object_path && file._urlFailed) {
    return `
      <div class="file-preview-empty">
        ${fileThumb(file, true)}
        <strong>Preview unavailable</strong>
        <p>Couldn't load a preview for this file. Use <b>Download</b> to open it.</p>
      </div>
    `;
  }
  return `
    <div class="file-preview-empty">
      ${fileThumb(file, true)}
      <strong>${h(fileTypeLabel(file))} preview</strong>
      <p>This is a metadata-only file record. Upload the actual file object to preview it here.</p>
      ${file.notes ? `<pre>${h(file.notes)}</pre>` : ''}
    </div>
  `;
}

// Bind Ctrl+scroll zoom, drag-to-pan, and the zoom controls on the file viewer.
function mountFileViewer() {
  const stage = document.querySelector('.file-viewer-stage[data-zoomable]');
  if (!stage || stage.dataset.zoomBound) return;
  const media = stage.querySelector('.file-preview-media');
  if (!media) return;
  stage.dataset.zoomBound = '1';
  let scale = 1;
  let ox = 0;
  let oy = 0;
  const level = stage.querySelector('[data-zoom-level]');
  const apply = () => {
    scale = Math.min(6, Math.max(1, scale));
    if (scale === 1) { ox = 0; oy = 0; }
    media.style.transform = `translate(${ox}px, ${oy}px) scale(${scale})`;
    stage.classList.toggle('zoomed', scale > 1);
    if (level) level.textContent = `${Math.round(scale * 100)}%`;
  };
  const zoomBy = (factor) => { scale *= factor; apply(); };
  stage.addEventListener('wheel', (event) => {
    if (!event.ctrlKey) return;
    event.preventDefault();
    zoomBy(event.deltaY < 0 ? 1.12 : 0.9);
  }, { passive: false });
  stage.querySelectorAll('[data-zoom]').forEach((btn) => btn.addEventListener('click', (event) => {
    event.preventDefault();
    const kind = btn.dataset.zoom;
    if (kind === 'in') zoomBy(1.25);
    else if (kind === 'out') zoomBy(0.8);
    else { scale = 1; ox = 0; oy = 0; apply(); }
  }));
  let dragging = false;
  let sx = 0;
  let sy = 0;
  stage.addEventListener('pointerdown', (event) => {
    if (scale <= 1 || event.button !== 0 || event.target.closest('[data-zoom], video, audio')) return;
    dragging = true; sx = event.clientX - ox; sy = event.clientY - oy;
    try { stage.setPointerCapture(event.pointerId); } catch { /* noop */ }
  });
  stage.addEventListener('pointermove', (event) => { if (!dragging) return; ox = event.clientX - sx; oy = event.clientY - sy; apply(); });
  const endDrag = () => { dragging = false; };
  stage.addEventListener('pointerup', endDrag);
  stage.addEventListener('pointercancel', endDrag);
  media.addEventListener('dblclick', () => { scale = scale > 1 ? 1 : 2; if (scale === 1) { ox = 0; oy = 0; } apply(); });
}

