function renderApprovalsPage(companyId) {
  const items = approvalItems(companyId);
  const formItems = items.filter((item) => item.type === 'Form approval');
  const taskItems = items.filter((item) => item.type === 'Task review');
  const accessItems = items.filter((item) => item.type === 'Access request');
  return `
    <section class="tool-page operations-page">
      ${workspaceHeader('Approvals', 'Company review queue for forms, task handoffs, and access requests.', `
        <a class="btn" href="${appHref(companyPath('forms', {}, companyId))}" data-router><i class="ti ti-clipboard-list"></i>Forms</a>
        <a class="btn btn-primary" href="${appHref(companyPath('tasks', {}, companyId))}" data-router><i class="ti ti-list-check"></i>Tasks</a>
      `)}
      ${renderOperationsTabs(companyId, 'approvals')}
      <section class="metric-grid operations-metrics">
        ${metricCard('Open approvals', items.length)}
        ${metricCard('Forms', formItems.length)}
        ${metricCard('Task reviews', taskItems.length)}
        ${metricCard('Access', accessItems.length)}
      </section>
      <section class="panel">
        <div class="section-head"><div><h2>Approval queue</h2><p>One calm list instead of a heavy dashboard.</p></div></div>
        <div class="data-table approval-table">
          <div class="table-head"><span>Item</span><span>Type</span><span>Owner</span><span>Status</span><span>Updated</span></div>
          ${items.map((item) => `
            <a class="table-row" href="${appHref(item.href)}" data-router>
              <span><strong>${h(item.title)}</strong><small>${h(item.meta)}</small></span>
              <span>${h(item.type)}</span>
              <span>${h(item.owner)}</span>
              <span>${h(item.status)}</span>
              <span>${formatDate(item.updatedAt)}</span>
            </a>
          `).join('') || emptyState('No approvals need attention right now.')}
        </div>
      </section>
    </section>
  `;
}

function renderPlannedPage(name) {
  return `
    ${workspaceHeader(titleCase(name || 'workspace'), 'This module will use the same company workspace shell when wired.', '')}
    <section class="panel">
      ${emptyState('Module data model pending.')}
    </section>
  `;
}

function renderAuthModal(returnUrl, inviteToken, authEnabled) {
  const inviteLookup = inviteLookupForToken(inviteToken);
  return `
    <div class="modal-overlay">
      <div class="modal-panel landing-auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-modal-title">
        <div class="modal-head landing-auth-head">
          <div>
            <div class="eyebrow">${authEnabled ? 'Tenant access' : 'Local access'}</div>
            <h2 id="auth-modal-title">${inviteToken ? 'Join workspace' : 'Questbase'}</h2>
          </div>
          <button class="btn" type="button" data-action="close-auth-modal">Close</button>
        </div>
        <div class="landing-auth-body">
          <div class="auth-modal-note">${authEnabled ? 'Owners create workspaces. Workers join by invite.' : 'Supabase auth is switched off while the company workspace foundation is stabilized.'}</div>
          ${inviteToken ? `
            <div class="invite-banner">
              <strong>${inviteLookup ? `Invite found for ${h(inviteLookup.company_name || 'workspace')}` : 'Workspace invite'}</strong>
              <span>${inviteLookup ? `${h(inviteLookup.email)} can create an account or sign in to join.` : 'Create an account with the invited email, or sign in if that email already has a Questbase account.'}</span>
            </div>
          ` : ''}
          ${authEnabled ? `
            ${renderAuthLanePicker(inviteToken)}
            ${renderSupabaseAuthForm(returnUrl)}
          ` : ''}
          ${renderDemoModeLauncher(returnUrl)}
          ${CONFIG.localLoginEnabled && authEnabled ? `
            <details class="demo-login-details">
              <summary>Legacy demo credentials</summary>
              ${renderLocalLoginForm(returnUrl)}
            </details>
          ` : ''}
        </div>
      </div>
    </div>
  `;
}

function closeLandingAuthModal() {
  state.loginError = '';
  state.authMessage = '';
  state.authBusy = false;
  navigate('/');
  return true;
}

function normalizeAuthMode(value, inviteToken = '') {
  const mode = String(value || '').toLowerCase().trim();
  if (inviteToken && !mode) return 'register';
  if (['signin', 'register', 'invite', 'request', 'forgot', 'recovery'].includes(mode)) return mode;
  if (mode === 'business') return 'register';
  if (mode === 'worker') return inviteToken ? 'register' : 'invite';
  return '';
}

function renderAuthLanePicker(inviteToken = '') {
  const active = state.authMode;
  if (['forgot', 'recovery'].includes(active)) return '';
  const options = inviteToken
    ? [
      ['signin', 'Sign in'],
      ['register', 'Create invited account'],
    ]
    : [
      ['signin', 'Sign in'],
      ['register', 'Create workspace'],
      ['invite', 'Join with invite'],
    ];
  return `
    <nav class="auth-mode-bar" aria-label="Account access">
      ${options.map(([mode, label]) => `
        <button class="${active === mode ? 'active' : ''}" type="button" data-action="set-auth-mode" data-auth-mode="${h(mode)}">${h(label)}</button>
      `).join('')}
    </nav>
  `;
}

function renderPasswordField({ name = 'password', label = 'Password', autocomplete = 'current-password', confirm = false } = {}) {
  const inputName = confirm ? 'password_confirm' : name;
  return `
    <label>${h(label)}
      <span class="password-field">
        <input name="${h(inputName)}" type="password" autocomplete="${h(autocomplete)}" minlength="${PASSWORD_MIN_LENGTH}" required />
        <button type="button" data-action="toggle-password" aria-label="Show password" title="Show password"><i class="ti ti-eye"></i></button>
      </span>
    </label>
  `;
}

function renderPasswordRequirements() {
  return `<ul class="password-requirements">${passwordRequirements().map((item) => `<li>${h(item)}</li>`).join('')}</ul>`;
}

function authSubmitButton(label, busyLabel = 'Working...') {
  return `<button class="btn btn-primary full" type="submit" ${state.authBusy ? 'disabled aria-busy="true"' : ''}>${h(state.authBusy ? busyLabel : label)}</button>`;
}

function renderDemoModeLauncher(returnUrl) {
  if (!CONFIG.demoModeEnabled) return '';
  return `
    <details class="demo-mode-details">
      <summary>Demo mode</summary>
      <section class="demo-mode-box">
        <div>
          <strong>Read-only sample workspace</strong>
          <span>Explore sample contacts, quotes, jobs, files, forms, approvals, and billing without saving changes.</span>
        </div>
        <button class="btn full" type="button" data-action="start-demo-mode" data-return-url="${h(returnUrl)}">Open read-only demo</button>
      </section>
    </details>
  `;
}

// Inline provider logos — the CSP blocks external images, so these ship as SVG.
const OAUTH_PROVIDER_META = {
  google: {
    label: 'Continue with Google',
    logo: '<svg width="17" height="17" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.27-4.74 3.27-8.1z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="#FBBC05" d="M5.84 14.1c-.22-.66-.35-1.36-.35-2.1s.13-1.44.35-2.1V7.06H2.18A11 11 0 0 0 1 12c0 1.77.43 3.45 1.18 4.94l3.66-2.84z"/><path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.06l3.66 2.84c.87-2.6 3.3-4.52 6.16-4.52z"/></svg>',
  },
  apple: {
    label: 'Continue with Apple',
    logo: '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M18.71 19.5c-.83 1.24-1.71 2.45-3.05 2.47-1.34.03-1.77-.79-3.29-.79-1.53 0-2 .77-3.27.82-1.31.05-2.3-1.32-3.14-2.53C4.25 17 2.94 12.45 4.7 9.39c.87-1.52 2.43-2.48 4.12-2.51 1.28-.02 2.5.87 3.29.87.78 0 2.26-1.07 3.81-.91.65.03 2.47.26 3.64 1.98-.09.06-2.17 1.28-2.15 3.81.03 3.02 2.65 4.03 2.68 4.04-.03.07-.42 1.44-1.38 2.83M13 3.5c.73-.83 1.94-1.46 2.94-1.5.13 1.17-.34 2.35-1.04 3.19-.69.85-1.83 1.51-2.95 1.42-.15-1.15.41-2.35 1.05-3.11z"/></svg>',
  },
};
// Kick off a provider OAuth flow. Supabase redirects the browser to the provider
// and back to redirectTo, where initializeAuth() picks up the session on load —
// so this is one unified path for both sign-up and sign-in. The redirectTo URL
// must be in the Supabase "Redirect URLs" allowlist, and the provider must be
// enabled + credentialed in the dashboard, or Supabase returns an error here.
async function startOAuthSignIn(provider) {
  if (!OAUTH_PROVIDER_META[provider]) return;
  const client = createSupabaseClient();
  if (!client) { showToast('Sign-in is unavailable in this mode.', 'error', 'Account'); return; }
  const label = provider === 'apple' ? 'Apple' : 'Google';
  try {
    // The provider sends the browser away and brings it back, and anything not in redirectTo
    // is gone by then. Without the invite riding along, someone joining by invitation would
    // return signed in but with no invitation to accept -- and no way back to it.
    const inviteToken = String(state.route?.params?.get('invite') || '').trim();
    const redirectTo = `${authOrigin()}${BASE_PATH || ''}/${inviteToken ? `?invite=${encodeURIComponent(inviteToken)}` : ''}`;
    const { error } = await client.auth.signInWithOAuth({ provider, options: { redirectTo } });
    if (error) throw error;
    // Success redirects the browser to the provider — nothing more to do here.
  } catch (error) {
    const raw = String(error?.message || '');
    const notReady = /not enabled|provider.*disabled|unsupported provider|validation_failed/i.test(raw);
    showToast(notReady ? `${label} sign-in isn't switched on yet — finish the ${label} setup in Supabase first.` : (raw || `Could not start ${label} sign-in.`), 'error', 'Account');
  }
}

// Social sign-on buttons for the auth modal. One provider button both registers
// a new user and signs in a returning one (Supabase resolves which). Hidden when
// no providers are configured.
function renderAuthOAuthButtons(invitedEmail = '') {
  const providers = CONFIG.oauthProviders.filter((p) => OAUTH_PROVIDER_META[p]);
  if (!providers.length) return '';
  return `
    <div class="auth-sso-group">
      ${providers.map((p) => `<button class="auth-sso auth-sso-${p}" type="button" data-action="oauth-signin" data-provider="${p}">${OAUTH_PROVIDER_META[p].logo}<span>${h(OAUTH_PROVIDER_META[p].label)}</span></button>`).join('')}
    </div>
    ${invitedEmail ? `
      <!-- The invitation is bound to one address and the database enforces it, so say which
           one before they pick an account rather than after: "Invite was sent to a different
           email address" is a poor way to learn you chose the wrong Google profile. -->
      <p class="auth-sso-note">Use <b>${h(invitedEmail)}</b> — the invitation is tied to that address.</p>
    ` : ''}
    <div class="auth-sso-divider"><span>or with email</span></div>`;
}

