function onPipeDragStart(event) {
  const card = event.target.closest('[draggable="true"][data-drag-kind][data-drag-id]');
  if (!card) return;
  pipeDrag = { kind: card.dataset.dragKind || '', id: card.dataset.dragId || '' };
  card.classList.add('dragging');
  event.dataTransfer?.setData('text/plain', JSON.stringify(pipeDrag));
  if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
}

function onPipeDragEnd(event) {
  event.target.closest('[data-drag-id]')?.classList.remove('dragging');
  document.querySelectorAll('.pipe-lane.drag-over, .wb-board-col.drag-over').forEach((lane) => lane.classList.remove('drag-over'));
  pipeDrag = null;
}

function onPipeDragOver(event) {
  const lane = event.target.closest('[data-drop-stage][data-drag-kind]');
  if (!lane || !pipeDrag || lane.dataset.dragKind !== pipeDrag.kind) return;
  event.preventDefault();
  lane.classList.add('drag-over');
  if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
}

function onPipeDrop(event) {
  const lane = event.target.closest('[data-drop-stage][data-drag-kind]');
  if (!lane || !pipeDrag || lane.dataset.dragKind !== pipeDrag.kind) return;
  event.preventDefault();
  const stage = lane.dataset.dropStage || '';
  const { kind, id } = pipeDrag;
  document.querySelectorAll('.pipe-lane.drag-over, .wb-board-col.drag-over').forEach((item) => item.classList.remove('drag-over'));
  pipeDrag = null;
  if (kind === 'contact') setContactStage(id, stage);
  if (kind === 'deal') setDealStage(id, stage);
  if (kind === 'job') setJobStage(id, stage);
  // App Builder records carry only their id; which app they belong to comes from the
  // board they were dropped on, so a second board on screen cannot be confused for this one.
  if (kind === 'wb-item') {
    const board = lane.closest('[data-wb-board]');
    if (board) wbSetItemStage(board.dataset.company, board.dataset.workspace, board.dataset.app, id, board.dataset.field, stage);
  }
}

/**
 * Move a record to a stage by dragging it there. Deliberately goes through the same steps
 * as editing the field in the record form -- timestamps, automations, save -- because a
 * drag is an edit, and an automation that fires when a status changes should not care how
 * the change was made.
 */
function wbSetItemStage(companyId, workspaceId, appId, itemId, fieldId, stageId) {
  if (!can('workspaces.manage', companyId)) return;
  const { workspace, app } = wbFind(companyId, workspaceId, appId);
  if (!app) return;
  const item = app.items.find((i) => i.id === itemId);
  const field = app.fields.find((f) => f.id === fieldId);
  if (!item || !field) return;
  const next = stageId || '';
  // Someone else may have deleted the stage since this board was drawn.
  if (next && !canDropOn(field, next)) { showToast('That stage no longer exists — refreshing the board.', 'local', 'Workspaces'); render(); return; }
  if ((item.values[fieldId] || '') === next) return;
  const prev = { ...item.values };
  item.values = { ...item.values, [fieldId]: next };
  const stamp = new Date().toISOString(); item.updatedAt = stamp; item.lastActivityAt = stamp;
  wbRunAutomations(companyId, workspace, app, item, 'updated', prev);
  wbSave(companyId);
  render();
}

async function signOut() {
  const draftProfileId = activeDraftProfileId();
  if (draftProfileId) {
    if (formDraftManager) formDraftManager.purgeProfile(draftProfileId);
    else formDraftManagerReady.then((manager) => manager?.purgeProfile(draftProfileId));
  }
  try { teardownGlobalRealtime(); } catch { /* ignore */ }
  if (isLiveSupabaseSession()) {
    const client = createSupabaseClient();
    if (CONFIG.questAuthEnabled && client?.auth) await client.auth.signOut();
  }
  localStorage.removeItem(SESSION_KEY);
  state.session = null;
  state.dataLoaded = false;
  state.everLoaded = false;
  navigate('/login', { replace: true });
}

function startDemoMode(returnUrl = '') {
  state.loginError = '';
  state.authMessage = '';
  state.session = buildDemoSession();
  resetDemoWorkspaceData();
  state.activeCompanyId = activeCompanyId();
  localStorage.setItem(COMPANY_KEY, state.activeCompanyId);
  writeJson(SESSION_KEY, state.session);
  state.dataLoaded = false;
  state.dataLoading = false;
  navigate(safeReturnUrl(returnUrl || appHref(companyPath('jobs', {}, activeCompanyId()))), { replace: true });
}

async function saveProfile(formNode) {
  // Saving a profile can mean uploading and compressing a photo before the row is even
  // written, which is long enough that a button doing nothing reads as a button that did not
  // work. beginSubmitting also refuses a second submit while the first is in flight.
  const done = beginSubmitting(formNode, 'Saving…');
  if (!done) return;
  try {
    await saveProfileFields(formNode);
  } finally {
    // Released on every path, including the early returns below, or a refused save leaves
    // the dialog stuck behind a permanently disabled button.
    done();
  }
}

async function saveProfileFields(formNode) {
  const data = new FormData(formNode);
  const current = activeSession().profile;
  const file = formNode.elements.avatar_file?.files?.[0] || null;
  const croppedUrl = String(data.get('avatar_cropped_url') || '').trim();
  let avatarUrl = String(data.get('avatar_url') || current.avatar_url || '').trim();
  if (croppedUrl.startsWith('data:image/')) {
    const croppedFile = dataUrlToFile(croppedUrl, `avatar-${Date.now()}.png`);
    const uploadResult = await saveProfileAvatar(croppedFile);
    if (!uploadResult.ok) return;
    avatarUrl = uploadResult.url;
  } else if (file && file.size) {
    const uploadResult = await saveProfileAvatar(file);
    if (!uploadResult.ok) return;
    avatarUrl = uploadResult.url;
  }
  let next = normalizeProfile({
    ...current,
    full_name: String(data.get('full_name') || '').trim() || current.full_name || 'Quest user',
    avatar_url: avatarUrl,
  }, current);
  if (isLiveSupabaseSession()) {
    const client = createSupabaseClient();
    if (!client) {
      showToast('Profile upload needs Supabase to be available.', 'local', 'Profile');
      return;
    }
    // Update via a SECURITY DEFINER RPC keyed on auth.uid() so the strict
    // profiles WITH CHECK (which pins role/email/etc.) can never block a user
    // from changing their own display name or avatar.
    const result = await client.rpc('update_own_profile', { p_full_name: next.full_name, p_avatar_url: next.avatar_url });
    if (result.error) {
      showToast(result.error.message || 'Profile save failed.', 'local', 'Profile');
      return;
    }
    next = normalizeProfile(Array.isArray(result.data) ? result.data[0] : result.data, next);
    if (client.auth?.updateUser) {
      await client.auth.updateUser({ data: { full_name: next.full_name, avatar_url: next.avatar_url } });
    }
    state.profiles = [next].concat(state.profiles.filter((profile) => profile.id !== next.id));
    if (next.member_id) {
      state.teamMembers = state.teamMembers.map((member) => (member.id === next.member_id ? { ...member, full_name: next.full_name, name: next.full_name, avatar_url: next.avatar_url } : member));
    }
  } else {
    writeJson(PROFILE_KEY, next);
    state.profileDraft = next;
  }
  state.session = { ...activeSession(), profile: next };
  writeJson(SESSION_KEY, state.session);
  state.modal = '';
  showToast('Profile saved.', isLiveSupabaseSession() ? 'live' : 'local', 'Profile');
  // The modal was already being cleared from state here, but nothing repainted, so it stayed
  // on screen with its own success toast in front of it until something else caused a render.
  render();
}

async function prepareProfileAvatarCrop(formNode) {
  if (!formNode) return;
  const file = formNode.elements.avatar_file?.files?.[0] || null;
  const hidden = formNode.querySelector('[data-profile-cropped-avatar]');
  if (hidden) hidden.value = '';
  if (!file) return;
  const check = await validateUpload(file, 'avatarimage');
  if (!check.ok) throw new Error(check.reason);
  // No byte cap: the crop source is downscaled to a bounded edge and the saved avatar
  // is re-encoded to a 512px square, so a large photo is compressed rather than refused.
  const image = await croppableImageFromFile(file);
  const modal = formNode.querySelector('[data-profile-avatar-crop-modal]');
  if (modal) modal.hidden = false;
  const preview = formNode.querySelector('#profile-avatar-preview');
  formNode._profileOriginalPreview = preview?.innerHTML || '';
  formNode._profileOriginalHadImage = preview?.classList.contains('has-image') || false;
  formNode._profileCropImage = image;
  formNode.querySelector('[data-profile-crop-zoom]').value = '1';
  formNode.querySelector('[data-profile-crop-x]').value = '0';
  formNode.querySelector('[data-profile-crop-y]').value = '0';
  bindProfileAvatarCropper(formNode);
  updateProfileAvatarCrop(formNode);
}

function updateProfileAvatarCrop(formNode, options = {}) {
  if (!formNode?._profileCropImage) return;
  const canvas = formNode.querySelector('[data-profile-crop-canvas]');
  const hidden = formNode.querySelector('[data-profile-cropped-avatar]');
  if (!canvas || !hidden) return;
  const ctx = canvas.getContext('2d');
  const size = canvas.width;
  const image = formNode._profileCropImage;
  const zoom = Math.max(1, Number(formNode.querySelector('[data-profile-crop-zoom]')?.value || 1));
  const offsetX = Number(formNode.querySelector('[data-profile-crop-x]')?.value || 0) / 100;
  const offsetY = Number(formNode.querySelector('[data-profile-crop-y]')?.value || 0) / 100;
  const baseScale = Math.max(size / image.naturalWidth, size / image.naturalHeight);
  const scale = baseScale * zoom;
  const drawWidth = image.naturalWidth * scale;
  const drawHeight = image.naturalHeight * scale;
  const maxOffsetX = Math.max(0, (drawWidth - size) / 2);
  const maxOffsetY = Math.max(0, (drawHeight - size) / 2);
  const drawX = (size - drawWidth) / 2 + offsetX * maxOffsetX;
  const drawY = (size - drawHeight) / 2 + offsetY * maxOffsetY;
  ctx.clearRect(0, 0, size, size);
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, size, size);
  ctx.drawImage(image, drawX, drawY, drawWidth, drawHeight);
  if (!options.commit) return;
  hidden.value = canvas.toDataURL('image/png');
  const preview = formNode.querySelector('#profile-avatar-preview');
  if (preview) preview.innerHTML = `<img src="${h(hidden.value)}" alt="" />`;
  if (preview) preview.classList.add('has-image');
}

function bindProfileAvatarCropper(formNode) {
  const stage = formNode?.querySelector('[data-profile-crop-stage]');
  if (!stage || stage.dataset.bound) return;
  stage.dataset.bound = '1';
  let dragging = false;
  let lastX = 0;
  let lastY = 0;
  stage.addEventListener('pointerdown', (event) => {
    if (!formNode._profileCropImage) return;
    dragging = true;
    lastX = event.clientX;
    lastY = event.clientY;
    stage.classList.add('dragging');
    stage.setPointerCapture?.(event.pointerId);
  });
  stage.addEventListener('pointermove', (event) => {
    if (!dragging) return;
    moveProfileAvatarCrop(formNode, event.clientX - lastX, event.clientY - lastY);
    lastX = event.clientX;
    lastY = event.clientY;
  });
  const endDrag = (event) => {
    dragging = false;
    stage.classList.remove('dragging');
    if (event?.pointerId !== undefined) stage.releasePointerCapture?.(event.pointerId);
  };
  stage.addEventListener('pointerup', endDrag);
  stage.addEventListener('pointercancel', endDrag);
}

function moveProfileAvatarCrop(formNode, deltaX, deltaY) {
  const x = formNode?.querySelector('[data-profile-crop-x]');
  const y = formNode?.querySelector('[data-profile-crop-y]');
  if (!x || !y) return;
  const nextX = Math.max(-100, Math.min(100, Number(x.value || 0) + deltaX));
  const nextY = Math.max(-100, Math.min(100, Number(y.value || 0) + deltaY));
  x.value = String(nextX);
  y.value = String(nextY);
  updateProfileAvatarCrop(formNode);
}

function applyProfileAvatarCrop(formNode) {
  updateProfileAvatarCrop(formNode, { commit: true });
  const modal = formNode?.querySelector('[data-profile-avatar-crop-modal]');
  if (modal) modal.hidden = true;
}

function cancelProfileAvatarCrop(formNode) {
  if (!formNode) return;
  const modal = formNode.querySelector('[data-profile-avatar-crop-modal]');
  const hidden = formNode.querySelector('[data-profile-cropped-avatar]');
  const file = formNode.elements.avatar_file;
  const preview = formNode.querySelector('#profile-avatar-preview');
  if (modal) modal.hidden = true;
  if (hidden) hidden.value = '';
  if (file) file.value = '';
  if (preview && formNode._profileOriginalPreview !== undefined) {
    preview.innerHTML = formNode._profileOriginalPreview;
    preview.classList.toggle('has-image', Boolean(formNode._profileOriginalHadImage));
  }
  formNode._profileCropImage = null;
}

async function saveProfileAvatar(file) {
  const check = await validateUpload(file, 'avatarimage');
  if (!check.ok) { showToast(check.reason, 'error', 'Profile'); return { ok: false, url: '' }; }
  // Compress before anything is stored or uploaded, so the source file's size never
  // matters. This also normalizes the already-cropped PNG the crop flow hands over.
  let avatarUrl = '';
  try {
    avatarUrl = await avatarDataUrlFromFile(file);
  } catch (error) {
    showToast(error.message || 'Could not read that image file.', 'local', 'Profile');
    return { ok: false, url: '' };
  }
  if (!avatarUrl) {
    showToast('Could not read that image file.', 'local', 'Profile');
    return { ok: false, url: '' };
  }
  if (state.session?.auth !== 'supabase') return { ok: true, url: avatarUrl };
  const client = createSupabaseClient();
  const profileId = activeSession().profile.id;
  // Extension and content type follow the compressed output, not the original file:
  // the ladder may have produced webp from a jpg, and a mismatched content type would
  // be rejected by the bucket's allowed_mime_types.
  const compressed = dataUrlToFile(avatarUrl, `avatar-${Date.now()}`);
  const ext = avatarFileExtension(compressed);
  const objectPath = `${profileId}/avatar-${Date.now()}.${ext}`;
  const upload = await client.storage
    .from('avatars')
    .upload(objectPath, compressed, { cacheControl: '3600', upsert: true, contentType: contentTypeFor(compressed) });
  if (upload.error) {
    showToast(upload.error.message || 'Profile picture upload failed.', 'local', 'Profile');
    return { ok: false, url: '' };
  }
  const publicResult = client.storage.from('avatars').getPublicUrl(objectPath);
  const publicUrl = publicResult.data?.publicUrl ? `${publicResult.data.publicUrl}?v=${Date.now()}` : '';
  if (!publicUrl) {
    showToast('Profile picture uploaded, but no public URL was returned.', 'local', 'Profile');
    return { ok: false, url: '' };
  }
  return { ok: true, url: publicUrl };
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error('Could not load that image.'));
    image.src = src;
  });
}

function dataUrlToFile(dataUrl, fileName) {
  const [header, payload] = String(dataUrl || '').split(',');
  const mime = header.match(/data:([^;]+)/)?.[1] || 'image/png';
  const binary = atob(payload || '');
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return new File([bytes], fileName, { type: mime });
}

function handleAuthFailure(error) {
  state.authBusy = false;
  state.loginError = error?.message || 'Account request failed. Please try again.';
  state.authMessage = '';
  render();
}

async function requestPasswordReset(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const email = String(form.email || '').trim();
  const client = createSupabaseClient();
  if (!client?.auth || !email) throw new Error('Enter the email for your Questbase account.');
  state.authBusy = true;
  state.loginError = '';
  state.authMessage = 'Sending reset link...';
  render();
  const redirectTo = `${authOrigin()}${appHref('/?auth=recovery')}`;
  const result = await client.auth.resetPasswordForEmail(email, { redirectTo });
  state.authBusy = false;
  if (result.error) {
    state.loginError = 'Password reset is temporarily unavailable. Please try again shortly.';
    state.authMessage = '';
  } else {
    state.loginError = '';
    state.authMessage = 'If an account exists for that email, a password reset link is on its way.';
  }
  render();
}

async function updateRecoveredPassword(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const password = String(form.password || '');
  const confirmation = String(form.password_confirm || '');
  const policy = await passwordPolicyAsync(password);
  if (!policy.valid) throw new Error(policy.issues[0]);
  if (password !== confirmation) throw new Error('The passwords do not match.');
  const client = createSupabaseClient();
  if (!client?.auth) throw new Error('Password recovery is unavailable in this session.');
  state.authBusy = true;
  state.loginError = '';
  state.authMessage = 'Updating password...';
  render();
  const result = await client.auth.updateUser({ password });
  if (result.error) {
    state.authBusy = false;
    state.loginError = result.error.message || 'Could not update your password.';
    state.authMessage = '';
    render();
    return;
  }
  await client.auth.signOut({ scope: 'global' });
  state.authBusy = false;
  state.authMode = 'signin';
  state.loginError = '';
  state.authMessage = 'Password updated. Sign in with your new password.';
  navigate('/?auth=signin', { replace: true });
}

async function signInWithSupabase(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const client = createSupabaseClient();
  if (!client?.auth) {
    state.loginError = 'Supabase auth is unavailable.';
    render();
    return;
  }
  state.authBusy = true;
  state.loginError = '';
  state.authMessage = 'Signing in...';
  render();
  const result = await client.auth.signInWithPassword({
    email: String(form.email || '').trim(),
    password: String(form.password || ''),
  });
  if (result.error) {
    state.authBusy = false;
    // Supabase answers "Invalid login credentials" for a wrong password, an address with no
    // account, AND an account whose email is not confirmed yet. Passed through raw it reads
    // as "your password is wrong", which is why a fresh sign-up looked broken.
    const generic = /invalid login credentials/i.test(result.error.message || '');
    state.loginError = generic
      ? 'That email and password did not match. If you just created this account, confirm it from the email we sent first — the link expires after 24 hours.'
      : result.error.message || 'Unable to sign in.';
    state.authMessage = '';
    render();
    return;
  }
  await setSupabaseSession(result.data.session);
  state.authBusy = false;
  if (form.invite_token) {
    await acceptCompanyInvite(form.invite_token, form.return_url);
    return;
  }
  state.authMessage = '';
  state.dataLoaded = false;
  navigate(safeReturnUrl(form.return_url || appHref(companyPath('jobs', {}, defaultCompanyId()))), { replace: true });
}

async function submitInviteCode(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const inviteCode = String(form.invite_code || '').trim();
  if (!inviteCode) {
    state.loginError = 'Invite code is required.';
    render();
    return;
  }
  state.loginError = '';
  state.authMessage = 'Checking invite code...';
  state.authMode = 'register';
  render();
  const lookup = await lookupInviteCode(inviteCode);
  if (lookup?.missing) {
    state.loginError = 'Invite code was not found or is no longer pending.';
    state.authMessage = '';
    state.authMode = 'invite';
    render();
    return;
  }
  if (lookup?.status && lookup.status !== 'pending') {
    state.loginError = `This invite is ${lookup.status}. Ask your company admin for a new code.`;
    state.authMessage = '';
    state.authMode = 'invite';
    render();
    return;
  }
  if (lookup?.expires_at && Date.parse(lookup.expires_at) <= Date.now()) {
    state.loginError = 'This invite code expired. Ask your company admin for a new code.';
    state.authMessage = '';
    state.authMode = 'invite';
    render();
    return;
  }
  if (lookup) {
    state.inviteLookup = lookup;
    state.authMessage = `Invite found for ${lookup.email}.`;
  } else {
    state.authMessage = '';
  }
  const params = new URLSearchParams({ invite: inviteCode });
  const returnUrl = safeReturnUrl(form.return_url || '');
  if (returnUrl) params.set('return_url', returnUrl);
  params.set('mode', 'register');
  navigate(`/login?${params.toString()}`, { replace: true });
}

async function lookupInviteCode(inviteCode) {
  const token = String(inviteCode || '').trim();
  if (!token) return null;
  // Invite lookup goes through a rate-limited server endpoint (direct anon RPC
  // is revoked) so tokens can't be enumerated.
  let row = null;
  try {
    const response = await fetch('/api/public-invite-lookup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ invite_token: token }),
    });
    if (!response.ok) return null;
    const payload = await response.json().catch(() => ({}));
    row = payload.invite;
  } catch {
    return null;
  }
  if (!row) return { missing: true };
  return {
    token,
    company_id: canonicalCompanyId(row.company_id || ''),
    company_name: String(row.company_name || row.company_id || '').trim(),
    email: String(row.email || '').trim(),
    status: String(row.status || '').trim(),
    expires_at: row.expires_at || '',
  };
}

async function registerWorkspace(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const client = createSupabaseClient();
  if (!client?.auth) {
    state.loginError = 'Supabase auth is unavailable.';
    render();
    return;
  }
  const email = String(form.email || '').trim();
  const password = String(form.password || '');
  const fullName = String(form.full_name || '').trim();
  const inviteToken = String(form.invite_token || '').trim();
  const companyName = String(form.company_name || '').trim();
  const iconKey = workspaceIconOption(form.icon_key).key;
  if (!email || !password || !fullName || (!inviteToken && !companyName)) {
    state.loginError = inviteToken ? 'Name, email, and password are required.' : 'Name, email, password, and company workspace are required.';
    render();
    return;
  }
  // Local rules first so they fail instantly; only then pay for the network round-trip.
  const policy = passwordPolicy(password);
  if (!policy.valid) {
    state.loginError = policy.issues[0];
    state.authMessage = '';
    render();
    return;
  }
  state.authBusy = true;
  state.loginError = '';
  state.authMessage = 'Checking password against known breaches...';
  render();
  const breachCheck = await passwordPolicyAsync(password);
  if (!breachCheck.valid) {
    state.authBusy = false;
    state.loginError = breachCheck.issues[0];
    state.authMessage = '';
    render();
    return;
  }
  state.authBusy = true;
  state.loginError = '';
  state.authMessage = inviteToken ? 'Creating account and accepting invite...' : 'Creating secure workspace...';
  render();
  const signUp = await client.auth.signUp({
    email,
    password,
    options: {
      data: { full_name: fullName },
      // Without this, the confirmation email has nowhere to point except the project's Site
      // URL -- which is a deployment host, so confirming an account dropped people on a
      // *.vercel.app copy of the app instead of on questbase.io. Passing it explicitly makes
      // the link go where the person actually signed up, and the invite rides along or it is
      // lost by the time they click it.
      emailRedirectTo: `${authOrigin()}${BASE_PATH || ''}/${inviteToken ? `?invite=${encodeURIComponent(inviteToken)}` : ''}`,
    },
  });
  if (signUp.error) {
    state.authBusy = false;
    const duplicateAccount = /already|registered|exists/i.test(signUp.error.message || '');
    state.loginError = duplicateAccount && inviteToken
      ? 'That email already has a Questbase account. Sign in with the invited email to accept this invite.'
      : signUp.error.message || 'Unable to create account.';
    if (duplicateAccount && inviteToken) state.authMode = 'signin';
    state.authMessage = '';
    render();
    return;
  }
  let session = signUp.data.session;
  if (!session) {
    // No session on a successful sign-up means the project requires email confirmation.
    // Signing in now is refused with "Invalid login credentials" -- the same words Supabase
    // uses for a wrong password -- so telling somebody to sign in sends them into a message
    // they cannot act on. Name the actual next step instead.
    const signIn = await client.auth.signInWithPassword({ email, password });
    if (signIn.error) {
      state.authBusy = false;
      state.loginError = '';
      state.authMessage = `Account created. Check ${email} for a confirmation link, then sign in.`;
      state.authMode = 'signin';
      render();
      return;
    }
    session = signIn.data.session;
  }
  await setSupabaseSession(session);
  state.authBusy = false;
  if (inviteToken) {
    await acceptCompanyInvite(inviteToken, form.return_url);
    return;
  }
  const workspace = await client.rpc('create_company_workspace', { company_name: companyName, preset_code: 'blank', icon_key: iconKey });
  if (workspace.error) {
    state.loginError = workspace.error.message || 'Account created, but workspace setup failed.';
    state.authMessage = '';
    render();
    return;
  }
  applyCreatedWorkspace(workspace.data, companyName, iconKey);
  state.authMessage = '';
  openWorkspaceSetupModal('', { required: true });
  navigate(companyPath('workspaces', {}, state.activeCompanyId), { replace: true });
}

async function createWorkspaceForCurrentUser(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const client = createSupabaseClient();
  const companyName = String(form.company_name || '').trim();
  const iconKey = workspaceIconOption(form.icon_key).key;
  if (!client || !companyName) {
    state.loginError = 'Company workspace name is required.';
    state.authMessage = '';
    render();
    return;
  }
  if (!canCreateAnotherWorkspace()) {
    state.loginError = workspaceLimitMessage();
    state.authMessage = '';
    render();
    return;
  }
  state.loginError = '';
  state.authMessage = 'Creating workspace...';
  render();
  const workspace = await safeSupabaseQuery(client.rpc('create_company_workspace', { company_name: companyName, preset_code: 'blank', icon_key: iconKey }));
  if (workspace.error) {
    state.loginError = workspace.error.message || 'Workspace setup failed.';
    state.authMessage = '';
    render();
    return;
  }
  applyCreatedWorkspace(workspace.data, companyName, iconKey);
  state.authMessage = 'Opening workspace...';
  openWorkspaceSetupModal('', { required: true });
  navigate(companyPath('workspaces', {}, state.activeCompanyId), { replace: true });
}

async function createOperationalWorkspace(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const companyId = canonicalCompanyId(form.company_id || activeCompanyId());
  if (!canManageOperationalWorkspaces(companyId)) {
    showToast('Workspace admin access is required.', 'local', 'Workspaces');
    return;
  }
  const workspaceName = String(form.workspace_name || '').trim();
  const iconKey = workspaceIconOption(form.icon_key).key;
  const iconImage = sanitizeWorkspaceIconImage(form.icon_image) || '';
  if (!workspaceName) {
    showToast('Workspace name is required.', 'local', 'Workspaces');
    return;
  }

  const client = createSupabaseClient();
  const live = isLiveSupabaseSession() && client;
  let saved;
  if (live) {
    const result = await safeSupabaseQuery(client.rpc('create_operational_workspace', {
      target_company_id: companyId,
      workspace_name: workspaceName,
      preset_code: 'blank',
      icon_key: iconKey,
      icon_image: iconImage,
    }));
    if (result.error) {
      showToast(result.error.message || 'Workspace creation failed.', 'local', 'Workspaces');
      return;
    }
    const workspaceId = String(result.data || '');
    // Read back what the server installed rather than assuming it. Without this the new
    // workspace has its plugins in the database but not in state, so isModuleInstalled()
    // still says no and the workspace app stays hidden until a reload.
    const pluginResult = await safeSupabaseQuery(client.from('workspace_plugins').select('*').eq('workspace_id', workspaceId));
    (pluginResult.data || []).forEach((row) => upsertWorkspacePluginLocal(row.workspace_id, row.plugin_id, row.status));
    const rowResult = await safeSupabaseQuery(client.from('workspaces').select('*').eq('id', workspaceId).maybeSingle());
    saved = normalizeOperationalWorkspace(rowResult.data || {
      id: workspaceId,
      company_id: companyId,
      name: workspaceName,
      slug: workspaceName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'workspace',
      icon_key: iconKey,
      status: 'active',
    });
  } else {
    saved = normalizeOperationalWorkspace({
      id: crypto.randomUUID(),
      company_id: companyId,
      name: workspaceName,
      slug: workspaceName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'workspace',
      icon_key: iconKey,
      icon_image: iconImage,
      color: companyColor(companyId),
      status: 'active',
      created_by: activeSession().profile.id,
      created_at: new Date().toISOString(),
    });
    state.workspaceMemberships = mergeWorkspaceMemberships(state.workspaceMemberships.concat(normalizeWorkspaceMembership({
      workspace_id: saved.id,
      profile_id: activeSession().profile.id,
      role_id: state.roleAssignments.find((assignment) => assignment.company_id === companyId && assignment.profile_id === activeSession().profile.id)?.role_id || '',
      status: 'active',
      assigned_by: activeSession().profile.id,
    })));
    // The offline path has no RPC to do it, so the same baseline is applied here.
    BASELINE_WORKSPACE_PLUGIN_IDS.forEach((pluginId) => upsertWorkspacePluginLocal(saved.id, pluginId, 'installed'));
  }
  if (iconImage) saved = normalizeOperationalWorkspace({ ...saved, icon_image: iconImage });
  state.operationalWorkspaces = mergeOperationalWorkspaces(state.operationalWorkspaces.concat(saved));
  state.activeCompanyId = companyId;
  state.activeWorkspaceId = saved.id;
  localStorage.setItem(COMPANY_KEY, companyId);
  localStorage.setItem(ACTIVE_WORKSPACE_KEY, saved.id);
  state.operationalWorkspaceModalIcon = null;
  state.workspaceNameDraft = null;
  state.workspaceDescriptionDraft = null;
  showToast(`${saved.name} workspace created.`, live ? 'live' : 'local', 'Workspaces');
  // Into the workspace itself, so the next thing you do is build an app. It used to force
  // the guided setup and land on Settings > Setup, which is a settings page you then had to
  // leave before you could make anything. Setup is still there for anyone who wants it --
  // the Setup tab, and the prompt an empty workspace shows -- it is just no longer a gate.
  navigate(companyPath('workspaces', { workspace: saved.id }, companyId));
}

async function saveOperationalWorkspaceSettings(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const workspaceId = String(form.workspace_id || '').trim();
  const workspace = state.operationalWorkspaces.find((item) => item.id === workspaceId);
  if (!workspace || workspace.company_id !== activeCompanyId()) {
    showToast('Workspace not found.', 'local', 'Workspaces');
    return;
  }
  if (!canManageOperationalWorkspaces(workspace.company_id)) {
    showToast('Workspace admin access is required.', 'local', 'Workspaces');
    return;
  }
  const workspaceName = String(form.workspace_name || '').trim();
  const workspaceDescription = String(form.workspace_description || '').trim();
  const iconKey = workspaceIconOption(form.icon_key).key;
  const iconImage = sanitizeWorkspaceIconImage(form.icon_image) || '';
  const status = String(form.workspace_status || 'active') === 'archived' ? 'archived' : 'active';
  if (!workspaceName) {
    showToast('Workspace name is required.', 'local', 'Workspaces');
    return;
  }
  if (workspace.is_default && status === 'archived') {
    showToast('Default workspace cannot be archived.', 'local', 'Workspaces');
    return;
  }

  const client = createSupabaseClient();
  const live = isLiveSupabaseSession() && client;
  let saved;
  if (live) {
    const result = await safeSupabaseQuery(client.rpc('update_operational_workspace', {
      target_workspace_id: workspace.id,
      workspace_name: workspaceName,
      workspace_description: workspaceDescription,
      icon_key: iconKey,
      next_status: status,
      icon_image: iconImage,
    }));
    if (result.error) {
      showToast(result.error.message || 'Workspace update failed.', 'local', 'Workspaces');
      return;
    }
    saved = normalizeOperationalWorkspace(result.data || { ...workspace, name: workspaceName, description: workspaceDescription, icon_key: iconKey, status });
  } else {
    saved = normalizeOperationalWorkspace({ ...workspace, name: workspaceName, description: workspaceDescription, icon_key: iconKey, status, updated_at: new Date().toISOString() });
  }
  // Keep local/demo mode and older cached API responses aligned with the saved draft.
  saved = normalizeOperationalWorkspace({ ...saved, icon_key: iconKey, icon_image: iconImage });
  state.operationalWorkspaces = mergeOperationalWorkspaces(state.operationalWorkspaces.filter((item) => item.id !== saved.id).concat(saved));
  if (saved.status === 'archived' && state.activeWorkspaceId === saved.id) {
    state.activeWorkspaceId = defaultOperationalWorkspaceId(saved.company_id);
    localStorage.setItem(ACTIVE_WORKSPACE_KEY, state.activeWorkspaceId);
  }
  state.modal = '';
  state.selectedOperationalWorkspaceId = '';
  state.operationalWorkspaceModalIcon = null;
  showToast('Workspace settings saved.', live ? 'live' : 'local', 'Workspaces');
  // Stay on whatever page the dialog was opened over. This used to navigate to Settings,
  // which was invisible back when the only way in was the workspace list on that very page.
  // The sidebar rail opens the same dialog from anywhere now, so renaming a workspace while
  // reading the activity feed threw you out to Settings.
  render();
}

async function createPlatformWorkspace(formNode) {
  if (!isQuestDeveloper()) {
    showToast('Platform owner access is required to create workspaces for others.', 'local', 'Master panel');
    return;
  }
  const form = Object.fromEntries(new FormData(formNode).entries());
  const client = createSupabaseClient();
  const companyName = String(form.company_name || '').trim();
  const ownerEmail = String(form.owner_email || '').trim();
  const presetCode = WORKSPACE_PLUGIN_PRESETS[form.preset_code] ? form.preset_code : 'generic';
  const iconKey = workspaceIconOption(form.icon_key).key;
  if (!client || !companyName) {
    showToast('Workspace name is required.', 'local', 'Master panel');
    return;
  }
  const workspace = await safeSupabaseQuery(client.rpc('create_company_workspace', { company_name: companyName, preset_code: presetCode, icon_key: iconKey, owner_email: ownerEmail }));
  if (workspace.error) {
    showToast(workspace.error.message || 'Workspace creation failed.', 'local', 'Master panel');
    return;
  }
  if (ownerEmail) applyPlatformCreatedWorkspace(workspace.data, companyName, iconKey);
  else applyCreatedWorkspace(workspace.data, companyName, iconKey);
  showToast(`${companyName} workspace created.`, 'live', 'Master panel');
  navigate(companyPath('admin', { tab: 'platform' }, state.activeCompanyId), { replace: true });
}

async function saveWorkspaceSettings(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const companyId = canonicalCompanyId(form.company_id || activeCompanyId());
  const workspaceName = String(form.workspace_name || '').trim();
  const iconKey = workspaceIconOption(form.icon_key).key;
  const iconImage = sanitizeWorkspaceIconImage(form.icon_image);
  const iconColor = normalizeIconColor(form.icon_color);
  const iconPack = workspaceIconPack(form.icon_pack);
  if (!workspaceName) {
    showToast('Workspace name is required.', 'local', 'Settings');
    return;
  }
  const client = createSupabaseClient();
  let live = false;
  if (client && isLiveSupabaseSession()) {
    const result = await safeSupabaseQuery(client.rpc('update_company_workspace', { target_company_id: companyId, workspace_name: workspaceName, icon_key: iconKey, icon_image: iconImage, p_icon_color: iconColor }));
    if (result.error) {
      showToast(result.error.message || 'Workspace update failed.', 'local', 'Settings');
      return;
    }
    live = true;
  }
  state.companies = mergeCompanies(state.companies
    .filter((company) => company.id !== companyId)
    .concat(normalizeCompany({
      ...(companyById(companyId) || {}),
      id: companyId,
      name: workspaceName,
      short_name: workspaceName,
      label: workspaceName,
      icon_key: iconKey,
      icon_image: iconImage,
      // Persisted: the RPC above passes p_icon_color, and the five-argument overload is
      // live (migration 202608021000). The four-argument function is still granted, so an
      // older client mid-rollout keeps working and simply leaves the colour unchanged.
      icon_color: iconColor,
      icon_pack: iconPack,
    })));
  delete state.workspaceIconDrafts[companyId];
  state.modal = '';
  showToast('Workspace settings saved.', live ? 'live' : 'local', 'Settings');
  render();
}

function applyCreatedWorkspace(workspaceId, requestedName = '', iconKey = 'home') {
  const companyId = authoritativeCompanyId(workspaceId || defaultCompanyId());
  const cleanName = String(requestedName || companyName(companyId) || companyId).trim();
  const existingSubscription = companySubscription(companyId);
  state.activeCompanyId = companyId;
  state.companies = mergeCompanies(state.companies.concat(normalizeCompany({
    id: companyId,
    name: cleanName,
    short_name: cleanName,
    color: companyColor(companyId),
    icon_key: iconKey,
  })));
  state.memberships = state.memberships
    .filter((membership) => !(membership.company_id === companyId && membership.profile_id === activeSession().profile.id))
    .concat(normalizeMembership({
      company_id: companyId,
      profile_id: activeSession().profile.id,
      member_id: activeSession().profile.member_id,
      role: 'owner',
      status: 'active',
    }));
  state.subscriptions = mergeSubscriptions(state.subscriptions.concat(normalizeSubscription({
    ...(existingSubscription || {}),
    company_id: companyId,
    status: existingSubscription?.status || 'pending_review',
  })));
  const profile = normalizeProfile({
    ...activeSession().profile,
    company_ids: compactUnique((activeSession().profile.company_ids || []).concat(companyId)),
    approved: true,
    role: activeSession().profile.role === 'member' ? 'admin' : activeSession().profile.role,
  });
  state.session = { ...activeSession(), profile };
  writeJson(SESSION_KEY, state.session);
  const subscription = companySubscription(companyId);
  if (subscription?.status === 'pending_review') markWorkspacePendingReview(companyId);
  else clearWorkspacePendingReview(companyId);
  localStorage.setItem(COMPANY_KEY, companyId);
  state.dataLoaded = false;
}

function applyPlatformCreatedWorkspace(workspaceId, requestedName = '', iconKey = 'home') {
  const companyId = authoritativeCompanyId(workspaceId || '');
  if (!companyId) return;
  const cleanName = String(requestedName || companyId).trim();
  state.companies = mergeCompanies(state.companies.concat(normalizeCompany({
    id: companyId,
    name: cleanName,
    short_name: cleanName,
    label: cleanName,
    color: companyColor(companyId),
    icon_key: iconKey,
  })));
  state.subscriptions = mergeSubscriptions(state.subscriptions.concat(normalizeSubscription({
    company_id: companyId,
    status: 'pending_review',
  })));
  markWorkspacePendingReview(companyId);
  state.dataLoaded = false;
}

function applyPluginPresetLocal(companyId, presetCode) {
  const cleanPreset = WORKSPACE_PLUGIN_PRESETS[presetCode] ? presetCode : 'generic';
  const pluginIds = WORKSPACE_PLUGIN_PRESETS[cleanPreset];
  availableWorkspacePlugins().forEach((plugin) => {
    upsertCompanyPluginLocal(companyId, plugin.id, pluginIds.includes(plugin.id) ? 'installed' : 'disabled');
  });
}

function upsertCompanyPluginLocal(companyId, pluginId, status) {
  const row = normalizeCompanyPlugin({
    company_id: companyId,
    plugin_id: pluginId,
    status,
    installed_by: status === 'installed' ? activeSession().profile.id : '',
    installed_at: status === 'installed' ? new Date().toISOString() : '',
    disabled_at: status === 'disabled' ? new Date().toISOString() : '',
    updated_at: new Date().toISOString(),
  });
  state.companyPlugins = mergeCompanyPlugins(state.companyPlugins
    .filter((item) => !(item.company_id === row.company_id && item.plugin_id === row.plugin_id))
    .concat(row));
}

function upsertWorkspacePluginLocal(workspaceId, pluginId, status) {
  const row = normalizeWorkspacePlugin({
    workspace_id: workspaceId,
    plugin_id: pluginId,
    status,
    installed_by: status === 'installed' ? activeSession().profile.id : '',
    installed_at: status === 'installed' ? new Date().toISOString() : '',
    disabled_at: status === 'disabled' ? new Date().toISOString() : '',
    updated_at: new Date().toISOString(),
  });
  state.workspacePlugins = mergeWorkspacePlugins(state.workspacePlugins
    .filter((item) => !(item.workspace_id === row.workspace_id && item.plugin_id === row.plugin_id))
    .concat(row));
}

function applyWorkspacePluginPresetLocal(workspaceId, presetCode) {
  const workspace = state.operationalWorkspaces.find((item) => item.id === String(workspaceId || ''));
  if (!workspace) return;
  const cleanPreset = WORKSPACE_PLUGIN_PRESETS[presetCode] ? presetCode : 'generic';
  const desiredPluginIds = WORKSPACE_PLUGIN_PRESETS[cleanPreset];
  availableWorkspacePlugins().forEach((plugin) => {
    const entitled = companyPluginStatus(workspace.company_id, plugin.id) === 'installed';
    upsertWorkspacePluginLocal(workspace.id, plugin.id, entitled && desiredPluginIds.includes(plugin.id) ? 'installed' : 'disabled');
  });
}

function revealPluginModulesInNavigation(plugin) {
  if (!plugin?.module_ids?.length) return;
  const groupsToOpen = NAV_GROUPS
    .filter((group) => group.ids.some((id) => plugin.module_ids.includes(id)))
    .map((group) => group.label);
  groupsToOpen.forEach((group) => state.collapsedNavGroups.delete(group));
  if (groupsToOpen.length) {
    state.sidebarCollapsed = false;
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, 'false');
    writeJson(NAV_GROUP_COLLAPSED_KEY, [...state.collapsedNavGroups]);
  }
}

async function setWorkspacePlugin(workspaceId, pluginId, status) {
  const workspace = state.operationalWorkspaces.find((item) => item.id === String(workspaceId || ''));
  const plugin = pluginById(pluginId);
  const nextStatus = status === 'disabled' ? 'disabled' : 'installed';
  if (!workspace || workspace.status !== 'active') {
    showToast('Choose an active workspace first.', 'local', 'Plugins');
    return;
  }
  if (!plugin || plugin.comingSoon) {
    showToast('That plugin is not available yet.', 'local', 'Plugins');
    return;
  }
  if (nextStatus === 'installed' && companyPluginStatus(workspace.company_id, plugin.id) !== 'installed') {
    showToast('This company account is not entitled to that plugin.', 'local', 'Plugins');
    return;
  }
  const conflictIds = conflictingPluginIds(workspace.company_id, plugin.id, nextStatus, workspace.id);
  if (conflictIds.length) {
    const conflictLabels = conflictIds.map((conflictId) => pluginById(conflictId)?.label || conflictId).join(', ');
    if (!window.confirm(`Installing ${plugin.label} will disable ${conflictLabels}. Continue?`)) return;
  }
  state.sync = { label: 'Updating workspace plugin...', mode: 'loading' };
  render();
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await safeSupabaseQuery(client.rpc('set_workspace_plugin', {
      target_workspace_id: workspaceId,
      target_plugin_id: plugin.id,
      next_status: nextStatus,
    }));
    if (result.error) throw new Error(result.error.message || 'Workspace plugin update failed.');
  }
  conflictIds.forEach((conflictId) => upsertWorkspacePluginLocal(workspace.id, conflictId, 'disabled'));
  upsertWorkspacePluginLocal(workspaceId, plugin.id, nextStatus);
  if (nextStatus === 'installed') revealPluginModulesInNavigation(plugin);
  state.sync = { label: `${plugin.label} ${nextStatus === 'installed' ? 'activated' : 'disabled'}`, mode: state.session?.auth === 'supabase' ? 'live' : 'local' };
  showToast(`${plugin.label} ${nextStatus === 'installed' ? 'activated' : 'disabled'} in ${workspace.name}.`, state.session?.auth === 'supabase' ? 'live' : 'local', 'Plugins');
  render();
}

async function applyWorkspacePluginPreset(workspaceId, presetCode) {
  const workspace = state.operationalWorkspaces.find((item) => item.id === String(workspaceId || ''));
  if (!workspace || workspace.status !== 'active') {
    showToast('Choose an active workspace first.', 'local', 'Plugins');
    return;
  }
  const cleanPreset = WORKSPACE_PLUGIN_PRESETS[presetCode] ? presetCode : 'generic';
  state.sync = { label: 'Applying workspace plugin preset...', mode: 'loading' };
  render();
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await safeSupabaseQuery(client.rpc('apply_workspace_plugin_preset', {
      target_workspace_id: workspaceId,
      preset_code: cleanPreset,
    }));
    if (result.error) throw new Error(result.error.message || 'Workspace plugin preset failed.');
  }
  applyWorkspacePluginPresetLocal(workspace.id, cleanPreset);
  state.sync = { label: `${WORKSPACE_PLUGIN_PRESET_LABELS[cleanPreset]} plugins applied to ${workspace.name}`, mode: state.session?.auth === 'supabase' ? 'live' : 'local' };
  showToast(`${WORKSPACE_PLUGIN_PRESET_LABELS[cleanPreset]} preset applied to ${workspace.name}.`, state.session?.auth === 'supabase' ? 'live' : 'local', 'Plugins');
  render();
}

