async function requestCompanyAccess(formNode) {
  const form = Object.fromEntries(new FormData(formNode).entries());
  const client = createSupabaseClient();
  if (!client?.auth) {
    state.loginError = 'Supabase auth is unavailable.';
    render();
    return;
  }
  const email = String(form.email || '').trim();
  const password = String(form.password || '');
  const companyId = canonicalCompanyId(form.company_id || '');
  state.authBusy = true;
  state.loginError = '';
  state.authMessage = 'Submitting access request...';
  render();
  const signIn = await client.auth.signInWithPassword({ email, password });
  if (signIn.error) {
    state.authBusy = false;
    state.loginError = signIn.error.message || 'Sign in first to request access.';
    state.authMessage = '';
    render();
    return;
  }
  await setSupabaseSession(signIn.data.session);
  const request = await client.rpc('request_company_access', {
    target_company_id: companyId,
    request_message: String(form.message || '').trim() || null,
  });
  if (request.error) {
    state.authBusy = false;
    state.loginError = request.error.message || 'Unable to request access.';
    state.authMessage = '';
    render();
    return;
  }
  state.authMessage = 'Access request sent. An Owner/Admin must approve it.';
  state.authBusy = false;
  state.loginError = '';
  state.authMode = 'signin';
  render();
}

async function startCheckout() {
  const companyId = activeCompanyId();
  if (!requirePermission('billing.manage', companyId, 'Your role can view billing but cannot change the subscription.', 'Billing')) return false;
  if (CONFIG.billingMode === 'manual') {
    state.sync = { label: 'Manual approval active', mode: 'local' };
    showToast('Manual approval is active for launch week. Lumen will activate billing after review.', 'local', 'Billing');
    render();
    return;
  }
  state.sync = { label: 'Opening billing...', mode: 'loading' };
  render();
  try {
    state.checkoutRequestId ||= crypto.randomUUID();
    const response = await fetch('/api/create-checkout-session', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(activeSession().access_token ? { Authorization: `Bearer ${activeSession().access_token}` } : {}),
      },
      body: JSON.stringify({
        company_id: companyId,
        request_id: state.checkoutRequestId,
        return_url: `${window.location.origin}${appHref(companyPath('admin', { tab: 'billing' }, companyId))}`,
      }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || !payload.url) throw new Error(payload.error || 'Billing is not configured yet.');
    window.location.href = payload.url;
  } catch (error) {
    state.sync = { label: error.message || 'Billing unavailable', mode: 'local' };
    render();
  }
}

async function reviewWorkspace(companyId, status) {
  const targetCompanyId = canonicalCompanyId(companyId);
  const nextStatus = normalizeSubscriptionStatus(status);
  if (!targetCompanyId || !nextStatus || !isQuestDeveloper()) {
    showToast('Platform owner access is required to review workspaces.', 'local', 'Workspace review');
    return;
  }
  const client = createSupabaseClient();
  state.sync = { label: 'Updating workspace review...', mode: 'loading' };
  render();
  if (isLiveSupabaseSession() && client) {
    const result = await client.rpc('review_company_workspace', {
      target_company_id: targetCompanyId,
      next_status: nextStatus,
      review_note: `Marked ${nextStatus} from Questbase approval console`,
    });
    if (result.error) {
      state.sync = { label: result.error.message || 'Workspace review failed', mode: 'local' };
      showToast(result.error.message || 'Workspace review failed.', 'local', 'Workspace review');
      render();
      return;
    }
  }
  applyWorkspaceReviewStatus(targetCompanyId, nextStatus);
  await recordAuditEvent(targetCompanyId, 'workspace.reviewed', 'company_subscription', targetCompanyId, { status: nextStatus }, state.session?.auth === 'supabase');
  state.sync = { label: `Workspace marked ${subscriptionLabelForStatus(nextStatus).toLowerCase()}`, mode: state.session?.auth === 'supabase' ? 'live' : 'local' };
  showToast(`Workspace marked ${subscriptionLabelForStatus(nextStatus).toLowerCase()}.`, state.session?.auth === 'supabase' ? 'live' : 'local', 'Workspace review');
  render();
}

async function managePlatformCompany(companyId, platformAction) {
  const targetCompanyId = canonicalCompanyId(companyId);
  const action = String(platformAction || '').toLowerCase().trim();
  const nextStatus = platformActionStatus(action);
  if (!targetCompanyId || !nextStatus || !isQuestDeveloper()) {
    showToast('Platform owner access is required to manage companies.', 'local', 'Master panel');
    return;
  }
  if (targetCompanyId === 'lumen' && ['suspend', 'archive', 'delete', 'cancel'].includes(action)) {
    showToast('The Lumen platform workspace cannot be suspended or archived from the panel.', 'local', 'Master panel');
    return;
  }
  const client = createSupabaseClient();
  state.sync = { label: 'Updating company access...', mode: 'loading' };
  render();
  if (isLiveSupabaseSession() && client) {
    const result = await client.rpc('manage_platform_company', {
      target_company_id: targetCompanyId,
      platform_action: action,
      review_note: `Platform master panel marked ${targetCompanyId} as ${nextStatus}`,
    });
    if (result.error) {
      state.sync = { label: result.error.message || 'Company update failed', mode: 'local' };
      showToast(result.error.message || 'Company update failed.', 'local', 'Master panel');
      render();
      return;
    }
  }
  applyPlatformCompanyStatus(targetCompanyId, nextStatus);
  await recordAuditEvent(targetCompanyId, `platform.company.${action}`, 'company', targetCompanyId, { action, status: nextStatus }, state.session?.auth === 'supabase');
  state.sync = { label: `${companyName(targetCompanyId)} marked ${subscriptionLabelForStatus(nextStatus).toLowerCase()}`, mode: state.session?.auth === 'supabase' ? 'live' : 'local' };
  showToast(`${companyName(targetCompanyId)} marked ${subscriptionLabelForStatus(nextStatus).toLowerCase()}.`, state.session?.auth === 'supabase' ? 'live' : 'local', 'Master panel');
  if (state.session?.auth === 'supabase') state.dataLoaded = false;
  render();
}

function applyWorkspaceReviewStatus(companyId, status) {
  const subscription = normalizeSubscription({
    ...(companySubscription(companyId) || {}),
    company_id: companyId,
    status,
  });
  state.subscriptions = mergeSubscriptions(state.subscriptions.filter((item) => item.company_id !== companyId).concat(subscription));
  const review = normalizeWorkspaceReview({
    ...(state.workspaceReviews.find((item) => item.company_id === companyId) || {}),
    company_id: companyId,
    company_name: companyName(companyId),
    status,
    plan_code: subscription.plan_code,
    amount_cents: subscription.amount_cents,
    currency: subscription.currency,
    created_at: new Date().toISOString(),
  });
  state.workspaceReviews = state.workspaceReviews.filter((item) => item.company_id !== companyId).concat(review);
  if (status === 'pending_review') markWorkspacePendingReview(companyId);
  else clearWorkspacePendingReview(companyId);
}

function applyPlatformCompanyStatus(companyId, status) {
  applyWorkspaceReviewStatus(companyId, status);
  const index = state.platformCompanies.findIndex((company) => company.company_id === companyId);
  const current = index >= 0 ? state.platformCompanies[index] : platformCompanyRows().find((company) => company.company_id === companyId) || normalizePlatformCompany({
    company_id: companyId,
    company_name: companyName(companyId),
  });
  const next = normalizePlatformCompany({
    ...current,
    status,
    updated_at: new Date().toISOString(),
  });
  if (index >= 0) state.platformCompanies[index] = next;
  else state.platformCompanies.push(next);
}

async function saveRole(formNode) {
  const companyId = activeCompanyId();
  if (!requirePermission('roles.manage', companyId, 'Your role cannot manage roles.', 'Roles')) return;
  const data = new FormData(formNode);
  const existingId = String(data.get('id') || '').trim();
  const existing = existingId ? roleById(companyId, existingId) : null;
  if (existing && existing.is_system) {
    showToast('System roles cannot be edited.', 'local', 'Roles');
    return;
  }
  const role = normalizeRole({
    id: existing ? existing.id : crypto.randomUUID(),
    company_id: companyId,
    name: data.get('name'),
    color: data.get('color') || '#f0b23b',
    priority: data.get('priority') || 100,
    is_system: false,
    created_by: existing ? existing.created_by : activeSession().profile.id,
  });
  const permissions = data.getAll('permissions').map((permission) => String(permission || '')).filter(Boolean);
  const upsertRoleInState = (saved) => {
    const index = state.roles.findIndex((item) => item.id === saved.id);
    if (index >= 0) state.roles[index] = saved;
    else state.roles.unshift(saved);
  };
  const replacePermissionsInState = (roleId, keys) => {
    const rows = keys.map((permission_key) => normalizeRolePermission({ role_id: roleId, permission_key, effect: 'allow' }));
    state.rolePermissions = rows.concat(state.rolePermissions.filter((item) => item.role_id !== roleId));
  };
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    // save_company_role reads a present id as "update the row with this id". The locally
    // minted one belongs to no row, so a new role took the update branch, matched nothing and
    // raised 'role not found' -- no custom role could be created at all. Send the id only
    // when there is a row behind it and let the database mint the rest.
    const result = await client.rpc('save_company_role', {
      p_role: existing ? role : { ...role, id: '' },
      p_permissions: permissions,
    });
    if (result.error) {
      // This used to set the sync chip and nothing else, so a failed save looked like a
      // save: the modal closed on the next render and the role was simply absent.
      state.sync = { label: result.error.message || 'Role save failed', mode: 'local' };
      showToast(result.error.message || 'Role save failed.', 'local', 'Roles');
      render();
      return;
    }
    const savedRole = normalizeRole(result.data);
    upsertRoleInState(savedRole);
    replacePermissionsInState(savedRole.id, permissions);
    state.sync = { label: existing ? 'Role updated' : 'Role saved', mode: 'live' };
  } else {
    upsertRoleInState(role);
    replacePermissionsInState(role.id, permissions);
    state.sync = { label: existing ? 'Role updated locally' : 'Role saved locally', mode: 'local' };
  }
  state.selectedRoleId = '';
  state.modal = '';
  render();
}

async function deleteRole(roleId) {
  const companyId = activeCompanyId();
  if (!requirePermission('roles.manage', companyId, 'Your role cannot manage roles.', 'Roles')) return;
  const role = roleById(companyId, roleId);
  if (!role) {
    showToast('That role is no longer available.', 'local', 'Roles');
    return;
  }
  if (role.is_system) {
    showToast('Owner and Member are the two roles every company starts with and cannot be deleted. You can edit Member.', 'local', 'Roles');
    return;
  }
  const assignedCount = state.roleAssignments.filter((item) => item.company_id === companyId && item.role_id === role.id).length;
  if (assignedCount > 0) {
    showToast(`Reassign the ${assignedCount} member${assignedCount === 1 ? '' : 's'} using "${role.name}" before deleting it.`, 'local', 'Roles');
    return;
  }
  const client = createSupabaseClient();
  const live = isLiveSupabaseSession() && client;
  if (live) {
    const result = await client.rpc('delete_company_role', { p_role_id: role.id });
    if (result.error) {
      state.sync = { label: result.error.message || 'Role delete failed', mode: 'local' };
      render();
      return;
    }
  }
  state.roles = state.roles.filter((item) => item.id !== role.id);
  state.rolePermissions = state.rolePermissions.filter((item) => item.role_id !== role.id);
  if (state.rolePreview?.role_id === role.id) state.rolePreview = null;
  if (state.selectedRoleId === role.id) state.selectedRoleId = '';
  state.roleDeleteCtx = null;
  state.modal = '';
  state.sync = { label: live ? 'Role deleted' : 'Role deleted locally', mode: live ? 'live' : 'local' };
  render();
}

/**
 * Put a form's submit button into a working state, and hand back the undo.
 *
 * For submits that wait on something slow enough to look broken -- sending an invite goes
 * through an insert, an audit write and an email provider before anything changes on screen.
 * Without this the button looks untouched, so people press it again and get two of whatever
 * they asked for.
 *
 * Returns a no-op when there is no submit button, so callers never have to check.
 */
function beginSubmitting(formNode, label = 'Working…') {
  // A form, or the button itself. The Company Contacts field editor saves from a button in the
  // modal header, which is nowhere near a <form>.
  const button = formNode?.matches?.('button') ? formNode : formNode?.querySelector?.('button[type="submit"]');
  if (!button || button.disabled) return null;
  const original = button.innerHTML;
  button.disabled = true;
  // Announced rather than only drawn: a disabled button with a spinner says nothing to a
  // screen reader on its own.
  button.setAttribute('aria-busy', 'true');
  button.innerHTML = `<span class="btn-spinner" aria-hidden="true"></span>${h(label)}`;
  return () => {
    // The form is often gone by now -- a successful save closes the modal -- and writing to a
    // detached node is harmless, so there is nothing to check for.
    button.disabled = false;
    button.removeAttribute('aria-busy');
    button.innerHTML = original;
  };
}

async function saveInvite(formNode) {
  // Already in flight. Enter in a text field can submit a form whose button is disabled, so
  // the guard belongs here rather than relying on the button alone.
  if (formNode?.querySelector?.('button[type="submit"]')?.disabled) return;
  const data = new FormData(formNode);
  const companyId = canonicalCompanyId(data.get('company_id') || activeCompanyId());
  if (!requirePermission('users.manage', companyId, 'Your role cannot invite users.', 'Users')) return;
  const email = String(data.get('email') || '').trim().toLowerCase();
  const roleId = String(data.get('role_id') || '').trim();
  const availableWorkspaceIds = new Set(state.operationalWorkspaces
    .filter((workspace) => workspace.company_id === companyId && workspace.status === 'active')
    .map((workspace) => workspace.id));
  const workspaceIds = compactUnique(data.getAll('workspace_ids').map(String))
    .filter((workspaceId) => availableWorkspaceIds.has(workspaceId));
  if (!email) {
    state.sync = { label: 'Invite email is required', mode: 'local' };
    render();
    return;
  }
  if (!workspaceIds.length) {
    state.sync = { label: 'Select at least one workspace for this teammate', mode: 'local' };
    render();
    return;
  }
  const inviteRole = roleById(companyId, roleId);
  if (inviteRole && INVITE_BLOCKED_ROLE_NAMES.has(inviteRole.name.toLowerCase())) {
    state.sync = { label: 'Owner, Admin, and Developer access must be granted after the teammate joins', mode: 'local' };
    render();
    return;
  }

  const invite = normalizeCompanyInvite({
    id: crypto.randomUUID(),
    company_id: companyId,
    email,
    role_id: isUuid(roleId) ? roleId : '',
    workspace_ids: workspaceIds,
    email_status: 'not_sent',
    token: generateInviteCode(),
    status: 'pending',
    invited_by: activeSession().profile.id,
    expires_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
    created_at: new Date().toISOString(),
  });
  const client = createSupabaseClient();
  // Everything below here waits on the network. The button says so until it is done.
  const doneSubmitting = beginSubmitting(formNode, 'Sending invite…');

  try {
    if (isLiveSupabaseSession() && client) {
      const payload = {
        company_id: invite.company_id,
        email: invite.email,
        role_id: invite.role_id || null,
        workspace_ids: invite.workspace_ids,
        token: invite.token,
        status: 'pending',
        invited_by: activeSession().profile.id,
      };
      const result = await client.from('company_invites').insert(payload).select().single();
      if (result.error) {
        state.sync = { label: result.error.message || 'Invite save failed', mode: 'local' };
        render();
        return;
      }
      state.companyInvites.unshift(normalizeCompanyInvite(result.data));
      await recordAuditEvent(invite.company_id, 'invite.created', 'company_invite', result.data.id, { email: invite.email }, true);
      await sendCompanyInviteEmail(result.data.id, { renderAfter: false });
    } else {
      state.companyInvites.unshift(invite);
      recordAuditEvent(invite.company_id, 'invite.created', 'company_invite', invite.id, { email: invite.email });
      state.sync = { label: 'Invite created locally. Copy its link to share it.', mode: 'local' };
    }

    notifyLocalEvent('access.invite', 'Teammate invited', `${actorName()} invited ${invite.email}.`, companyPath('users', { tab: 'invites' }, invite.company_id), 'invite', invite.id, invite.company_id);
    state.modal = '';
    render();
  } finally {
    // Restored on every path, including the early return above and an unexpected throw --
    // otherwise a failed invite leaves a permanently dead button behind.
    if (doneSubmitting) doneSubmitting();
  }
}

async function sendCompanyInviteEmail(inviteId, { renderAfter = true } = {}) {
  const invite = state.companyInvites.find((item) => item.id === String(inviteId || ''));
  if (!invite) return false;
  if (!requirePermission('users.manage', invite.company_id, 'Your role cannot send invite emails.', 'Users')) return false;
  const client = createSupabaseClient();
  if (!isLiveSupabaseSession() || !client) {
    state.sync = { label: 'Email delivery requires a live Questbase session. Copy the invite link instead.', mode: 'local' };
    if (renderAfter) render();
    return false;
  }

  state.sync = { label: `Sending invite to ${invite.email}...`, mode: 'live' };
  if (renderAfter) render();
  const { data, error } = await client.functions.invoke('send-company-invite', {
    body: { invite_id: invite.id },
  });
  const sent = !error && data?.ok === true;
  // Two different failures hide behind one label, and telling them apart matters: the mail
  // provider rejecting the message is recorded by the function itself, but a request that
  // never arrives leaves no trace server-side at all -- the row stays "not sent" while the
  // screen says "delivery failed", which is how this became impossible to diagnose. Keep
  // whatever reason we actually have.
  const reason = sent ? '' : (error?.message || data?.error || 'The request did not reach the mail service.');
  state.companyInvites = state.companyInvites.map((item) => (
    item.id === invite.id
      ? normalizeCompanyInvite({
        ...item,
        email_status: sent ? 'sent' : 'failed',
        email_sent_at: sent ? (data?.email_sent_at || item.email_sent_at || new Date().toISOString()) : '',
        email_last_error: reason,
      })
      : item
  ));
  state.sync = sent
    ? { label: data?.already_sent ? 'Invite email was already sent' : `Invite emailed to ${invite.email}`, mode: 'live' }
    : { label: 'Email delivery failed. The invite is still valid - copy its link or retry.', mode: 'local' };
  // The invite itself is fine either way, so this is a warning rather than an error, but it
  // has to say why or the next report is "it just fails" again.
  if (!sent) showToast(`Could not email ${invite.email}: ${reason}`, 'error', 'Users');
  if (renderAfter) render();
  return sent;
}

async function acceptCompanyInvite(token, fallbackReturnUrl = '') {
  const client = createSupabaseClient();
  if (!client) {
    state.loginError = 'Supabase auth is unavailable.';
    state.authMessage = '';
    render();
    return;
  }
  state.authMessage = 'Accepting workspace invite...';
  render();
  const result = await client.rpc('accept_company_invite', { invite_token: String(token || '').trim() });
  if (result.error) {
    state.loginError = result.error.message || 'Unable to accept invite.';
    state.authMessage = '';
    render();
    return;
  }
  const companyId = canonicalCompanyId(result.data || defaultCompanyId());
  state.activeCompanyId = companyId;
  localStorage.setItem(COMPANY_KEY, companyId);
  state.inviteLookup = null;
  state.authMessage = '';
  state.loginError = '';
  state.dataLoaded = false;
  navigate(companyPath('dashboard', {}, companyId), { replace: true });
}

async function copyInviteLink(inviteId) {
  const invite = state.companyInvites.find((item) => item.id === inviteId);
  if (invite && !requirePermission('users.manage', invite.company_id, 'Your role cannot view invite links.', 'Users')) return;
  if (!invite?.token) {
    state.sync = { label: 'Invite link is unavailable', mode: 'local' };
    render();
    return;
  }
  try {
    await navigator.clipboard.writeText(inviteLink(invite));
    state.sync = { label: 'Invite link copied', mode: 'live' };
  } catch {
    state.sync = { label: 'Copy failed', mode: 'local' };
  }
  render();
}

async function copyInviteCode(inviteId) {
  const invite = state.companyInvites.find((item) => item.id === inviteId);
  if (invite && !requirePermission('users.manage', invite.company_id, 'Your role cannot view invite codes.', 'Users')) return;
  if (!invite?.token) {
    state.sync = { label: 'Invite code is unavailable', mode: 'local' };
    render();
    return;
  }
  try {
    await navigator.clipboard.writeText(invite.token);
    state.sync = { label: 'Invite code copied', mode: 'live' };
  } catch {
    state.sync = { label: 'Copy failed', mode: 'local' };
  }
  render();
}

async function revokeInvite(inviteId) {
  const invite = state.companyInvites.find((item) => item.id === inviteId);
  if (!invite) return;
  if (!requirePermission('users.manage', invite.company_id, 'Your role cannot revoke invites.', 'Users')) return;
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.rpc('revoke_company_invite', { target_invite_id: invite.id });
    if (result.error) {
      // This failed silently for a while: the reason went into the sync pill, which is easy
      // to miss, so revoking looked like it simply did nothing. A refusal to revoke is worth
      // interrupting for.
      state.sync = { label: result.error.message || 'Invite revoke failed', mode: 'local' };
      showToast(result.error.message || 'Could not revoke this invite.', 'error', 'Users');
      render();
      return;
    }
    state.sync = { label: 'Invite revoked', mode: 'live' };
  } else {
    state.sync = { label: 'Invite revoked locally', mode: 'local' };
  }
  // Removed, not marked. Revoking withdraws the invitation entirely, so the row goes and the
  // same person can be invited again without colliding with their own history. What happened
  // is kept in audit_events, which is the table that exists to be permanent -- the invite row
  // was only ever live state.
  state.companyInvites = state.companyInvites.filter((item) => item.id !== invite.id);
  recordAuditEvent(invite.company_id, 'invite.revoked', 'company_invite', invite.id, { email: invite.email });
  notifyLocalEvent('access.invite', 'Invite revoked', `${actorName()} revoked the invite for ${invite.email}.`, companyPath('users', { tab: 'invites' }, invite.company_id), 'invite', invite.id, invite.company_id);
  persistAll();
  render();
}

let memberDirectoryModule = null;
function loadMemberDirectory() {
  if (memberDirectoryModule) return Promise.resolve(memberDirectoryModule);
  return import('./team/member-directory.js').then((mod) => { memberDirectoryModule = mod; return mod; });
}

function memberDirectoryUi() {
  state.memberDirectory = state.memberDirectory || { view: 'list', query: '', role: '', sort: 'name', selected: new Set(), expanded: new Set() };
  if (!(state.memberDirectory.selected instanceof Set)) state.memberDirectory.selected = new Set();
  // Which member rows are open. On state rather than the DOM: every save re-renders the page,
  // and a flag held on the element would be discarded with it.
  if (!(state.memberDirectory.expanded instanceof Set)) state.memberDirectory.expanded = new Set();
  return state.memberDirectory;
}

/**
 * Give one role to everybody selected.
 *
 * Runs each person through the SAME validation and persistence the single-user form does,
 * one at a time -- so a bulk change cannot make a company ownerless by a route the form
 * already refuses. Only the role moves: the workspace ids handed to persistUserAccess are
 * the person's current ones, so assigning a role does not silently rewrite who can see what.
 */
async function assignRoleToSelectedMembers(companyId, roleId) {
  if (!requirePermission('users.manage', companyId, 'Your role cannot manage user access.', 'Users')) return;
  const role = roleById(companyId, roleId);
  if (!role) { showToast('Choose a role to assign.', 'local', 'Users'); return; }

  const ui = memberDirectoryUi();
  const users = companyAccessUsers(companyId);
  const memberDirectory = await loadMemberDirectory();
  const { eligible } = memberDirectory.assignableSelection({
    selected: ui.selected,
    visible: memberDirectory.filterSortMembers({ users, query: ui.query, role: ui.role, sort: ui.sort }),
    isProtected: (user) => isProtectedOwner(companyId, user),
  });
  if (!eligible.length) { showToast('Nobody selected can be reassigned.', 'local', 'Users'); return; }

  const done = [];
  const refused = [];
  for (const user of eligible) {
    const status = ['active', 'pending', 'disabled', 'left'].includes(user.status) ? user.status : 'active';
    const refusal = validateMembershipChange(companyId, user.profile_id, role, status);
    if (refusal) { refused.push(`${userDisplayName(user)}: ${refusal}`); continue; }
    const workspaceIds = state.workspaceMemberships
      .filter((m) => m.profile_id === user.profile_id && (m.status || 'active') === 'active')
      .map((m) => String(m.workspace_id));
    try {
      // persistUserAccess reads only `data`, and only workspace_ids off it.
      await persistUserAccess(null, {
        companyId, profileId: user.profile_id, role, status,
        data: { getAll: () => workspaceIds },
      });
      done.push(user);
    } catch (error) {
      refused.push(`${userDisplayName(user)}: ${error.message || 'save failed'}`);
    }
  }

  if (done.length) ui.selected.clear();
  // Both halves reported: a partial success that only says "3 updated" hides the two it
  // could not do, and those are the ones needing attention.
  if (done.length) showToast(`${role.name} assigned to ${done.length} member${done.length === 1 ? '' : 's'}.`, isLiveSupabaseSession() ? 'live' : 'local', 'Users');
  if (refused.length) showToast(`Not changed — ${refused.join('; ')}`, 'local', 'Users');
  render();
}

async function saveUserAccess(formNode) {
  const data = new FormData(formNode);
  const companyId = canonicalCompanyId(data.get('company_id') || activeCompanyId());
  if (!requirePermission('users.manage', companyId, 'Your role cannot manage user access.', 'Users')) return;
  const profileId = String(data.get('profile_id') || '').trim();
  const roleId = String(data.get('role_id') || '').trim();
  const status = ['active', 'pending', 'disabled', 'left'].includes(String(data.get('membership_status'))) ? String(data.get('membership_status')) : 'active';
  const role = roleById(companyId, roleId);
  if (!profileId || !role) {
    accessSaveFailed('Choose a role before saving.');
    return;
  }
  const validationMessage = validateMembershipChange(companyId, profileId, role, status);
  if (validationMessage) {
    accessSaveFailed(validationMessage);
    return;
  }
  // The audit trail shows this form submitted three times inside 0.4s, so the button says it
  // is working and refuses a second press while the first is in flight.
  const done = beginSubmitting(formNode, 'Saving…');
  if (!done) return;
  try {
    await persistUserAccess(formNode, { companyId, profileId, role, status, data });
  } finally {
    done();
  }
}

/** A refused save has to say so where the user is looking, not only in the sync chip. */
function accessSaveFailed(message) {
  showToast(message, 'local', 'Users');
  render();
}

/**
 * Confirming a removal.
 *
 * The whole point of this dialog is the middle line. "Remove" reads as "erase", and the fear
 * that removing somebody deletes the jobs, tasks and messages they produced is exactly what
 * stops people using it. Say what survives before saying what goes.
 */
/**
 * Make a task out of something that happened in the workspace.
 *
 * Pre-filled from the log line, because the whole point is that you saw an event and want to
 * act on it -- retyping what you just read is friction. It goes through the one task model,
 * so it lands in My Tasks rather than becoming a workspace-only to-do.
 */
/**
 * Deleting an operational workspace.
 *
 * Behind the account password, like the other operations that destroy something: being signed
 * in is not enough for a thing that cannot be undone, and a session left open on a desk
 * should not be either.
 *
 * The server refuses a workspace that still holds business records and returns the counts
 * rather than a bare failure, so this can say what is in the way and point at Archive --
 * which is the operation that does exist for a workspace with history in it.
 */
function renderDeleteWorkspaceModal(companyId, workspaceId) {
  const workspace = state.operationalWorkspaces.find((item) => item.id === workspaceId);
  if (!workspace) return renderModalShell('Workspaces', 'Delete workspace', emptyState('That workspace is no longer available.'));
  const blocking = state.deleteWorkspaceBlocking;
  const blockingRows = blocking
    ? Object.entries(blocking).filter(([, count]) => Number(count) > 0)
    : [];
  return renderModalShell('Workspaces', 'Delete workspace', `
    <form class="compact-tool-form" data-delete-workspace-form>
      <input type="hidden" name="workspace_id" value="${h(workspace.id)}" />
      <p class="chat-leave-lead">${h(`"${workspace.name}" and its configuration are removed for everyone.`)}</p>
      <ul class="chat-leave-points">
        <li><i class="ti ti-alert-triangle" aria-hidden="true"></i>${h('This cannot be undone.')}</li>
        <li><i class="ti ti-check" aria-hidden="true"></i>${h('Its apps, member assignments, pipeline stages and setup answers go with it.')}</li>
        <li><i class="ti ti-check" aria-hidden="true"></i>${h('Sibling workspaces, the company, its people and every other record are untouched.')}</li>
      </ul>
      ${blockingRows.length ? `
        <div class="company-setup-alert danger">
          <i class="ti ti-alert-circle"></i>
          <div>
            <strong>This workspace still holds records</strong>
            <span>${h(blockingRows.map(([label, count]) => `${count} ${label}`).join(', '))}. Move or delete them first, or archive the workspace instead to keep its history.</span>
          </div>
        </div>` : ''}
      ${isLiveSupabaseSession() ? reauthPasswordField('deleteWorkspacePw', 'Confirm your password') : ''}
      ${state.deleteWorkspaceError ? `<div class="form-message error">${h(state.deleteWorkspaceError)}</div>` : ''}
      <div class="form-actions">
        <button class="btn danger" type="submit"><i class="ti ti-trash"></i>Delete workspace</button>
        <button class="btn" type="button" data-action="close-modal">Cancel</button>
      </div>
    </form>
  `, 'task-modal');
}

/**
 * Confirm the password, then ask the server to delete.
 *
 * The password is checked first so a wrong one costs nothing, and the refusal path keeps the
 * dialog open carrying the counts rather than closing on a toast the person cannot act on.
 */
async function deleteOperationalWorkspace(formNode, workspaceId, password) {
  const companyId = activeCompanyId();
  const workspace = state.operationalWorkspaces.find((item) => item.id === workspaceId);
  if (!workspace) return;
  if (!isCompanyOwner(companyId)) {
    state.deleteWorkspaceError = 'Owner access is required to delete a workspace.';
    render();
    return;
  }
  if (isLiveSupabaseSession()) {
    const check = await confirmAccountPassword(password);
    if (!check.ok) {
      state.deleteWorkspaceError = check.error;
      render();
      return;
    }
    const client = createSupabaseClient();
    const result = await safeSupabaseQuery(client.rpc('delete_workspace', { target_workspace_id: workspaceId }));
    if (result.error) {
      state.deleteWorkspaceError = result.error.message || 'The workspace could not be deleted.';
      render();
      return;
    }
    if (result.data && result.data.deleted === false) {
      state.deleteWorkspaceBlocking = result.data.blocking || {};
      state.deleteWorkspaceError = '';
      render();
      return;
    }
  }
  state.operationalWorkspaces = state.operationalWorkspaces.filter((item) => item.id !== workspaceId);
  state.workspaceMemberships = state.workspaceMemberships.filter((item) => item.workspace_id !== workspaceId);
  state.workspacePlugins = state.workspacePlugins.filter((item) => item.workspace_id !== workspaceId);
  // Deleting the one you were looking at leaves the selection pointing at nothing; clearing
  // it lets activeWorkspaceId() fall back to the company default on the next read.
  if (state.activeWorkspaceId === workspaceId) {
    state.activeWorkspaceId = '';
    localStorage.removeItem(ACTIVE_WORKSPACE_KEY);
  }
  state.modal = '';
  state.deletingWorkspaceId = '';
  state.deleteWorkspaceBlocking = null;
  persistAll();
  showToast(`"${workspace.name}" deleted.`, isLiveSupabaseSession() ? 'live' : 'local', 'Workspaces');
  render();
}

function renderActivityTaskModal(companyId, actId) {
  const workspace = wbCompanyWorkspace(companyId);
  const entry = workspace ? (workspace.activity || []).find((item) => item.id === actId) : null;
  if (!entry) return renderModalShell('Workspaces', 'New task', emptyState('That activity is no longer available.'));
  const members = wbMembers(companyId);
  return renderModalShell('Workspaces', 'New task from activity', `
    <form class="compact-tool-form" data-wb-activity-task-form>
      <input type="hidden" name="activity_id" value="${h(entry.id)}" />
      <p class="form-note">${h(wbActivityPlainText(entry))}</p>
      ${field('Task title', 'title', wbActivityPlainText(entry).slice(0, 120), true)}
      <label><span>Assign to</span><select name="assignee_id"><option value="">Me</option>${members.map((member) => `<option value="${h(member.id)}">${h(member.name)}</option>`).join('')}</select></label>
      ${field('Due date', 'due', '', false, 'date')}
      <div class="form-actions">
        <button class="btn btn-primary" type="submit"><i class="ti ti-circle-check"></i>Create task</button>
        <button class="btn" type="button" data-action="close-modal">Cancel</button>
      </div>
    </form>
  `, 'task-modal');
}

function renderRemoveMemberModal(key) {
  const [companyId, profileId] = String(key || '').split(':');
  const user = companyAccessUsers(companyId).find((item) => item.profile_id === profileId);
  if (!user) return renderModalShell('Users', 'Remove from company', emptyState('That member was not found.'));
  return renderModalShell('Users', 'Remove from company', `
    <p class="chat-leave-lead">${h(`${userDisplayName(user)} loses access to ${companyName(companyId)}.`)}</p>
    <ul class="chat-leave-points">
      <li><i class="ti ti-check" aria-hidden="true"></i>${h('Everything they did stays: jobs, tasks, messages, files and time all keep their name on them.')}</li>
      <li><i class="ti ti-check" aria-hidden="true"></i>${h('Their Questbase account is untouched. Any other company they belong to is unaffected.')}</li>
      <li><i class="ti ti-check" aria-hidden="true"></i>${h('You can invite the same email again later and they come straight back.')}</li>
      <li><i class="ti ti-alert-triangle" aria-hidden="true"></i>${h('Their role and workspace assignments here are gone and would need setting up again.')}</li>
    </ul>
    <p class="form-note">${h('To stop them signing in but keep their access ready, suspend them instead.')}</p>
    <div class="modal-actions">
      <button class="btn" type="button" data-action="cancel-remove-member">Cancel</button>
      <button class="btn danger" type="button" data-action="confirm-remove-member" data-company-id="${h(companyId)}" data-profile-id="${h(profileId)}">
        <i class="ti ti-user-minus"></i>Remove from company
      </button>
    </div>
  `, 'task-modal');
}

// The stored vocabulary is what the database has always used; only the words shown changed.
// 'disabled' is renamed Suspended because that is what it does -- the seat and every row stay
// exactly where they are, and the person simply stops being an active member until somebody
// sets them back. Renaming the value itself would have meant migrating live rows to buy a
// nicer string, which is not a trade worth making.
const MEMBERSHIP_STATUS_OPTIONS = [
  ['active', 'Active'],
  ['pending', 'Pending'],
  ['disabled', 'Suspended'],
  ['left', 'Left'],
];

function membershipStatusLabel(status) {
  const match = MEMBERSHIP_STATUS_OPTIONS.find(([value]) => value === status);
  return match ? match[1] : titleCase(status || '');
}

/**
 * Suspend or reactivate somebody, without touching their role.
 *
 * Reuses update_company_member_access, which already refuses the main owner, refuses an
 * Owner or Developer unless the actor is an Owner, and writes the audit event. Passing the
 * role they already hold keeps this about the status and nothing else.
 */
async function setMemberSuspension(companyId, profileId, suspended) {
  if (!requirePermission('users.manage', companyId, 'Your role cannot change member access.', 'Users')) return;
  const membership = membershipForProfile(companyId, profileId);
  if (!membership) return;
  const status = suspended ? 'disabled' : 'active';
  if (membership.status === status) return;
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await safeSupabaseQuery(client.rpc('update_company_member_access', {
      target_company_id: companyId,
      target_profile_id: profileId,
      target_role: membership.role,
      target_role_id: state.roleAssignments.find((item) => item.company_id === companyId && item.profile_id === profileId)?.role_id || null,
      target_status: status,
    }));
    if (result.error) {
      showToast(result.error.message || 'Could not change that access.', 'local', 'Users');
      return;
    }
  }
  state.memberships = state.memberships.map((item) => (
    item.company_id === companyId && item.profile_id === profileId ? { ...item, status } : item
  ));
  persistAll();
  showToast(suspended
    ? 'Suspended. They keep their account and their work, and can reach nothing here until you reactivate them.'
    : 'Reactivated. Their access is back exactly as it was.', isLiveSupabaseSession() ? 'live' : 'local', 'Users');
  render();
}

/**
 * Take somebody's seat back.
 *
 * Deletes the membership, the role assignment and the workspace assignments for this company.
 * Their profile stays, and so does everything they wrote -- jobs, tasks, messages, time --
 * because that is the company's record, not theirs to take away. Inviting the same email
 * again puts them straight back.
 *
 * Their Questbase ACCOUNT is not deleted, deliberately: a person can hold seats in several
 * companies, and one company removing them must not sign them out of the others.
 */
async function removeCompanyMember(companyId, profileId) {
  if (!requirePermission('users.manage', companyId, 'Your role cannot change member access.', 'Users')) return;
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await safeSupabaseQuery(client.rpc('remove_company_member', {
      target_company_id: companyId,
      target_profile_id: profileId,
    }));
    if (result.error) {
      showToast(result.error.message || 'Could not remove that person.', 'local', 'Users');
      return;
    }
  }
  const companyWorkspaceIds = new Set(state.operationalWorkspaces
    .filter((workspace) => workspace.company_id === companyId).map((workspace) => workspace.id));
  state.memberships = state.memberships.filter((item) => !(item.company_id === companyId && item.profile_id === profileId));
  state.roleAssignments = state.roleAssignments.filter((item) => !(item.company_id === companyId && item.profile_id === profileId));
  state.workspaceMemberships = state.workspaceMemberships.filter((item) => !(
    companyWorkspaceIds.has(item.workspace_id) && item.profile_id === profileId
  ));
  state.removingMemberId = '';
  state.modal = '';
  persistAll();
  showToast('Removed from this company. Their work stays on the record, and you can invite them again any time.', isLiveSupabaseSession() ? 'live' : 'local', 'Users');
  render();
}

async function persistUserAccess(formNode, { companyId, profileId, role, status, data }) {
  const selectedWorkspaceIds = new Set(data.getAll('workspace_ids').map((value) => String(value || '')));
  const companyWorkspaces = state.operationalWorkspaces.filter((workspace) => workspace.company_id === companyId && workspace.status === 'active');

  const membership = normalizeMembership({
    company_id: companyId,
    profile_id: profileId,
    role: membershipRoleForRole(role),
    status,
  });
  const previousMembership = membershipForProfile(companyId, profileId);
  const assignment = normalizeRoleAssignment({
    company_id: companyId,
    profile_id: profileId,
    role_id: role.id,
    assigned_by: activeSession().profile.id,
  });
  const client = createSupabaseClient();

  if (isLiveSupabaseSession() && client) {
    const canPersistRoleAssignment = isUuid(role.id);
    const membershipResult = await client.rpc('update_company_member_access', {
      target_company_id: companyId,
      target_profile_id: profileId,
      target_role: membership.role,
      target_role_id: canPersistRoleAssignment ? role.id : null,
      target_status: status,
    });
    if (membershipResult.error) {
      accessSaveFailed(membershipResult.error.message || 'Access update failed.');
      return;
    }
    upsertMembership(normalizeMembership(membershipResult.data || membership));
    if (canPersistRoleAssignment) replaceRoleAssignment(assignment);
    state.sync = { label: canPersistRoleAssignment ? 'User access saved' : 'Membership saved; create a role to assign permissions', mode: 'live' };
  } else {
    upsertMembership(membership);
    replaceRoleAssignment(assignment);
    state.sync = { label: 'User access saved locally', mode: 'local' };
  }

  const inheritedWorkspaceAccess = ['owner', 'admin', 'developer'].includes(String(membership.role || '').toLowerCase());
  for (const workspace of companyWorkspaces) {
    const enabled = status === 'active' && (inheritedWorkspaceAccess || selectedWorkspaceIds.has(workspace.id));
    const requestedWorkspaceRoleId = String(data.get(`workspace_role:${workspace.id}`) || role.id || '');
    const workspaceRole = roleById(companyId, requestedWorkspaceRoleId) || role;
    const workspaceMembership = normalizeWorkspaceMembership({
      workspace_id: workspace.id,
      profile_id: profileId,
      role_id: workspaceRole?.id || '',
      status: enabled ? 'active' : 'disabled',
      assigned_by: activeSession().profile.id,
      updated_at: new Date().toISOString(),
    });
    if (isLiveSupabaseSession() && client) {
      const result = await safeSupabaseQuery(client.rpc('set_workspace_member', {
        target_workspace_id: workspace.id,
        target_profile_id: profileId,
        target_role_id: isUuid(workspaceMembership.role_id) ? workspaceMembership.role_id : null,
        next_status: enabled ? 'active' : 'disabled',
      }));
      if (result.error) {
        state.sync = { label: result.error.message || 'Workspace assignment failed', mode: 'local' };
        showToast(result.error.message || 'Workspace assignment failed.', 'local', 'Users');
        render();
        return;
      }
      upsertWorkspaceMembership(normalizeWorkspaceMembership(result.data || workspaceMembership));
    } else {
      upsertWorkspaceMembership(workspaceMembership);
    }
  }

  // Only announce a change that happened. Saving this form to adjust workspace assignments
  // left the role and status untouched, yet still told everyone with users.manage that the
  // access had been updated -- which is most of the notification fatigue the audit measured.
  const identityChanged = previousMembership?.role !== membership.role
    || previousMembership?.status !== membership.status;
  if (identityChanged) {
    notifyLocalEvent('access.role', 'User access updated', `${actorName()} set ${profileName(profileId)} to ${role.name} / ${titleCase(status)}.`, companyPath('users', { tab: 'access' }, companyId), 'membership', profileId, companyId, [profileId].concat(usersWithAnyPermission(companyId, ['users.manage', 'settings.manage'])));
    // The audit row is written by update_company_member_access, inside the same statement
    // that makes the change. Recording a second one here is what produced two audit entries
    // for every single access save.
    if (!isLiveSupabaseSession()) {
      recordAuditEvent(companyId, membershipAuditEventType(previousMembership, membership), 'membership', profileId, { role: role.name, status });
    }
  }
  render();
}

async function updateJoinRequest(requestId, status) {
  const request = state.joinRequests.find((item) => item.id === requestId);
  if (!request || !['approved', 'rejected'].includes(status)) return;
  if (!requirePermission('users.manage', request.company_id, 'Your role cannot manage access requests.', 'Users')) return;
  const client = createSupabaseClient();
  const nextRequest = normalizeJoinRequest({ ...request, status });
  const membership = normalizeMembership({
    company_id: request.company_id,
    profile_id: request.profile_id,
    role: 'member',
    status: status === 'approved' ? 'active' : 'disabled',
  });

  if (isLiveSupabaseSession() && client) {
    const requestResult = await client.rpc('review_company_join_request', {
      target_request_id: request.id,
      decision: status,
      target_role_id: null,
    });
    if (requestResult.error) {
      state.sync = { label: requestResult.error.message || 'Request update failed', mode: 'local' };
      render();
      return;
    }
    if (status === 'approved') upsertMembership(membership);
    state.sync = { label: status === 'approved' ? 'Access approved' : 'Request rejected', mode: 'live' };
  } else {
    if (status === 'approved') upsertMembership(membership);
    state.sync = { label: status === 'approved' ? 'Access approved locally' : 'Request rejected locally', mode: 'local' };
  }

  state.joinRequests = state.joinRequests.map((item) => (item.id === request.id ? nextRequest : item));
  recordAuditEvent(request.company_id, status === 'approved' ? 'join.approved' : 'join.rejected', 'join_request', request.id, { email: request.requested_email });
  notifyLocalEvent('access.request', status === 'approved' ? 'Access approved' : 'Access rejected', `${actorName()} ${status === 'approved' ? 'approved' : 'rejected'} ${request.requested_email || 'a join request'}.`, companyPath('users', { tab: 'invites' }, request.company_id), 'join_request', request.id, request.company_id, [request.profile_id].concat(usersWithAnyPermission(request.company_id, ['users.manage', 'settings.manage'])));
  persistAll();
  render();
}

async function saveMessageGroup(form) {
  const companyId = activeCompanyId();
  if (!can('messages.create_group', companyId)) {
    showToast('Your role cannot create group chats.', 'local', 'Messages');
    return;
  }
  // beginSubmitting returns null for a button it has already disabled, so a second click
  // while the first is still in flight stops here instead of creating another group.
  const done = beginSubmitting(form, 'Creating…');
  if (!done) return;
  try {
    await createMessageGroup(form, companyId);
  } finally {
    done();
  }
}

async function createMessageGroup(form, companyId) {
  const data = new FormData(form);
  const type = ['company', 'role', 'custom'].includes(data.get('type')) ? String(data.get('type')) : 'custom';
  const conversation = normalizeMessageConversation({
    id: crypto.randomUUID(),
    company_id: companyId,
    title: String(data.get('title') || '').trim() || 'New group chat',
    type,
    created_by: activeSession().profile.id,
    icon_key: data.get('icon_key') || '',
    icon_image: data.get('icon_image') || '',
    last_message_at: new Date().toISOString(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });
  const accessRows = messageAccessFromForm(data, conversation, type);
  if (!accessRows.some((row) => row.target_type === 'profile' && row.target_id === activeSession().profile.id) && type !== 'company') {
    accessRows.push(normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: companyId, conversation_id: conversation.id, target_type: 'profile', target_id: activeSession().profile.id }));
  }
  const saved = await persistConversation(conversation, accessRows);
  if (!saved) return;
  state.selectedConversationId = conversation.id;
  state.modal = '';
  notifyLocalEvent('message.group', 'Group chat created', `${actorName()} created ${conversation.title}.`, companyPath('messages', { conversation: conversation.id }, companyId), 'message_conversation', conversation.id, companyId, conversationNotificationRecipients(conversation));
  navigate(companyPath('messages', { conversation: conversation.id }, companyId), { replace: true });
}

async function saveDirectMessage(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('messages.send', companyId, 'Your role cannot start direct messages.', 'Messages')) return;
  const data = new FormData(form);
  const targetId = String(data.get('profile_id') || '').trim();
  if (!targetId) {
    showToast('Choose a person first.', 'local', 'Messages');
    return;
  }
  // beginSubmitting returns null for a button it has already disabled, so a second click
  // while the first is still working stops right here rather than starting another chat.
  const done = beginSubmitting(form, 'Starting…');
  if (!done) return;
  try {
    const body = String(data.get('body') || '').trim();
    // Ask the starter rather than building a conversation outright. It finds an existing chat
    // with this person, joins one already being created, and only makes a new one when there
    // genuinely is none. Creating one unconditionally -- which is what this did -- is why
    // picking the same person again produced a second chat every time.
    const conversationId = await startDirectMessageWithProfile(companyId, targetId, { navigate: false });
    if (!conversationId) return;
    const conversation = state.messageConversations.find((item) => item.id === conversationId);
    // The first message goes into whichever conversation that turned out to be, so writing to
    // somebody you already talk to continues that thread instead of forking it.
    if (body && conversation) await createMessageRecord(conversation, body, []);
    state.selectedConversationId = conversationId;
    state.modal = '';
    navigate(companyPath('messages', { conversation: conversationId }, companyId), { replace: true });
  } finally {
    done();
  }
}

/**
 * Direct-message creates that are already running, keyed by company + the pair of profiles.
 *
 * The "do we already have this chat?" check reads local state, but state does not carry the
 * new conversation until persistConversation has finished two network round-trips. A second
 * click inside that window saw nothing and started another chat. Three clicks inside 1.1
 * seconds produced three identical conversations with the same person in production.
 */
const directMessageInFlight = new Map();

function directMessagePairKey(companyId, profileId, targetId) {
  return `${companyId}:${[String(profileId), String(targetId)].sort().join('|')}`;
}

/** Join the create already running for this pair, or start it and hold the slot. */
async function openOrCreateDirect(flightKey, companyId, goToMessages, make) {
  const inFlight = directMessageInFlight.get(flightKey);
  if (inFlight) {
    const existingId = await inFlight;
    if (existingId) {
      state.selectedConversationId = existingId;
      state.modal = '';
      if (goToMessages) navigate(companyPath('messages', { conversation: existingId }, companyId), { replace: true });
    }
    return existingId;
  }
  const create = make();
  directMessageInFlight.set(flightKey, create);
  try {
    return await create;
  } finally {
    // Cleared even when the create throws, or the pair stays wedged for the whole session.
    directMessageInFlight.delete(flightKey);
  }
}

async function startDirectMessageWithProfile(companyId, targetId, options = {}) {
  const goToMessages = options.navigate !== false;
  const cleanTargetId = String(targetId || '').trim();
  const profile = activeSession().profile;
  if (!cleanTargetId) {
    showToast('Choose a workspace member first.', 'local', 'Messages');
    return;
  }
  if (cleanTargetId === profile.id) {
    await startSelfMessage(companyId);
    return;
  }
  const existing = allCompanyConversations(companyId).find((conversation) => {
    if (conversation.type !== 'direct') return false;
    const rowIds = conversationAccessRows(conversation.id)
      .filter((row) => row.target_type === 'profile')
      .map((row) => row.target_id)
      .sort();
    return rowIds.length === 2 && rowIds[0] === [profile.id, cleanTargetId].sort()[0] && rowIds[1] === [profile.id, cleanTargetId].sort()[1];
  });
  if (existing) {
    state.selectedConversationId = existing.id;
    state.modal = '';
    if (goToMessages) navigate(companyPath('messages', { conversation: existing.id }, companyId), { replace: true });
    return existing.id;
  }
  const flightKey = directMessagePairKey(companyId, profile.id, cleanTargetId);
  return openOrCreateDirect(flightKey, companyId, goToMessages, () => (
    createDirectConversation(companyId, cleanTargetId, profile, goToMessages)
  ));
}

async function createDirectConversation(companyId, cleanTargetId, profile, goToMessages) {
  const targetUser = companyAccessUsers(companyId).find((user) => (user.profile_id || user.member_id) === cleanTargetId);
  const now = new Date().toISOString();
  const conversation = normalizeMessageConversation({
    id: crypto.randomUUID(),
    company_id: companyId,
    title: targetUser?.name || profileName(cleanTargetId),
    type: 'direct',
    created_by: profile.id,
    last_message_at: now,
    created_at: now,
    updated_at: now,
  });
  const accessRows = [
    normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: companyId, conversation_id: conversation.id, target_type: 'profile', target_id: profile.id }),
    normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: companyId, conversation_id: conversation.id, target_type: 'profile', target_id: cleanTargetId }),
  ];
  const saved = await persistConversation(conversation, accessRows);
  if (!saved) return '';
  state.selectedConversationId = conversation.id;
  state.modal = '';
  notifyLocalEvent('message.direct', 'Direct message started', `${actorName()} started a direct message with ${conversation.title}.`, companyPath('messages', { conversation: conversation.id }, companyId), 'message_conversation', conversation.id, companyId, [cleanTargetId]);
  if (goToMessages) navigate(companyPath('messages', { conversation: conversation.id }, companyId), { replace: true });
  return conversation.id;
}

async function startSelfMessage(companyId) {
  const profile = activeSession().profile;
  const existing = allCompanyConversations(companyId).find((conversation) => {
    if (conversation.type !== 'direct') return false;
    const rows = conversationAccessRows(conversation.id).filter((row) => row.target_type === 'profile');
    return rows.length === 1 && rows[0].target_id === profile.id;
  });
  if (existing) {
    state.selectedConversationId = existing.id;
    state.modal = '';
    navigate(companyPath('messages', { conversation: existing.id }, companyId), { replace: true });
    return;
  }
  // Same race as the two-person case: the note above directMessageInFlight applies here too.
  const flightKey = directMessagePairKey(companyId, profile.id, profile.id);
  await openOrCreateDirect(flightKey, companyId, true, () => createSelfConversation(companyId, profile));
}

async function createSelfConversation(companyId, profile) {
  const now = new Date().toISOString();
  const conversation = normalizeMessageConversation({
    id: crypto.randomUUID(),
    company_id: companyId,
    title: 'Notes to self',
    type: 'direct',
    created_by: profile.id,
    last_message_at: now,
    created_at: now,
    updated_at: now,
  });
  const accessRows = [
    normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: companyId, conversation_id: conversation.id, target_type: 'profile', target_id: profile.id }),
  ];
  const saved = await persistConversation(conversation, accessRows);
  if (!saved) return;
  state.selectedConversationId = conversation.id;
  state.modal = '';
  navigate(companyPath('messages', { conversation: conversation.id }, companyId), { replace: true });
  return conversation.id;
}

async function saveMessageAccess(form) {
  const companyId = activeCompanyId();
  if (!can('messages.manage_groups', companyId) && !can('messages.manage', companyId)) {
    showToast('Your role cannot manage chat access.', 'local', 'Messages');
    return;
  }
  const conversation = state.messageConversations.find((item) => item.id === form.dataset.conversationId);
  if (!conversation) return;
  const data = new FormData(form);
  const next = normalizeMessageConversation({
    ...conversation,
    title: String(data.get('title') || '').trim() || conversation.title,
    type: MESSAGE_TYPES.includes(data.get('type')) ? String(data.get('type')) : conversation.type,
    icon_key: data.has('icon_key') ? data.get('icon_key') : conversation.icon_key,
    icon_image: data.has('icon_image') ? data.get('icon_image') : conversation.icon_image,
    updated_at: new Date().toISOString(),
  });
  const accessRows = messageAccessFromForm(data, next, next.type);
  if (next.type !== 'company' && !accessRows.some((row) => row.target_type === 'profile' && row.target_id === activeSession().profile.id)) {
    accessRows.push(normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: companyId, conversation_id: next.id, target_type: 'profile', target_id: activeSession().profile.id }));
  }
  const previousRecipients = conversationNotificationRecipients(conversation);
  const saved = await persistConversation(next, accessRows, true);
  if (!saved) return;
  const addedRecipients = conversationNotificationRecipients(next).filter((profileId) => !previousRecipients.includes(profileId));
  if (addedRecipients.length) {
    notifyLocalEvent('message.group', 'Added to chat', `${actorName()} added you to ${next.title}.`, companyPath('messages', { conversation: next.id }, companyId), 'message_conversation', next.id, companyId, addedRecipients);
  }
  state.modal = '';
  showToast('Chat access saved.', state.session?.auth === 'supabase' ? 'live' : 'local', 'Messages');
  render();
}

async function sendMessage(form) {
  const conversation = state.messageConversations.find((item) => item.id === form.dataset.conversationId);
  if (!conversation) return;
  if (!can('messages.send', conversation.company_id)) {
    showToast('Your role cannot send messages.', 'local', 'Messages');
    return;
  }
  const data = new FormData(form);
  const body = String(data.get('body') || '').trim();
  // The chips are the source of truth: the input is cleared on every pick so the same file
  // can be chosen twice, and a re-render would have emptied it anyway.
  const files = messageComposerFiles(conversation.id).concat(Array.from(form.elements.attachments?.files || []));
  if (!body && !files.length) {
    showToast('Type a message or attach a file.', 'local', 'Messages');
    return;
  }
  if (files.length && !can('messages.attach_files', conversation.company_id)) {
    showToast('Your role cannot attach files.', 'local', 'Messages');
    return;
  }
  // Lock the submit button for the duration of the (possibly slow) upload + write
  // so a second tap or Enter can't fire a duplicate send. A successful send
  // re-renders, replacing the button; the finally only re-enables on the paths
  // that leave the current DOM in place.
  const submitButton = form.querySelector('[type="submit"]');
  if (submitButton?.disabled) return;
  if (submitButton) { submitButton.disabled = true; submitButton.setAttribute('aria-busy', 'true'); }
  try {
    for (const file of files) { if (!(await guardUpload(file, 'document', 'Messages'))) return; }
    await createMessageRecord(conversation, body, files);
    messageDraftFiles.delete(conversation.id);
    form.reset();
    render();
  } finally {
    if (submitButton?.isConnected) { submitButton.disabled = false; submitButton.removeAttribute('aria-busy'); }
  }
}

async function saveCalendarEvent(form) {
  const companyId = activeCompanyId();
  const fields = Object.fromEntries(new FormData(form).entries());
  const existing = fields.id ? manualCalendarEventById(String(fields.id)) : null;
  if (!existing && !can('calendar.manage', companyId)) {
    showToast('Your role cannot create or edit calendar events.', 'local', 'Calendar');
    return;
  }
  if (existing && !canEditCalendarEvent(existing)) {
    showToast('This event cannot be edited from Calendar.', 'local', 'Calendar');
    return;
  }
  const linkedJobId = String(fields.linked_job_id || '').trim();
  const now = new Date().toISOString();
  const startsAtIso = localDateTimeToIso(fields.starts_at);
  const endsAtIso = localDateTimeToIso(fields.ends_at || fields.starts_at);
  if (Date.parse(endsAtIso) < Date.parse(startsAtIso)) {
    showToast('End date must be the same as or after the start date.', 'local', 'Calendar');
    return;
  }
  let eventRecord = normalizeCalendarEvent({
    ...(existing || {}),
    id: existing?.id || crypto.randomUUID(),
    company_id: companyId,
    title: String(fields.title || '').trim() || 'Calendar event',
    description: String(fields.description || '').trim(),
    event_type: CALENDAR_EVENT_TYPES.includes(fields.event_type) ? String(fields.event_type) : 'Company event',
    starts_at: startsAtIso,
    ends_at: endsAtIso,
    all_day: fields.all_day === 'on',
    visibility: fields.visibility === 'private' ? 'private' : 'company',
    linked_type: linkedJobId ? 'job' : '',
    linked_id: linkedJobId,
    assigned_profile_id: String(fields.assigned_profile_id || ''),
    created_by: existing?.created_by || activeSession().profile.id,
    created_at: existing?.created_at || now,
    updated_at: now,
  });
  // The button said nothing while the write was in flight, so a slow save read as a hang and
  // invited a second press -- the same shape as the access form and the chat starters.
  const done = beginSubmitting(form, 'Saving…');
  if (!done) return;
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const payload = calendarEventPayload(eventRecord);
    if (existing) delete payload.id;
    try {
      const result = existing
        ? await client.from('calendar_events').update({ ...payload, updated_at: now }).eq('id', existing.id).select().single()
        : await client.from('calendar_events').insert(payload).select().single();
      if (result.error) {
        showToast(result.error.message || 'Calendar event save failed.', 'local', 'Calendar');
        return;
      }
      eventRecord = normalizeCalendarEvent(result.data);
    } finally {
      done();
    }
  } else {
    done();
  }
  state.calendarEvents = [eventRecord].concat(state.calendarEvents.filter((item) => item.id !== eventRecord.id));
  persistCalendarEvents();
  notifyLocalEvent('calendar.event', existing ? 'Calendar event updated' : 'Calendar event created', `${actorName()} ${existing ? 'updated' : 'created'} ${eventRecord.title}.`, companyPath('calendar', {}, companyId), 'calendar_event', eventRecord.id, companyId);
  state.selectedCalendarEventId = `manual:${eventRecord.id}`;
  state.modal = 'calendar-event-detail';
  render();
}

async function deleteCalendarEvent(eventId) {
  const eventRecord = manualCalendarEventById(eventId);
  if (!eventRecord || !canEditCalendarEvent(eventRecord)) {
    showToast('This event cannot be deleted from Calendar.', 'local', 'Calendar');
    return;
  }
  await recycleDeleteRecord({ type: 'calendar_event', id: eventRecord.id });
}

async function createMessageRecord(conversation, body, files) {
  const now = new Date().toISOString();
  const message = normalizeMessage({
    id: crypto.randomUUID(),
    conversation_id: conversation.id,
    company_id: conversation.company_id,
    sender_profile_id: activeSession().profile.id,
    body,
    message_type: files.length ? 'attachment' : 'text',
    created_at: now,
    updated_at: now,
  });
  const client = createSupabaseClient();
  let savedMessage = message;
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('messages').insert(messagePayload(message)).select().single();
    if (result.error) {
      showToast(result.error.message || 'Message send failed.', 'local', 'Messages');
      return null;
    }
    savedMessage = normalizeMessage(result.data);
  }
  state.messages = state.messages.concat(savedMessage);
  const attachments = await saveMessageAttachments(savedMessage, files);
  const updatedConversation = { ...conversation, last_message_at: savedMessage.created_at, updated_at: savedMessage.created_at };
  state.messageConversations = state.messageConversations.map((item) => (item.id === conversation.id ? updatedConversation : item));
  if (isLiveSupabaseSession() && client) {
    const lastMessageBump = await client.from('message_conversations').update({ last_message_at: savedMessage.created_at, updated_at: savedMessage.created_at }).eq('id', conversation.id);
    if (lastMessageBump.error) console.warn('Could not bump conversation last_message_at; list ordering may lag until the next sync.', lastMessageBump.error);
  }
  markConversationRead(conversation.id, false);
  notifyMessageEvents(updatedConversation, savedMessage, attachments);
  persistMessages();
  return savedMessage;
}

async function saveMessageAttachments(message, files) {
  const client = createSupabaseClient();
  const saved = [];
  for (const file of files) {
    const id = crypto.randomUUID();
    const objectPath = `${message.company_id}/${message.conversation_id}/${id}-${slugify(file.name || 'attachment')}`;
    let previewUrl = '';
    let objectSaved = '';
    if (isLiveSupabaseSession() && client) {
      const upload = await client.storage
        .from('quest-message-attachments')
        .upload(objectPath, file, { cacheControl: '3600', upsert: false, contentType: contentTypeFor(file) });
      if (upload.error) {
        showToast(upload.error.message || 'Attachment upload failed.', 'local', 'Messages');
        continue;
      }
      objectSaved = objectPath;
    } else if (file.type?.startsWith('image/') && file.size <= 220000) {
      previewUrl = await fileToDataUrl(file);
    }
    const attachment = normalizeMessageAttachment({
      id,
      conversation_id: message.conversation_id,
      message_id: message.id,
      company_id: message.company_id,
      bucket_id: 'quest-message-attachments',
      object_path: objectSaved,
      file_name: file.name || 'attachment',
      mime_type: file.type || 'application/octet-stream',
      size_bytes: file.size || 0,
      preview_url: previewUrl,
      created_at: new Date().toISOString(),
    });
    if (isLiveSupabaseSession() && client) {
      const result = await client.from('message_attachments').insert(messageAttachmentPayload(attachment)).select().single();
      if (result.error) {
        showToast(result.error.message || 'Attachment record failed.', 'local', 'Messages');
        if (objectSaved) await client.storage.from('quest-message-attachments').remove([objectSaved]);
        continue;
      }
      saved.push(normalizeMessageAttachment(result.data));
    } else {
      saved.push(attachment);
    }
  }
  state.messageAttachments = state.messageAttachments.concat(saved);
  return saved;
}

async function persistConversation(conversation, accessRows, update = false) {
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    // No .select() on the insert. PostgREST turns that into INSERT ... RETURNING, and
    // Postgres applies the SELECT policy to the returned row. A brand-new conversation
    // has no message_conversation_access rows yet, so can_access_message_conversation()
    // cannot see it and the statement fails with "new row violates row-level security
    // policy" — which reads like the insert was rejected when it is really the read-back.
    // The access rows are written immediately after, and the locally built row is already
    // the same data, so there is nothing to gain from reading it back here.
    const conversationResult = update
      ? await client.from('message_conversations').update(messageConversationPayload(conversation)).eq('id', conversation.id).select().single()
      : await client.from('message_conversations').insert(messageConversationPayload(conversation));
    if (conversationResult.error) {
      showToast(conversationResult.error.message || 'Conversation save failed.', 'local', 'Messages');
      return false;
    }
    const accessReset = await client.from('message_conversation_access').delete().eq('conversation_id', conversation.id);
    if (accessReset.error) {
      showToast(accessReset.error.message || 'Could not reset conversation access.', 'local', 'Messages');
      return false;
    }
    if (accessRows.length) {
      const accessResult = await client.from('message_conversation_access').insert(accessRows.map(messageAccessPayload));
      if (accessResult.error) {
        showToast(accessResult.error.message || 'Conversation access save failed.', 'local', 'Messages');
        return false;
      }
    }
    // Only the update path reads the row back; the insert path keeps the local object.
    if (conversationResult.data) conversation = normalizeMessageConversation(conversationResult.data);
    state.sync = { label: 'Quest Supabase live', mode: 'live' };
  }
  state.messageConversations = [conversation].concat(state.messageConversations.filter((item) => item.id !== conversation.id));
  state.messageAccess = accessRows.concat(state.messageAccess.filter((item) => item.conversation_id !== conversation.id));
  markConversationRead(conversation.id, false);
  persistMessages();
  return true;
}

/**
 * Write one of the two watermarks onto my own access row for a chat.
 *
 * Shared by clearConversation and leaveConversation because everything except the column and
 * the wording is identical: call the RPC, mark the row in memory, and let the accessors do
 * the rest. Neither touches a message, the conversation, or another person's access.
 *
 * The RPCs are SECURITY DEFINER because INSERT and UPDATE on message_conversation_access
 * require a manager permission -- without them a member could not clear or leave anything,
 * and anybody who could would have been able to do it to other people too. They also create
 * the row when my access came from an all_company row, a role, or from having created the
 * conversation, which is the case the old delete-the-row version silently did nothing for.
 */
async function markChatAccess(conversationId, mode) {
  const conversation = state.messageConversations.find((item) => item.id === conversationId);
  if (!conversation) return null;
  const profile = activeSession().profile;
  const rpc = mode === 'clear' ? 'clear_message_conversation' : 'leave_message_conversation';
  let at = new Date().toISOString();
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await safeSupabaseQuery(client.rpc(rpc, { target_conversation_id: conversationId }));
    if (result.error) {
      showToast(result.error.message || (mode === 'clear' ? 'Could not clear that chat.' : 'Could not leave that chat.'), 'local', 'Messages');
      return null;
    }
    // The procedure returns the instant it stamped; using the server's clock rather than
    // this browser's keeps the local window identical to the one RLS will apply.
    if (typeof result.data === 'string' && result.data) at = result.data;
  }
  const column = mode === 'clear' ? 'cleared_at' : 'left_at';
  const mine = myConversationAccessRows(conversationId);
  if (mine.length) {
    state.messageAccess = state.messageAccess.map((row) => (
      mine.includes(row) ? { ...row, [column]: at } : row
    ));
  } else {
    // No row of my own to mark, so the RPC made one. Mirror it rather than refetch.
    state.messageAccess = state.messageAccess.concat(normalizeMessageAccess({
      conversation_id: conversationId,
      company_id: conversation.company_id,
      target_type: 'profile',
      target_id: profile.id,
      created_at: at,
      [column]: at,
    }));
  }
  state.leavingConversationId = '';
  state.modal = '';
  persistMessages();
  return conversation;
}

/**
 * DELETE CHAT: clear my copy of the history and stay in the conversation.
 *
 * The chat starts again from empty for me. Everyone else keeps every message, and anything
 * sent from now on still reaches me -- which is the whole difference from leaving.
 */
async function clearConversation(conversationId) {
  const conversation = await markChatAccess(conversationId, 'clear');
  if (!conversation) return;
  // It has just left the list, so keeping it open would show a thread the list no longer
  // contains -- the same reason leaving deselects.
  if (state.selectedConversationId === conversationId) state.selectedConversationId = '';
  showToast(isConversationArchived(conversationId)
    ? 'Archived chat deleted.'
    : 'Chat deleted. You are still in it — it comes back with the next message.', isLiveSupabaseSession() ? 'live' : 'local', 'Messages');
  navigate(companyPath('messages', {}, conversation.company_id), { replace: true });
  render();
}

/**
 * LEAVE CHAT: stop receiving, and keep what was said up to now as an archive.
 */
async function leaveConversation(conversationId) {
  const conversation = await markChatAccess(conversationId, 'leave');
  if (!conversation) return;
  const isDirect = conversation.type === 'direct';
  // The thread is no longer in the working list, so showing it would be showing something
  // the sidebar does not contain.
  if (state.selectedConversationId === conversationId) state.selectedConversationId = '';
  showToast(isDirect ? 'Chat archived. You will not receive new messages in it.' : 'You left the chat. It is in Archived.', isLiveSupabaseSession() ? 'live' : 'local', 'Messages');
  navigate(companyPath('messages', {}, conversation.company_id), { replace: true });
  render();
}

async function deleteMessage(messageId) {
  const message = state.messages.find((item) => item.id === messageId);
  if (!message) return;
  const own = message.sender_profile_id === activeSession().profile.id;
  if (!((own && can('messages.delete_own', message.company_id)) || can('messages.delete_any', message.company_id))) {
    showToast('Your role cannot delete this message.', 'local', 'Messages');
    return;
  }
  const deletedAt = new Date().toISOString();
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('messages').update({ deleted_at: deletedAt, updated_at: deletedAt }).eq('id', message.id);
    if (result.error) {
      showToast(result.error.message || 'Message delete failed.', 'local', 'Messages');
      return;
    }
  }
  state.messages = state.messages.map((item) => (item.id === message.id ? { ...item, deleted_at: deletedAt, updated_at: deletedAt } : item));
  persistMessages();
  render();
}

async function openMessageAttachment(attachmentId) {
  const attachment = state.messageAttachments.find((item) => item.id === attachmentId);
  if (!attachment) return;
  if (attachment.preview_url) {
    window.open(attachment.preview_url, '_blank', 'noopener,noreferrer');
    return;
  }
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client && attachment.object_path) {
    const result = await client.storage.from(attachment.bucket_id || 'quest-message-attachments').createSignedUrl(attachment.object_path, 900, { download: attachment.file_name });
    if (!result.error && result.data?.signedUrl) {
      window.open(result.data.signedUrl, '_blank', 'noopener,noreferrer');
      return;
    }
  }
  showToast('This demo attachment is metadata-only.', 'local', 'Messages');
}

function onDocumentInput(event) {
  // Both paths, for the reason the job Client field taught us: typing fires input, and
  // picking from the datalist fires input too in Chromium but change in Firefox.
  if (event.target.matches('[data-wb-cc-name]')) syncCompanyContactPicker(event.target);
  if (event.target.matches('[data-wb-user-name]')) syncUserPicker(event.target);
  // The sheet's name is typed beside it and stored INSIDE the sheet, because that is what every
  // column, search result and export reads. The hidden input still carries the whole thing, so
  // the form's own save needs to know nothing about this.
  if (event.target.matches('[data-wb-sheet-name]')) {
    const holder = document.querySelector(`[data-f="${CSS.escape(event.target.dataset.wbSheetName)}"]`);
    if (holder) {
      let sheet;
      try { sheet = JSON.parse(holder.value || '{}'); } catch { sheet = {}; }
      sheet.title = event.target.value.slice(0, 120);
      holder.value = JSON.stringify(sheet);
      holder.dataset.wbSheetTitle = sheet.title || 'Sheet';
    }
    return;
  }
  // The visible box drives a hidden input, so an unchecked field still submits a value: a
  // missing key would be indistinguishable from a field somebody deleted.
  if (event.target.matches('[data-cc-check]')) {
    const name = event.target.dataset.ccCheck;
    const hidden = event.target.closest('label')?.querySelector(`input[type="hidden"][name="${CSS.escape(name)}"]`);
    if (hidden) hidden.value = event.target.checked ? 'yes' : 'no';
    const echo = event.target.closest('.cc-check')?.querySelector('em');
    if (echo) echo.textContent = event.target.checked ? 'Yes' : 'No';
    return;
  }
  if (event.target.matches('[data-company-contact-search]')) {
    state.companyContactQuery = event.target.value || '';
    render();
    // The re-render replaces the input, so put the caret back at the end.
    queueMicrotask(() => {
      const field = document.querySelector('[data-company-contact-search]');
      if (field) { field.focus(); field.setSelectionRange(field.value.length, field.value.length); }
    });
    return;
  }
  if (event.target.matches('[data-company-picker-search]')) {
    state.companyPickerQuery = event.target.value || '';
    render();
    // The re-render replaces the input, so put the caret back where it was.
    queueMicrotask(() => {
      const field = document.getElementById('companyPickerSearch');
      if (field) { field.focus(); field.setSelectionRange(field.value.length, field.value.length); }
    });
    return;
  }
  if (event.target.matches('[data-appearance-range]')) {
    // Live-apply the CSS variable + update the readout without a full re-render,
    // so dragging the slider stays smooth and the input keeps focus.
    const kind = event.target.dataset.appearanceRange === 'cardBlur' ? 'cardBlur' : 'cardOpacity';
    const value = Number(event.target.value);
    setAppearance({ [kind]: value });
    const out = event.target.closest('.appearance-range')?.querySelector('[data-appearance-out]');
    if (out) out.textContent = kind === 'cardOpacity' ? `${value}%` : `${value}px`;
    return;
  }
  if (event.target.matches('[data-appearance-card-color]')) {
    setAppearance({ cardColor: event.target.value });
    return;
  }
  // Live while dragging the picker, so the menu recolours under the cursor. No re-render:
  // that would tear down the open colour popup mid-drag.
  if (event.target.matches('[data-appearance-sidebar-bg]')) {
    setAppearance({ sidebarBg: event.target.value });
    return;
  }
  if (event.target.matches('[data-appearance-sidebar-text]')) {
    setAppearance({ sidebarText: event.target.value });
    return;
  }
  if (event.target.matches('[data-appearance-sidebar-accent]')) {
    setAppearance({ sidebarAccent: event.target.value });
    return;
  }
  if (event.target.matches('[data-underwriting-field]')) {
    // Only ever reachable while the underwriter page is on screen, which is what loaded it.
    renderUnderwriterPageModule?.syncUnderwritingForm(event.target.closest('[data-underwriting-form]'));
    return;
  }
  if (takeoffEvent(event, 'input')) return;
  if (event.target.closest?.('[data-f]')) wbSyncButtons(event.target.closest('form, .wb-modal, .wb-record-page'));
  if (event.target.matches('[data-wb-pal-find]')) {
    const q = event.target.value.trim().toLowerCase();
    event.target.closest('.wb-palette').querySelectorAll('.wb-palette-item').forEach((item) => {
      item.hidden = !!q && !item.textContent.toLowerCase().includes(q);
    });
    return;
  }
  if (event.target.matches('[data-phone-format]')) {
    // Only digits, '+' and '-' are allowed; strip anything else, then format.
    const cleaned = event.target.value.replace(/[^0-9+\-]/g, '');
    const formatted = formatPhoneNumber(cleaned);
    if (formatted !== event.target.value) event.target.value = formatted;
    return;
  }
  if (event.target.matches('[data-command-input]')) {
    // Update results in place without a full re-render, so the field keeps focus
    // and the caret position through every keystroke.
    state.commandPalette.query = event.target.value;
    state.commandPalette.index = 0;
    refreshCommandPaletteResults();
    return;
  }
  if (state.commandPalette.taskDraft && event.target.closest('[data-command-task-form]')) {
    // Mirror edits into the draft so a background re-render (realtime sync) can't
    // wipe what the user typed before they hit Create.
    const form = event.target.closest('[data-command-task-form]');
    const draft = state.commandPalette.taskDraft;
    draft.title = form.elements.title?.value ?? draft.title;
    draft.due = form.elements.due?.value ?? draft.due;
    draft.due_time = form.elements.due_time?.value ?? draft.due_time;
    draft.urgency = form.elements.priority?.value ?? draft.urgency;
    draft.assignee_id = form.elements.assignee_id?.value ?? draft.assignee_id;
    return;
  }
  if (state.commandPalette.contactDraft && event.target.closest('[data-command-contact-form]')) {
    const form = event.target.closest('[data-command-contact-form]');
    const draft = state.commandPalette.contactDraft;
    draft.name = form.elements.name?.value ?? draft.name;
    draft.email = form.elements.email?.value ?? draft.email;
    draft.phone = form.elements.phone?.value ?? draft.phone;
    return;
  }
  if (event.target.matches('[data-job-type-input]')) {
    // Picking a client that is already a contact carries their details across, so the job is
    // linked to the CRM record rather than repeating a name that only looks the same. A name
    // that matches nothing is left exactly as typed -- that is how a job gets opened for
    // somebody who is not in the CRM yet.
    if (event.target.name === 'client_name') fillJobClientFromContact(event.target);
    syncContactRoofFieldVisibility(event.target);
    wireJobTypeAutocomplete(event.target);
    closeJobTypeMenus(event.target);
    renderJobTypeSuggestions(event.target, true);
    return;
  }
  if (event.target.matches('[data-currency-input]')) {
    event.target.value = formatCurrencyDraft(event.target.value);
    return;
  }
  if (event.target.matches('[data-digits-only]')) {
    // Restrict to digits, '+' and '-' only.
    const cleaned = event.target.value.replace(/[^0-9+\-]/g, '');
    if (cleaned !== event.target.value) event.target.value = cleaned;
    return;
  }
  if (event.target.matches('[data-cp-color-input]')) {
    updateClientPortalAnnotateColor(event.target.value || CP_PALETTE[0]);
    return;
  }
  if (event.target.matches('[data-cp-stroke-input]')) {
    updateClientPortalAnnotateStroke(event.target.value);
    return;
  }
  if (event.target.matches('[data-global-search]')) {
    openCommandPalette(event.target.value);
    return;
  }
  if (event.target.matches('[data-member-search]')) {
    memberDirectoryUi().query = event.target.value;
    updateWorkspacePreservingFocus('[data-member-search]');
    return;
  }
  if (event.target.matches('[data-file-search]')) {
    state.fileQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-file-search]');
    return;
  }
  if (event.target.matches('[data-form-search]')) {
    state.formQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-form-search]');
    return;
  }
  if (event.target.matches('[data-client-portal-search]')) {
    state.clientPortalQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-client-portal-search]');
    return;
  }
  if (event.target.matches('[data-crm-search]')) {
    state.crmQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-crm-search]');
    return;
  }
  if (event.target.matches('[data-account-search]')) {
    state.accountQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-account-search]');
    return;
  }
  if (event.target.matches('[data-contact-search]')) {
    state.contactQuery = event.target.value;
    const pos = event.target.selectionStart;
    updateWorkspaceOnly();
    const next = document.querySelector('[data-contact-search]');
    if (next) { next.focus(); try { next.setSelectionRange(pos, pos); } catch { /* noop */ } }
    return;
  }
  if (event.target.matches('[data-contact-rail-search]')) {
    const key = event.target.dataset.contactRailSearch || '';
    if (!Object.prototype.hasOwnProperty.call(CONTACT_FILTER_DEFAULTS, key)) return;
    state.contactRailSearch = { ...(state.contactRailSearch || {}), [key]: event.target.value };
    updateWorkspacePreservingFocus(`[data-contact-rail-search="${key}"]`);
    return;
  }
  if (event.target.matches('[data-knowledge-search]')) {
    state.knowledgeUi.query = event.target.value;
    const pos = event.target.selectionStart;
    updateWorkspaceOnly();
    const next = document.querySelector('[data-knowledge-search]');
    if (next) { next.focus(); try { next.setSelectionRange(pos, pos); } catch { /* noop */ } }
    return;
  }
  if (event.target.matches('[data-deal-search]')) {
    state.dealQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-deal-search]');
    return;
  }
  if (event.target.matches('[data-proposal-search]')) {
    state.proposalQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-proposal-search]');
    return;
  }
  if (event.target.matches('[data-pb-search]')) {
    state.pricebookQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-pb-search]');
    return;
  }
  if (event.target.matches('[data-location-picker-search]')) {
    state.locationPicker = { ...(state.locationPicker || {}), address: event.target.value };
    refreshLocationPickerSuggestions(event.target).catch(() => {});
    return;
  }
  if (event.target.matches('[data-message-search]')) {
    state.messageQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-message-search]');
    return;
  }
  if (event.target.matches('[data-calendar-search]')) {
    state.calendarQuery = event.target.value;
    updateWorkspacePreservingFocus('[data-calendar-search]');
    return;
  }
  if (event.target.matches('[data-message-access-filter]')) {
    filterMessagePeopleList(event.target);
    return;
  }
  if (event.target.matches('input[name="profile_ids"]')) {
    syncMessagePeopleSelection(event.target);
    return;
  }
  if (event.target.matches('.message-composer input[name="attachments"]')) {
    const conversationId = event.target.closest('[data-message-form]')?.dataset.conversationId || '';
    const picked = Array.from(event.target.files || []);
    if (conversationId && picked.length) {
      messageDraftFiles.set(conversationId, messageComposerFiles(conversationId).concat(picked));
      // The input is cleared so picking the same file twice still fires a change event.
      event.target.value = '';
      render();
    }
    return;
  }
  if (event.target.matches('[data-estimate-field]')) {
    updateEstimateBuilderPreview(event.target.closest('[data-estimate-builder-form]'));
    return;
  }
  if (event.target.matches('[data-proposal-field]')) {
    updateProposalBuilderPreview(event.target.closest('[data-proposal-builder-form]'));
    return;
  }
  if (event.target.matches('[data-profile-crop-zoom], [data-profile-crop-x], [data-profile-crop-y]')) {
    updateProfileAvatarCrop(event.target.closest('[data-profile-form]'));
    return;
  }
  if (event.target.matches('[data-platform-backup-filter]')) {
    const key = event.target.dataset.platformBackupFilter;
    state.platformBackupFilters = { company_id: 'all', status: 'all', kind: 'all', query: '', ...(state.platformBackupFilters || {}), [key]: event.target.value };
    updateWorkspaceOnly();
    return;
  }
  if (event.target.matches('[data-role-permission-search]')) {
    state.rolePermissionQuery = event.target.value;
    rerenderPreservingFocus('[data-role-permission-search]');
    return;
  }
  if (event.target.matches('[data-direct-message-search]')) {
    state.directMessageQuery = event.target.value;
    rerenderPreservingFocus('[data-direct-message-search]');
    return;
  }
  if (event.target.matches('[data-company-directory-search]')) {
    const scope = event.target.dataset.companyDirectorySearch;
    // Back to page 1: staying on page 3 of the old result set would show an empty
    // list for a search that actually matched something.
    setCompanyDirectoryFilters(scope, { search: event.target.value, page: 0 });
    updateWorkspacePreservingFocus(`[data-company-directory-search="${scope}"]`);
    return;
  }
  if (event.target.matches('[data-form-field]')) {
    updateFormField(event.target);
    return;
  }
  if (event.target.matches('[data-question-field]') || event.target.matches('[data-question-option]')) {
    updateQuestionField(event.target);
  }
}

/**
 * A wheel over the pipeline board scrolls it sideways.
 *
 * The board is wider than the screen and the columns that matter -- Won, Lost -- sit off the
 * right edge, so reaching them meant finding the scrollbar every time.
 *
 * It hands the gesture back at the ends rather than swallowing it. The app strip was made
 * Shift-only for exactly the opposite reason: it is a thin bar, so trapping the wheel there
 * stopped the page moving at all. The board fills the view, and letting the page scroll once
 * the board has run out of travel keeps both possible.
 */
/**
 * Keep a pipeline board where it was scrolled to across a re-render.
 *
 * Deleting a card calls render(), which replaces the markup -- and a fresh element starts at
 * scrollLeft 0. Somebody working in Won, over at the right-hand end, was thrown back to
 * Prospect on every delete and had to scroll out again. It reads as the page reloading.
 *
 * Remembered in a variable rather than on the node, for the same reason the app strip does
 * it: the node the value would live on is the one being thrown away.
 */
let pipeBoardScrollLeft = 0;

function mountPipeBoardScroll() {
  const board = document.querySelector('.pipe-board');
  if (!board) {
    // Left the board entirely -- a remembered offset would be wrong when it is next opened.
    pipeBoardScrollLeft = 0;
    return;
  }
  if (!board.dataset.scrollBound) {
    board.dataset.scrollBound = '1';
    board.addEventListener('scroll', () => { pipeBoardScrollLeft = board.scrollLeft; }, { passive: true });
  }
  // Clamped, because the board may now be narrower -- deleting the last card in the final
  // column removes it, and restoring past the new end would silently land at the edge.
  if (pipeBoardScrollLeft > 0) board.scrollLeft = Math.min(pipeBoardScrollLeft, board.scrollWidth - board.clientWidth);
}

function onPipeBoardWheel(event) {
  // A trackpad's sideways swipe already arrives as deltaX and the browser handles it.
  if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
  const board = horizontalScrollerUnder(event.target);
  if (!board) return;
  const before = board.scrollLeft;
  board.scrollLeft += event.deltaY;
  // Only claim the gesture if it actually moved -- at either end it did not, and the page
  // should scroll rather than the wheel doing nothing.
  if (board.scrollLeft !== before) event.preventDefault();
}

/**
 * The nearest thing under the pointer that genuinely scrolls sideways.
 *
 * Found by measuring rather than by a list of class names: the quote board, the contacts
 * table and every other wide table want the same behaviour, and a list would need extending
 * for each one -- and would silently miss the next.
 *
 * A vertical scroller wins if it is closer, so the wheel keeps working normally inside a
 * long list that happens to sit within a wide one.
 */
function horizontalScrollerUnder(target) {
  let node = target?.closest?.('*') || null;
  while (node && node !== document.body) {
    const style = getComputedStyle(node);
    const scrollable = (overflow) => overflow === 'auto' || overflow === 'scroll';
    // Yields only to a box that can ACTUALLY scroll down -- it both overflows AND is allowed
    // to. Testing the overflow alone was wrong: a quote column full of cards is taller than
    // its board with overflow-y hidden, so the board was treated as a vertical scroller and
    // the wheel did nothing at all.
    if (style.overflowY && scrollable(style.overflowY) && node.scrollHeight > node.clientHeight + 1) return null;
    if (node.scrollWidth > node.clientWidth + 1 && scrollable(style.overflowX)) return node;
    node = node.parentElement;
  }
  return null;
}

function onDocumentChange(event) {
  // The contact card's panel-contents controls: a checkbox, a number box and a select, so the
  // value is only right on the CHANGE event. Dispatched into the page module for the same
  // reason the click actions are -- these bodies belong with the markup that emits them.
  const panelOpt = event.target.closest?.('[data-action^="cc-panel-"]');
  if (panelOpt && panelOpt.dataset.action !== 'cc-panel-settings'
    && companyContactWrites()?.handleCardChange(panelOpt)) return;
  // Typed rather than picked: change fires when the box loses focus, which is the moment a
  // value stops being half-typed and becomes the answer.
  if (event.target.matches?.('[data-wb-option-input]')) wbCommitOptionChoice(event.target);
  if (event.target.matches('[data-wb-cc-name]')) syncCompanyContactPicker(event.target);
  if (event.target.matches('[data-wb-user-name]')) syncUserPicker(event.target);
  // Picking a client from the suggestions dispatches CHANGE, not input -- see the
  // [data-job-type-option] handler. The same call lives in onDocumentInput for the typing
  // path; without this one, choosing the very name the menu offered filled nothing, which
  // is the one case the feature exists for.
  if (event.target.matches?.('[data-job-type-input]') && event.target.name === 'client_name') {
    fillJobClientFromContact(event.target);
  }
  // Member access directory: filter, sort, and the selection checkboxes.
  if (event.target.matches('[data-member-role]')) {
    memberDirectoryUi().role = event.target.value;
    render();
    return;
  }
  if (event.target.matches('[data-member-sort]')) {
    memberDirectoryUi().sort = event.target.value;
    render();
    return;
  }
  if (event.target.matches('[data-member-pick]')) {
    const ui = memberDirectoryUi();
    const id = event.target.dataset.memberPick;
    if (event.target.checked) ui.selected.add(id); else ui.selected.delete(id);
    render();
    return;
  }
  if (event.target.matches('[data-member-all]')) {
    const ui = memberDirectoryUi();
    const companyId = activeCompanyId();
    const checked = event.target.checked;
    loadMemberDirectory().then((memberDirectory) => {
    // Everyone currently VISIBLE, not everyone in the company: the box sits above a
    // filtered list, and selecting people you cannot see is how bulk actions surprise you.
      const visible = memberDirectory.filterSortMembers({
        users: companyAccessUsers(companyId), query: ui.query, role: ui.role, sort: ui.sort,
      }).filter((user) => user.profile_id);
      if (checked) visible.forEach((user) => ui.selected.add(user.profile_id));
      else visible.forEach((user) => ui.selected.delete(user.profile_id));
      render();
    }).catch((error) => console.error('Member directory failed to load', error));
    return;
  }
  if (event.target.matches('[data-underwriting-contact]')) {
    state.underwritingContactId = event.target.value || '';
    state.underwritingDraft = null;
    state.takeoffDraft = null;
    render();
    return;
  }
  if (takeoffEvent(event, 'change')) return;
  // Auto-format contact form text fields on blur/commit so the entry the user
  // sees matches exactly what gets stored (name casing, email case, zip, etc.).
  const cf = event.target;
  if (cf && (cf.tagName === 'INPUT' || cf.tagName === 'TEXTAREA')
      && !cf.matches('[data-phone-format]')
      && cf.closest('[data-contact-form]')
      && CONTACT_FORM_FORMAT_FIELDS.has(cf.name)) {
    const formatted = String(formatContactField(cf.name, cf.value));
    if (formatted !== cf.value) cf.value = formatted;
    // fall through: no early return, this is a passive normalization
  }
  if (event.target.matches('[data-dashboard-rep]')) {
    state.dashboardRep = event.target.value || 'all';
    render();
    return;
  }
  // The SAME switch the left rail makes, not a second idea of which workspace is open. Two
  // places that each remembered their own answer would sooner or later disagree, and the
  // dashboard would be showing one workspace's numbers under another one's name.
  if (event.target.matches('[data-dashboard-workspace]')) {
    const next = event.target.value || '';
    if (next && next !== activeWorkspaceId()) setActiveWorkspace(next);
    return;
  }
  if (event.target.matches('[data-calls-widget-custom]')) {
    const edge = event.target.dataset.callsWidgetCustom === 'to' ? 'to' : 'from';
    state.callsWidgetCustom = { ...(state.callsWidgetCustom || { from: '', to: '' }), [edge]: event.target.value || '' };
    render();
    return;
  }
  if (event.target.matches('[data-workspace-backup-import]')) {
    if (!requirePermission('settings.manage', activeCompanyId(), 'Your role cannot import workspace backups.', 'Backups')) {
      event.target.value = '';
      return;
    }
    const file = event.target.files?.[0];
    importWorkspaceBackupFile(file).catch((error) => showToast(error.message || 'Import failed.', 'error', 'Backups'));
    event.target.value = '';
    return;
  }
  if (event.target.matches('select[data-platform-backup-filter]')) {
    const key = event.target.dataset.platformBackupFilter;
    state.platformBackupFilters = { company_id: 'all', status: 'all', kind: 'all', query: '', ...(state.platformBackupFilters || {}), [key]: event.target.value };
    render();
    return;
  }
  if (event.target.matches('[data-company-directory-status]')) {
    setCompanyDirectoryFilters(event.target.dataset.companyDirectoryStatus, { status: event.target.value, page: 0 });
    updateWorkspaceOnly();
    return;
  }
  if (event.target.matches('[data-recycle-filter]')) {
    const key = event.target.dataset.recycleFilter;
    state.recycleFilters = { type: 'all', status: 'active', ...(state.recycleFilters || {}), [key]: event.target.value || 'all' };
    render();
    return;
  }
  if (event.target.matches('[data-cp-unit-select]')) {
    cpChangeUnit(event.target.value || 'ft').catch((error) => showToast(error.message || 'Unit update failed.', 'local', 'Client Portal'));
    return;
  }
  if (event.target.matches('[data-action="client-portal-color"], [data-action="client-portal-stamp"]')) {
    handleAction(event, event.target);
    return;
  }
  if (event.target.matches('[data-company-switch]')) {
    const nextCompanyId = event.target.value || defaultCompanyId();
    setActiveCompany(nextCompanyId);
    return;
  }
  if (event.target.matches('[data-estimate-system]')) {
    state.estimateContext = { ...(state.estimateContext || {}), system: event.target.value || 'shingle' };
    render();
    return;
  }
  if (event.target.matches('[data-proposal-template]')) {
    state.proposalContext = { ...(state.proposalContext || {}), template: event.target.value || PROPOSAL_TEMPLATES[0].id };
    render();
    return;
  }
  if (event.target.matches('[data-estimate-field]')) {
    updateEstimateBuilderPreview(event.target.closest('[data-estimate-builder-form]'));
    return;
  }
  if (event.target.matches('[data-proposal-field]')) {
    updateProposalBuilderPreview(event.target.closest('[data-proposal-builder-form]'));
    return;
  }
  if (event.target.matches('[data-stage-filter]')) {
    state.stageFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-crm-stage-filter]')) {
    state.crmStageFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-crm-owner-filter]')) {
    state.crmOwnerFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-contact-filter]')) {
    const key = event.target.dataset.contactFilter;
    if (Object.prototype.hasOwnProperty.call(CONTACT_FILTER_DEFAULTS, key)) {
      state.contactFilters = { ...CONTACT_FILTER_DEFAULTS, ...(state.contactFilters || {}), [key]: event.target.value || 'all' };
      render();
    }
    return;
  }
  if (event.target.matches('[data-proposal-status-filter]')) {
    const next = event.target.value || 'all';
    state.proposalStatusFilter = next === 'all' || PROPOSAL_STATUS_OPTIONS.includes(next) ? next : 'all';
    render();
    return;
  }
  if (event.target.matches('[data-task-status-filter]')) {
    state.taskStatusFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-task-priority-filter]')) {
    state.taskPriorityFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-calendar-type-filter]')) {
    state.calendarTypeFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-task-job-filter]')) {
    const jobId = event.target.value;
    navigate(taskPath(jobId ? { job_id: jobId } : {}, activeCompanyId()));
    return;
  }
  if (event.target.matches('[data-analytics-job-filter]')) {
    const jobId = event.target.value;
    navigate(companyPath('analytics', jobId ? { job_id: jobId } : {}, activeCompanyId()));
    return;
  }
  if (event.target.matches('[data-file-category-filter]')) {
    state.fileCategoryFilter = event.target.value || 'All categories';
    render();
    return;
  }
  if (event.target.matches('[data-file-folder-filter]')) {
    const folder = event.target.value === 'home' ? '' : event.target.value;
    const jobId = state.route?.jobId || '';
    navigate(companyPath('files', { ...(folder ? { folder } : {}), ...(jobId ? { job_id: jobId } : {}) }, activeCompanyId()));
    return;
  }
  if (event.target.matches('[data-file-job-filter]')) {
    const jobId = event.target.value;
    navigate(companyPath('files', { ...(jobId ? { folder: 'jobs', job_id: jobId } : {}) }, activeCompanyId()));
    return;
  }
  if (event.target.matches('[data-form-type-filter]')) {
    state.formTypeFilter = event.target.value || 'all';
    render();
    return;
  }
  if (event.target.matches('[data-profile-avatar-file]')) {
    prepareProfileAvatarCrop(event.target.closest('[data-profile-form]')).catch((error) => {
      showToast(error.message || 'Could not preview that profile picture.', 'local', 'Profile');
    });
    return;
  }
  // Live while the native picker is open. No render(): that would tear the popup down
  // mid-drag, the same reason the appearance colour inputs mutate in place.
  // Typing filters in place. A full render() would recreate the input and lose the
  // caret, which is the same reason the appearance colour pickers mutate rather than
  // re-render -- here the list below is small enough to replace on its own.
  if (event.target.matches('[data-msgdock-people-search]')) {
    state.messageDock = { ...state.messageDock, peopleQuery: event.target.value };
    render();
    return;
  }
  if (event.target.matches('[data-msgdock-guide-search]')) {
    state.messageDock = { ...state.messageDock, guideQuery: event.target.value };
    render();
    return;
  }
  if (event.target.matches('[data-workspace-icon-color]')) {
    const value = normalizeIconColor(event.target.value);
    setWorkspaceIconDraft(activeCompanyId(), { icon_color: value });
    document.querySelectorAll('.workspace-icon-modal .workspace-icon:not(.has-upload)').forEach((el) => el.style.setProperty('--icon-color', value));
    return;
  }
  if (event.target.matches('[data-workspace-icon-upload]')) {
    prepareWorkspaceIconUpload(event.target.files?.[0] || null).catch((error) => {
      showToast(error.message || 'Could not preview that workspace icon.', 'local', 'Settings');
    });
    return;
  }
  if (event.target.matches('[data-message-group-icon-upload]')) {
    prepareMessageGroupIconUpload(event.target.files?.[0] || null).catch((error) => {
      showToast(error.message || 'Could not use that image.', 'local', 'Messages');
    });
    return;
  }
  if (event.target.matches('[data-operational-workspace-modal-icon-upload]')) {
    // A change event, so it never reaches handleAction -- and this re-renders too.
    keepWorkspaceFormText(event.target);
    prepareOperationalWorkspaceModalIconUpload(event.target.files?.[0] || null).catch((error) => {
      showToast(error.message || 'Could not use that image.', 'local', 'Workspaces');
    });
    return;
  }
  if (event.target.matches('[data-appearance-bg-upload]')) {
    prepareAppearanceBgUpload(event.target.files?.[0] || null).catch((error) => {
      showToast(error.message || 'Could not use that background image.', 'local', 'Appearance');
    });
    return;
  }
  if (event.target.matches('[data-form-field]')) {
    updateFormField(event.target);
    return;
  }
  if (event.target.matches('[data-question-field]') || event.target.matches('[data-question-option]')) {
    updateQuestionField(event.target);
  }
}

function validateJobForm(form) {
  const formData = Object.fromEntries(new FormData(form).entries());
  const nameInput = form.querySelector('[name="name"]');
  const rawName = String(formData.name || '').trim();
  if (!rawName) {
    nameInput?.setCustomValidity('Workspace name is required.');
    nameInput?.reportValidity();
    showToast('Workspace name is required.', 'local', 'Jobs');
    return { ok: false };
  }
  nameInput?.setCustomValidity('');
  formData.name = rawName;
  formData.estimate_total = parseCurrencyAmount(formData.estimate_total);
  formData.invoice_total = parseCurrencyAmount(formData.invoice_total);
  return { ok: true, data: formData };
}

/**
 * A job for somebody who is not in the CRM yet creates them.
 *
 * Typing a client the contact list does not have is how a real job starts -- a call comes
 * in, the job is opened, and the contact record is the thing nobody goes back to make. So
 * saving the job makes it, using the number typed into Contact beside it.
 *
 * Never on an edit that already resolved to a contact, and never on a name that matches one
 * -- that would mint a duplicate every time an existing job was saved. Failure here is
 * swallowed on purpose: the job is what was asked for, and losing it because a convenience
 * record could not be written would be the worse outcome.
 */
async function ensureJobClientContact(payload, form) {
  const name = String(payload.client_name || '').trim();
  if (!name || payload.contact_id) return payload;
  const existing = contactByName(payload.company_id, name);
  if (existing) return { ...payload, contact_id: existing.id };
  try {
    const contact = normalizeContact({
      id: crypto.randomUUID(),
      company_id: payload.company_id,
      workspace_id: payload.workspace_id,
      name,
      // The Contact box beside Client is where the number was typed.
      phone: String(form?.querySelector('[name="contact_name"]')?.value || '').trim(),
      stage: 'Prospects',
    });
    await persistContact(contact);
    showToast(`${name} added to Contacts.`, isLiveSupabaseSession() ? 'live' : 'local', 'Contacts');
    return { ...payload, contact_id: contact.id };
  } catch (error) {
    console.warn('Client contact could not be created', error);
    return payload;
  }
}

async function saveJob(form) {
  const validation = validateJobForm(form);
  if (!validation.ok) return;
  let payload = normalizeJob(validation.data);
  payload.id = payload.id || crypto.randomUUID();
  payload.company_id = payload.company_id || activeCompanyId();
  payload.workspace_id = workspaceIdForRecord(payload.company_id, payload.workspace_id);
  if (!requirePermission('jobs.manage', payload.company_id, 'Your role can view jobs but cannot create or edit them.', 'Jobs')) return;
  payload.estimate_total = Number(payload.estimate_total || 0);
  payload.invoice_total = Number(payload.invoice_total || 0);
  payload.updated_at = new Date().toISOString();
  // After the permission check -- somebody who cannot save the job must not leave a contact
  // behind as a side effect of trying.
  payload = await ensureJobClientContact(payload, form);

  const existing = state.jobs.some((job) => job.id === payload.id);
  const client = createSupabaseClient();

  if (client) {
    // Through jobSupabaseRow, as persistJob already does. It trims the payload to the
    // table's columns and -- the part that matters here -- turns an empty account_id,
    // contact_id, deal_id or site_id into null. A job created without a client was sending
    // account_id: '', which is not "no account" to Postgres but a link to an account whose
    // id is the empty string, so every such save died on jobs_account_id_fkey.
    const row = jobSupabaseRow(payload);
    const result = await safeSupabaseQuery(existing
      ? client.from('jobs').update(row).eq('id', payload.id).select().single()
      : client.from('jobs').insert(row).select().single());
    if (!result.error && result.data) {
      upsertJob(normalizeJob(result.data));
      state.sync = { label: 'Quest Supabase live', mode: 'live' };
      clearProtectedFormDraft(form);
      state.modal = '';
      navigate(companyPath('jobs', { tab: 'profile', job_id: result.data.id }, payload.company_id), { replace: true });
      return true;
    }
    if (isLiveSupabaseSession()) {
      notifySyncFailure(result.error || new Error('Job save returned no record.'), 'Job save');
      return false;
    }
    state.sync = { label: 'Saved locally', mode: 'local' };
  }

  upsertJob(payload);
  clearProtectedFormDraft(form);
  state.modal = '';
  navigate(companyPath('jobs', { tab: 'profile', job_id: payload.id }, payload.company_id), { replace: true });
  return true;
}

// ---- the Button field -------------------------------------------------------------------
// A field that carries its record into another app. Both halves -- deciding whether it is live
// against what the form holds, and doing the push -- are fetched on the first record form that
// has one, because most apps have none.
let buttonPushModule = null;
let buttonPushPending = null;

function loadButtonPush() {
  if (buttonPushModule) return Promise.resolve(buttonPushModule);
  if (!buttonPushPending) {
    buttonPushPending = import('./workspace/button-push.js').then((mod) => {
      buttonPushModule = mod.createButtonPush({
        h, can, wbDoc, wbSave, wbUid, showToast, render, canonicalCompanyId, activeSession,
        state, wbFind, wbReadFieldInput, activeCompanyId, wbLogActivity, wbItemTitle, wbRunAutomations,
        // A move takes the record out of this app. Somebody reading its page goes with it.
        navigate, companyPath,
        // A thunk, not the resolved seat: the contacts page is loaded on its own schedule, and
        // this keeps every storage-shape difference a contact has on that side of the boundary.
        contactSeat: (seat) => companyContactsPageModule?.contactButtonSeat(seat) || null,
        // The directory as a destination. Its field list is read live, so a field added in
        // Settings is available to a button that was configured before it existed.
        contactsApp: (companyId) => wbContactsTargetApp(companyId),
        // Filing the arrival. Awaited through the loader rather than read off the module: the
        // contacts page is fetched when somebody opens it, and pressing a button that sends
        // there is very often the first thing in a session that needs it.
        contactIntake: (companyId, payload) => loadCompanyContactsPage()
          .then((mod) => mod.receiveContactFromApp(companyId, payload))
          .catch(() => ({ ok: false, error: 'Company Contacts could not load.' })),
      });
      return buttonPushModule;
    }).catch((error) => { buttonPushPending = null; throw error; });
  }
  return buttonPushPending;
}

// Enable or disable the buttons on screen against what the form currently holds.
function wbSyncButtons(root) {
  if (!root?.querySelector?.('[data-wb-press]')) return;
  if (buttonPushModule) { buttonPushModule.syncButtons(root); return; }
  loadButtonPush()
    .then((mod) => mod.syncButtons(root))
    .catch((error) => console.error('button field failed to load', error));
}

function wbPressButton(fieldId, seat) {
  loadButtonPush()
    .then((mod) => mod.press(fieldId, seat))
    .catch((error) => showToast(error.message || 'That record could not be sent.', 'local', 'Workspaces'));
}

