/**
 * Attach a file to a job -- a receipt, a voice note, anything.
 *
 * Same bucket and same table as job photos, so whatever is attached here shows up in the
 * job's files and the drive without a second code path.
 */
async function uploadJobFile(job, file, note, category = 'Receipt', policy = 'image') {
  const client = createSupabaseClient();
  // Same validator the other uploads use: type and size are checked before anything is sent.
  if (!(await guardUpload(file, policy, 'Jobs'))) throw new Error('That file was not accepted');
  const path = `${canonicalCompanyId(job.company_id)}/job-files/${crypto.randomUUID()}-${slugify(file.name || 'attachment')}`;
  if (client && isLiveSupabaseSession()) {
    const up = await client.storage.from('quest-job-files').upload(path, file, { cacheControl: '3600', contentType: contentTypeFor(file) });
    if (up.error) throw up.error;
  }
  const row = normalizeFile({
    company_id: job.company_id,
    workspace_id: activeWorkspaceId(),
    job_id: job.id,
    bucket_id: 'quest-job-files',
    object_path: path,
    file_name: file.name || 'receipt.jpg',
    mime_type: contentTypeFor(file),
    size_bytes: file.size || 0,
    category,
    notes: note,
  });
  if (client && isLiveSupabaseSession()) {
    const result = await client.from('job_files').insert(filePayload(row)).select().single();
    if (result.error) throw result.error;
    state.files = [normalizeFile(result.data), ...state.files];
    return;
  }
  state.files = [row, ...state.files];
}

/** Closing a bucket is what turns a projected net into a real one, so it is one click. */
async function setCostBucketFinal(bucketId) {
  const bucket = state.jobCostBuckets.find((b) => b.id === bucketId);
  if (!bucket) return;
  if (!requirePermission('jobs.manage', bucket.company_id, 'Your role cannot change job costs.', 'Jobs')) return;
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('job_cost_buckets').update({ status: 'final', updated_at: new Date().toISOString() }).eq('id', bucketId);
    if (result.error) { showToast(result.error.message || 'Could not close that bucket.', 'error', 'Jobs'); return; }
  }
  state.jobCostBuckets = state.jobCostBuckets.map((b) => (b.id === bucketId ? { ...b, status: 'final' } : b));
  showToast(`${bucket.name} closed — the net just firmed up.`, isLiveSupabaseSession() ? 'live' : 'local', 'Jobs');
  render();
}

async function requestJobDraw(drawId) {
  const draw = state.jobDraws.find((d) => d.id === drawId);
  if (!draw) return;
  if (!requirePermission('jobs.manage', draw.company_id, 'Your role cannot invoice draws.', 'Jobs')) return;
  const now = new Date().toISOString();
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('job_draws').update({ status: 'paid', invoiced_at: now, updated_at: now }).eq('id', drawId);
    if (result.error) { showToast(result.error.message || 'Could not request that draw.', 'error', 'Jobs'); return; }
  }
  state.jobDraws = state.jobDraws.map((d) => (d.id === drawId ? { ...d, status: 'paid', invoiced_at: now } : d));
  showToast(`Invoice requested for ${draw.label}.`, isLiveSupabaseSession() ? 'live' : 'local', 'Jobs');
  render();
}

async function advanceChangeOrder(coId, step) {
  const co = state.jobChangeOrders.find((c) => c.id === coId);
  if (!co || !CO_STEPS.includes(step)) return;
  if (!requirePermission('jobs.manage', co.company_id, 'Your role cannot change these.', 'Jobs')) return;
  const patch = { step, updated_at: new Date().toISOString() };
  if (step === 'accepted') patch.accepted_at = patch.updated_at;
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('job_change_orders').update(patch).eq('id', coId);
    if (result.error) { showToast(result.error.message || 'Could not update that change order.', 'error', 'Jobs'); return; }
  }
  state.jobChangeOrders = state.jobChangeOrders.map((c) => (c.id === coId ? { ...c, ...patch } : c));
  showToast(step === 'acknowledged'
    ? 'Crew acknowledged — they are building to it.'
    : `Marked ${step}.`, isLiveSupabaseSession() ? 'live' : 'local', 'Jobs');
  render();
}

async function deleteJob(id) {
  if (!id) return;
  const companyId = activeCompanyId();
  if (!requirePermission('jobs.manage', companyId, 'Your role cannot delete jobs.', 'Jobs')) return;
  await recycleDeleteRecord({ type: 'job', id });
}

async function runTaskSaveHooks(previous, savedTask) {
  if (!savedTask) return;
  if (previous && previous.status !== 'done' && savedTask.status === 'done') {
    await spawnNextRecurrence(savedTask);
  }
  await runCompanyAutomations('task', previous, savedTask, savedTask.company_id);
}

async function saveTask(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('tasks.manage', companyId, 'Your role can view tasks but cannot create or edit them.', 'Tasks')) return;
  const formData = Object.fromEntries(new FormData(form).entries());
  const creatorId = activeTaskCreatorId(companyId);
  if (!creatorId) {
    showToast('Your signed-in profile is missing a task creator ID.', 'error', 'Tasks');
    return false;
  }
  const taskId = String(formData.id || '').trim();
  const previous = taskId ? taskById(taskId) : null;
  if (taskId && !previous) {
    showToast('This task is not available in the active workspace.', 'error', 'Tasks');
    return false;
  }
  const linkedJob = formData.project_id ? companyJobs(companyId).find((item) => item.id === formData.project_id) : null;
  const linkedContact = formData.contact_id ? companyContacts(companyId).find((item) => item.id === formData.contact_id) : null;
  const linkedDeal = formData.deal_id ? companyDeals(companyId).find((item) => item.id === formData.deal_id) : null;
  if ((formData.project_id && !linkedJob) || (formData.contact_id && !linkedContact) || (formData.deal_id && !linkedDeal)) {
    showToast('One of the linked records is outside the active workspace.', 'error', 'Tasks');
    return false;
  }
  const payload = normalizeTask({
    ...(previous || {}),
    ...formData,
    id: taskId || `task-${crypto.randomUUID()}`,
    company_id: companyId,
    workspace_id: workspaceIdForRecord(companyId, previous?.workspace_id),
    // project_id has carried the job id since before tasks had a real job column -- it is
    // free text, so nothing stopped it. Both are written now: the FK is the one to trust, and
    // the old field keeps every existing reader working.
    project_id: linkedJob?.id || linkedDeal?.job_id || '',
    job_id: linkedJob?.id || linkedDeal?.job_id || previous?.job_id || '',
    contact_id: linkedContact?.id || linkedJob?.contact_id || linkedDeal?.primary_contact_id || '',
    deal_id: linkedDeal?.id || linkedJob?.deal_id || '',
    creator_id: previous?.creator_id || creatorId,
    urgency: formData.priority || 'medium',
    watchers: previous?.watchers || [],
    subtasks: previous?.subtasks || [],
    activity: previous?.activity || [],
    updated_at: new Date().toISOString(),
  });

  const existing = !!previous;
  const client = createSupabaseClient();
  const returnContactId = String(formData.return_contact_id || '').trim();
  if (client) {
    const savePayload = taskPayload(payload);
    const result = await safeSupabaseQuery(existing
      ? client.from('tasks').update(savePayload).eq('id', payload.id).eq('workspace_id', payload.workspace_id).select().single()
      : client.from('tasks').insert(savePayload).select().single());
    if (!result.error && result.data) {
      const savedTask = normalizeTask(result.data);
      upsertTask(savedTask);
      notifyTaskChange(savedTask, previous);
      await runTaskSaveHooks(previous, savedTask);
      state.sync = { label: 'Quest Supabase live', mode: 'live' };
      state.modal = '';
      if (returnContactId) {
        navigate(companyPath('contacts', { contact_id: returnContactId }, companyId), { replace: true });
        return true;
      }
      navigate(taskPath({ ...(payload.project_id ? { job_id: payload.project_id } : {}), task_id: payload.id }, companyId), { replace: true });
      return true;
    }
    if (isLiveSupabaseSession()) {
      notifySyncFailure(result.error || new Error('Task save returned no record.'), 'Task save');
      return false;
    }
    state.sync = { label: 'Task saved locally', mode: 'local' };
  }

  upsertTask(payload);
  notifyTaskChange(payload, previous);
  await runTaskSaveHooks(previous, payload);
  state.modal = '';
  if (returnContactId) {
    navigate(companyPath('contacts', { contact_id: returnContactId }, companyId), { replace: true });
    return true;
  }
  navigate(taskPath({ ...(payload.project_id ? { job_id: payload.project_id } : {}), task_id: payload.id }, companyId), { replace: true });
  return true;
}

async function deleteTask(id, options = {}) {
  if (!id) return;
  const companyId = activeCompanyId();
  if (!requirePermission('tasks.manage', companyId, 'Your role cannot delete tasks.', 'Tasks')) return;
  await recycleDeleteRecord({ type: 'task', id, options });
}

// The measurements live in the takeoff card's draft while it is on screen. Saving the decision
// saves them with it, so reopening the contact shows the report it was priced from.
function takeoffStateForSave() {
  const draft = state.takeoffDraft;
  if (!draft || draft.scope !== 'underwriter' || draft.companyId !== activeCompanyId()) return null;
  return { calculator_id: draft.calculatorId || '', measurements: draft.measurements, overrides: draft.overrides || {} };
}



async function saveUnderwritingCase(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('underwriter.manage', companyId, 'Your role can view underwriting but cannot save cases.', 'Underwriter')) return false;
  const input = renderUnderwriterPageModule.underwritingInputFromForm(form);
  const contact = companyContacts(companyId).find((item) => item.id === input.contactId);
  if (!contact) {
    showToast('Choose a contact before saving.', 'error', 'Underwriter');
    return false;
  }
  const existing = underwritingCaseForContact(contact.id, companyId);
  const item = normalizeUnderwritingCase({
    ...(existing || {}),
    company_id: companyId,
    workspace_id: workspaceIdForRecord(contact.company_id, contact.workspace_id),
    contact_id: contact.id,
    contract_price: input.contractPrice,
    material_cost: input.materialCost,
    labor_cost: input.laborCost,
    permit_cost: input.permitCost,
    disposal_cost: input.disposalCost,
    other_cost: input.otherCost,
    overhead_percent: input.overheadPercent,
    commission_percent: input.commissionPercent,
    contingency_percent: input.contingencyPercent,
    target_margin_percent: input.targetMarginPercent,
    notes: input.notes,
    takeoff: takeoffStateForSave() || existing?.takeoff || {},
    created_by: existing?.created_by || (isUuid(activeSession().profile.id) ? activeSession().profile.id : null),
    updated_at: new Date().toISOString(),
  });
  const client = createSupabaseClient();
  let saved = item;
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('underwriting_cases').upsert(underwritingCasePayload(item), { onConflict: 'company_id,contact_id' }).select().single();
    if (result.error || !result.data) {
      notifySyncFailure(result.error || new Error('Underwriting save returned no record.'), 'Underwriter');
      return false;
    }
    saved = normalizeUnderwritingCase(result.data);
  }
  state.underwritingCases = [saved, ...state.underwritingCases.filter((entry) => !(entry.company_id === companyId && entry.contact_id === contact.id))];
  state.underwritingDraft = { companyId, ...input, hydrated: true };
  clearProtectedFormDraft(form);
  showToast(`Underwriting saved for ${contact.name}.`, isLiveSupabaseSession() ? 'live' : 'local', 'Underwriter');
  render();
  return true;
}

async function saveJobPhotos(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('files.manage', companyId, 'Your role can view job photos but cannot upload them.', 'Job photos')) return false;
  const fields = Object.fromEntries(new FormData(form).entries());
  const job = jobById(String(fields.job_id || ''));
  if (!job || job.company_id !== companyId) {
    showToast('This job is unavailable in the active workspace.', 'error', 'Job photos');
    return false;
  }
  const files = [
    ...Array.from(form.elements.camera?.files || []),
    ...Array.from(form.elements.photos?.files || []),
  ];
  if (!files.length) {
    showToast('Take a photo or choose images to upload.', 'error', 'Job photos');
    return false;
  }
  const submit = form.querySelector('[data-job-photo-submit]');
  const progress = form.querySelector('[data-job-photo-progress]');
  const bar = form.querySelector('[data-job-photo-bar]');
  if (submit) { submit.disabled = true; submit.innerHTML = '<span class="btn-spinner"></span>Uploading...'; }
  if (progress) progress.hidden = false;
  const client = createSupabaseClient();
  const live = isLiveSupabaseSession();
  let savedCount = 0;
  let failedCount = 0;
  let lastError = null;

  for (let index = 0; index < files.length; index += 1) {
    const item = files[index];
    if (bar) bar.style.width = `${Math.max(6, Math.round(((index + 1) / files.length) * 100))}%`;
    if (!(await guardUpload(item, 'image', 'Job photos'))) { failedCount += 1; continue; }
    const fileId = crypto.randomUUID();
    const objectPath = `${companyId}/jobs/${job.id}/photos/${fileId}-${slugify(item.name)}`;
    let uploaded = false;
    if (live && client) {
      const storage = await client.storage.from('quest-job-files').upload(objectPath, item, {
        cacheControl: '3600',
        upsert: false,
        contentType: contentTypeFor(item),
      });
      if (storage.error) {
        failedCount += 1;
        lastError = storage.error;
        continue;
      }
      uploaded = true;
    }
    const payload = normalizeFile({
      id: fileId,
      company_id: companyId,
      job_id: job.id,
      folder: 'photos',
      file_name: item.name,
      mime_type: item.type || contentTypeFor(item),
      size_bytes: item.size,
      category: JOB_PHOTO_CATEGORIES.includes(fields.category) ? fields.category : 'Inspection',
      notes: String(fields.notes || '').trim(),
      uploaded_by_label: activeSession().profile.full_name || activeSession().profile.email || 'Questbase',
      bucket_id: 'quest-job-files',
      object_path: uploaded ? objectPath : '',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    });
    let saved = payload;
    if (live && client) {
      const result = await client.from('job_files').insert(filePayload(payload)).select().single();
      if (result.error || !result.data) {
        failedCount += 1;
        lastError = result.error || new Error('Photo record insert returned no record.');
        await client.storage.from('quest-job-files').remove([objectPath]);
        continue;
      }
      saved = normalizeFile(result.data);
    }
    upsertFile(saved);
    savedCount += 1;
  }

  if (!savedCount) {
    if (submit) { submit.disabled = false; submit.innerHTML = '<i class="ti ti-cloud-upload"></i>Upload photos'; }
    if (progress) progress.hidden = true;
    showToast(lastError?.message || 'No photos were uploaded. Check the images and try again.', 'error', 'Job photos');
    return false;
  }
  notifyLocalEvent(
    'file.added',
    savedCount === 1 ? 'Job photo added' : 'Job photos added',
    `${actorName()} added ${savedCount} photo${savedCount === 1 ? '' : 's'} to ${job.name}.`,
    companyPath('jobs', { tab: 'profile', job_id: job.id }, companyId),
    'file',
    job.id,
    companyId,
  );
  showToast(
    failedCount ? `Uploaded ${savedCount} of ${files.length} photos. ${failedCount} failed.` : `Added ${savedCount} photo${savedCount === 1 ? '' : 's'} to ${job.name}.`,
    failedCount ? 'error' : (live ? 'live' : 'local'),
    'Job photos',
  );
  state.jobPhotoCategory = 'All';
  render();
  return true;
}

async function saveFileRecord(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('files.manage', companyId, 'Your role can view files but cannot upload.', 'Files')) return;
  const formData = new FormData(form);
  const fields = Object.fromEntries(formData.entries());
  const selectedFiles = Array.from(form.elements.files?.files || []);
  const metadataName = String(fields.file_name || '').trim();
  const uploadList = selectedFiles.length ? selectedFiles : (metadataName ? [null] : []);
  if (!uploadList.length) {
    state.sync = { label: 'Choose a file or enter a file name', mode: 'local' };
    render();
    return;
  }
  // Uploading UI: disable the submit button (prevents duplicate uploads) and
  // animate a progress bar as each file is processed.
  const submitBtn = form.querySelector('[data-upload-submit]');
  const progressWrap = form.querySelector('[data-upload-progress]');
  const progressBar = form.querySelector('[data-upload-bar]');
  if (submitBtn) { submitBtn.disabled = true; submitBtn.innerHTML = '<span class="btn-spinner"></span>Uploading…'; }
  if (progressWrap) progressWrap.hidden = false;
  const total = uploadList.length;
  let done = 0;
  const setProgress = () => { if (progressBar) progressBar.style.width = `${Math.max(6, Math.round((done / total) * 100))}%`; };
  setProgress();
  const client = createSupabaseClient();
  const live = isLiveSupabaseSession();
  let liveSaved = 0;
  let failed = 0;
  let lastError = null;
  for (const item of uploadList) {
    done += 1;
    setProgress();
    const fileId = crypto.randomUUID();
    const fileName = item?.name || metadataName;
    if (item && !(await guardUpload(item, 'document', 'Files'))) { failed += 1; continue; }
    const folder = String(fields.folder || 'shared');
    const objectPath = `${companyId}/${fields.job_id ? `jobs/${fields.job_id}` : folder}/${fileId}-${slugify(fileName)}`;
    let uploaded = false;
    if (client && item) {
      const storageResult = await client.storage
        .from('quest-job-files')
        .upload(objectPath, item, { cacheControl: '3600', upsert: false, contentType: contentTypeFor(item) });
      uploaded = !storageResult.error;
      if (storageResult.error) lastError = storageResult.error;
    }
    // On a live session, an actual file whose bytes never reached storage must
    // NOT be recorded — that produces a phantom (name/size shown, no bytes).
    if (live && item && !uploaded) { failed += 1; continue; }
    const payload = normalizeFile({
      id: fileId,
      company_id: companyId,
      job_id: fields.job_id || '',
      folder,
      file_name: fileName,
      mime_type: item?.type || 'application/octet-stream',
      size_bytes: item?.size || Number(fields.size_bytes || 0),
      category: fields.category || folderLabel(folder),
      notes: fields.notes || '',
      uploaded_by_label: fields.uploaded_by_label || activeSession().profile.full_name,
      bucket_id: 'quest-job-files',
      object_path: uploaded || !item ? objectPath : '',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    });

    if (client) {
      const result = await client.from('job_files').insert(filePayload(payload)).select().single();
      if (!result.error && result.data) {
        upsertFile(normalizeFile(result.data));
        liveSaved += 1;
        continue;
      }
      if (uploaded) await client.storage.from('quest-job-files').remove([objectPath]);
      // Live session but the DB record failed to persist — don't keep a phantom
      // local-only row; report it as failed so the user knows to retry.
      if (live) { failed += 1; lastError = result.error || new Error('File record insert returned no record.'); continue; }
    }
    upsertFile(payload);
  }

  const uploadCount = uploadList.length;
  state.sync = failed === 0 && liveSaved === uploadCount
    ? { label: 'Quest Supabase live', mode: 'live' }
    : { label: failed ? 'Some uploads failed' : (liveSaved ? 'Some files saved locally' : 'File record saved locally'), mode: failed ? 'local' : (liveSaved ? 'loading' : 'local') };
  if (failed > 0 && liveSaved === 0) {
    showToast(lastError?.message || `Upload failed — ${failed} file${failed === 1 ? '' : 's'} were not saved. Please try again.`, 'error', 'Upload failed');
  } else if (failed > 0) {
    showToast(`Uploaded ${liveSaved} of ${uploadCount} — ${failed} failed and ${failed === 1 ? 'was' : 'were'} not saved.`, 'error', 'Files');
  } else if (liveSaved === uploadCount) {
    showToast(`Uploaded ${uploadCount} file${uploadCount === 1 ? '' : 's'} to the drive.`, isLiveSupabaseSession() ? 'live' : 'local', 'Files');
  } else if (liveSaved > 0) {
    showToast(`Uploaded ${liveSaved} of ${uploadCount} — the rest were saved locally.`, 'local', 'Files');
  } else {
    showToast(`Saved ${uploadCount} file record${uploadCount === 1 ? '' : 's'} locally (storage upload was blocked).`, 'local', 'Files');
  }
  // If nothing persisted on a live session, keep the upload modal open so the
  // user can retry without re-selecting files.
  if (live && liveSaved === 0 && failed > 0) {
    if (submitBtn) { submitBtn.disabled = false; submitBtn.innerHTML = 'Upload'; }
    if (progressWrap) progressWrap.hidden = true;
    return;
  }
  notifyLocalEvent(
    'file.added',
    uploadList.length > 1 ? 'Files added' : 'File added',
    `${actorName()} added ${uploadList.length} file${uploadList.length === 1 ? '' : 's'} to ${folderLabel(fields.folder || 'shared')}.`,
    companyPath('files', { folder: fields.folder || 'shared', ...(fields.job_id ? { job_id: fields.job_id } : {}) }, companyId),
    'file',
    fields.job_id || '',
    companyId,
  );
  state.modal = '';
  navigate(companyPath('files', { folder: fields.folder || 'shared', ...(fields.job_id ? { job_id: fields.job_id } : {}) }, companyId), { replace: true });
}

async function saveClientPortal(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('client_portals.manage', companyId, 'Your role cannot manage client portals.', 'Client Portal')) return;
  const fields = Object.fromEntries(new FormData(form).entries());
  const existing = fields.id ? clientPortalById(String(fields.id)) : null;
  const rawToken = existing?.raw_token || (existing ? '' : randomPortalToken());
  const tokenHash = existing?.token_hash || await digestHex(rawToken);
  const password = String(fields.password || '');
  const passwordSalt = password ? randomPortalToken(18) : existing?.password_salt || '';
  const passwordHash = password ? await pbkdf2Hex(password, passwordSalt) : existing?.password_hash || '';
  let portal = normalizeClientPortal({
    ...(existing || {}),
    id: existing?.id || crypto.randomUUID(),
    company_id: companyId,
    job_id: fields.job_id || '',
    title: String(fields.title || '').trim() || 'Client plan portal',
    client_name: fields.client_name || '',
    client_email: fields.client_email || '',
    token_hash: tokenHash,
    raw_token: rawToken,
    password_hash: passwordHash,
    password_salt: passwordSalt,
    status: existing?.status || 'active',
    created_by: existing?.created_by || activeSession().profile.id,
    created_at: existing?.created_at || new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const payload = clientPortalPayload(portal);
    const result = existing
      ? await client.from('client_portals').update(payload).eq('id', existing.id).select().single()
      : await client.from('client_portals').insert(payload).select().single();
    if (result.error) {
      showToast(result.error.message || 'Portal save failed.', 'local', 'Client Portal');
      return;
    }
    portal = normalizeClientPortal({ ...result.data, raw_token: rawToken });
  }
  upsertClientPortal(portal);
  state.modal = '';
  showToast(existing ? 'Portal saved.' : 'Portal created. Copy the link from the detail panel.', state.session?.auth === 'supabase' ? 'live' : 'local', 'Client Portal');
  navigate(companyPath('client-portals', { portal_id: portal.id }, companyId), { replace: true });
}

async function saveClientPortalDocuments(form) {
  const companyId = activeCompanyId();
  if (!requirePermission('client_portals.manage', companyId, 'Your role cannot upload portal documents.', 'Client Portal')) return;
  const fields = Object.fromEntries(new FormData(form).entries());
  const portal = clientPortalById(String(fields.portal_id || ''));
  if (!portal) {
    showToast('Choose a portal first.', 'local', 'Client Portal');
    return;
  }
  const files = Array.from(form.elements.files?.files || []);
  if (!files.length) {
    showToast('Choose at least one PDF, PNG, or JPG.', 'local', 'Client Portal');
    return;
  }
  const submitBtn = form.querySelector('[data-upload-submit]');
  const progressWrap = form.querySelector('[data-upload-progress]');
  const progressBar = form.querySelector('[data-upload-bar]');
  if (submitBtn) { submitBtn.disabled = true; submitBtn.innerHTML = '<span class="btn-spinner"></span>Uploading…'; }
  if (progressWrap) progressWrap.hidden = false;
  const total = files.length;
  let done = 0;
  const setProgress = () => { if (progressBar) progressBar.style.width = `${Math.max(6, Math.round((done / total) * 100))}%`; };
  setProgress();
  const client = createSupabaseClient();
  let savedCount = 0;
  for (const file of files) {
    done += 1;
    setProgress();
    if (!(await guardUpload(file, 'document', 'Client Portal'))) continue;
    const id = crypto.randomUUID();
    const objectPath = `${companyId}/portals/${portal.id}/${id}-${slugify(file.name || 'plan-set')}`;
    let uploaded = false;
    if (isLiveSupabaseSession() && client) {
      const upload = await client.storage
        .from('quest-client-portal-documents')
        .upload(objectPath, file, { cacheControl: '3600', upsert: false, contentType: contentTypeFor(file) });
      if (upload.error) {
        showToast(upload.error.message || 'Plan upload failed.', 'local', 'Client Portal');
        continue;
      }
      uploaded = true;
    }
    let doc = normalizeClientPortalDocument({
      id,
      company_id: companyId,
      portal_id: portal.id,
      bucket_id: 'quest-client-portal-documents',
      object_path: uploaded ? objectPath : '',
      file_name: file.name || 'Plan set',
      mime_type: file.type || 'application/octet-stream',
      size_bytes: file.size || 0,
      uploaded_by: activeSession().profile.id,
    });
    if (isLiveSupabaseSession() && client) {
      const result = await client.from('client_portal_documents').insert(clientPortalDocumentPayload(doc)).select().single();
      if (result.error) {
        if (uploaded) await client.storage.from('quest-client-portal-documents').remove([objectPath]);
        showToast(result.error.message || 'Document record failed.', 'local', 'Client Portal');
        continue;
      }
      doc = normalizeClientPortalDocument(result.data);
    }
    upsertClientPortalDocument(doc);
    savedCount += 1;
  }
  state.modal = '';
  persistAll();
  if (savedCount) {
    showToast(`${savedCount} document${savedCount === 1 ? '' : 's'} uploaded.`, state.session?.auth === 'supabase' ? 'live' : 'local', 'Client Portal');
  } else {
    showToast('Upload failed — no documents were saved.', 'local', 'Client Portal');
  }
  navigate(companyPath('client-portals', { portal_id: portal.id }, companyId), { replace: true });
}

function copyClientPortalLink(portalId) {
  const portal = clientPortalById(portalId);
  if (!portal) return;
  const token = String(portal.raw_token || '');
  if (!token) {
    showToast('Use Regenerate to issue a new copyable portal link.', 'local', 'Client Portal');
    return;
  }
  const link = `${window.location.origin}${appHref(`/portal/${encodeURIComponent(token)}`)}`;
  navigator.clipboard?.writeText(link).then(
    () => showToast('Portal link copied.', 'live', 'Client Portal'),
    () => showToast(link, 'local', 'Copy this portal link'),
  );
}

async function regenerateClientPortalLink(portalId) {
  const portal = clientPortalById(portalId);
  if (!portal || !requirePermission('client_portals.manage', portal.company_id, 'Your role cannot regenerate portal links.', 'Client Portal')) return;
  if (!window.confirm(`Regenerate the public link for ${portal.title}? The old link will stop opening.`)) return;
  const rawToken = randomPortalToken();
  const tokenHash = await digestHex(rawToken);
  const next = normalizeClientPortal({ ...portal, token_hash: tokenHash, status: 'active', revoked_at: null, updated_at: new Date().toISOString(), raw_token: rawToken });
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client
      .from('client_portals')
      .update({ token_hash: tokenHash, status: 'active', revoked_at: null, updated_at: next.updated_at })
      .eq('id', portal.id)
      .select()
      .single();
    if (result.error) throw new Error(result.error.message || 'Portal link regenerate failed.');
  }
  upsertClientPortal(next);
  persistAll();
  copyClientPortalLink(portal.id);
  render();
}

async function revokeClientPortal(portalId) {
  const portal = clientPortalById(portalId);
  if (!portal || !requirePermission('client_portals.manage', portal.company_id, 'Your role cannot revoke portals.', 'Client Portal')) return;
  if (!window.confirm(`Revoke ${portal.title}? Existing guests will lose access.`)) return;
  const next = normalizeClientPortal({ ...portal, status: 'revoked', revoked_at: new Date().toISOString(), updated_at: new Date().toISOString() });
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('client_portals').update({ status: 'revoked', revoked_at: next.revoked_at, updated_at: next.updated_at }).eq('id', portal.id).select().single();
    if (result.error) {
      showToast(result.error.message || 'Portal revoke failed.', 'local', 'Client Portal');
      return;
    }
  }
  upsertClientPortal(next);
  showToast('Portal revoked.', state.session?.auth === 'supabase' ? 'live' : 'local', 'Client Portal');
  render();
}

async function restoreClientPortal(portalId) {
  const portal = clientPortalById(portalId);
  if (!portal || !requirePermission('client_portals.manage', portal.company_id, 'Your role cannot manage portals.', 'Client Portal')) return;
  const next = normalizeClientPortal({ ...portal, status: 'active', revoked_at: null, updated_at: new Date().toISOString() });
  const client = createSupabaseClient();
  if (isLiveSupabaseSession() && client) {
    const result = await client.from('client_portals').update({ status: 'active', revoked_at: null, updated_at: next.updated_at }).eq('id', portal.id).select().single();
    if (result.error) { showToast(result.error.message || 'Portal reactivate failed.', 'error', 'Client Portal'); return; }
  }
  upsertClientPortal(next);
  showToast('Portal reactivated.', isLiveSupabaseSession() ? 'live' : 'local', 'Client Portal');
  render();
}

async function deleteClientPortal(portalId) {
  const portal = clientPortalById(portalId);
  if (!portal || !requirePermission('client_portals.manage', portal.company_id, 'Your role cannot manage portals.', 'Client Portal')) return;
  await recycleDeleteRecord({ type: 'client_portal', id: portal.id });
}

async function openClientPortal(form) {
  const fields = Object.fromEntries(new FormData(form).entries());
  const token = String(fields.token || '').trim();
  await openClientPortalToken(token, fields.password || '');
}

function shouldAutoOpenClientPortal(token) {
  const portal = state.clientPortalPublic;
  if (!token) return false;
  if (!portal || portal.token !== token) return true;
  return !portal.session && !portal.loading && !portal.passwordRequired && !portal.error;
}

async function ensureClientPortalPublicOpen(token) {
  if (!shouldAutoOpenClientPortal(token)) return;
  state.clientPortalPublic = { token, loading: true };
  render();
  await openClientPortalToken(token);
}

async function openClientPortalToken(token, password = '') {
  const response = await fetch('/api/client-portal-open', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ token, guest_name: CLIENT_PORTAL_GUEST_NAME, password: password || '' }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    state.clientPortalPublic = {
      token,
      error: payload.error || 'Could not open portal.',
      passwordRequired: payload.password_required === true,
    };
    render();
    return;
  }
  state.clientPortalPublic = {
    token,
    guestName: CLIENT_PORTAL_GUEST_NAME,
    session: payload.session,
    portal: payload.portal,
    documents: payload.documents || [],
    documentId: payload.documents?.[0]?.id || '',
    documentUrl: '',
    annotations: [],
  };
  writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
  render();
}

async function ensureClientPortalDocumentUrl() {
  const portal = state.clientPortalPublic;
  const cachedUrl = String(portal?.documentUrl || '');
  if (!portal?.session) return '';
  if (cachedUrl && cachedUrl.includes('/storage/v1/object/sign/')) return cachedUrl;
  const documentId = portal.documentId || portal.documents?.[0]?.id || '';
  if (!documentId) return '';
  if (portal.staff) {
    const doc = (portal.documents || []).find((item) => item.id === documentId);
    const client = createSupabaseClient();
    if (!client || !doc?.bucket_id || !doc?.object_path) return '';
    const { data, error } = await client.storage.from(doc.bucket_id).createSignedUrl(doc.object_path, 3600);
    if (error) throw new Error(error.message || 'Document unavailable.');
    state.clientPortalPublic.documentUrl = data?.signedUrl || '';
    return state.clientPortalPublic.documentUrl;
  }
  const response = await fetch('/api/client-portal-document-url', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ session: portal.session, document_id: documentId }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || 'Document unavailable.');
  state.clientPortalPublic.documentUrl = payload.url;
  state.clientPortalPublic.documentId = documentId;
  writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
  return payload.url;
}

async function fetchClientPortalDocumentFile(documentId) {
  const portal = state.clientPortalPublic;
  if (!portal?.session || !documentId) throw new Error('Open a document first.');
  if (portal.staff) {
    const signedUrl = await ensureClientPortalDocumentUrl();
    if (!signedUrl) throw new Error('Document unavailable.');
    const fileResponse = await fetch(signedUrl);
    if (!fileResponse.ok) throw new Error('Document unavailable.');
    return fileResponse.blob();
  }
  const response = await fetch('/api/client-portal-document-file', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ session: portal.session, document_id: documentId }),
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(payload.error || 'Document unavailable.');
  }
  return response.blob();
}

async function loadClientPortalAnnotations() {
  const portal = state.clientPortalPublic;
  if (!portal?.session || !portal.documentId) return [];
  if (portal.staff) {
    const client = createSupabaseClient();
    if (!client) return portal.annotations || [];
    const { data, error } = await client.from('client_portal_annotations')
      .select('*')
      .eq('portal_id', portal.portal?.id || '')
      .eq('document_id', portal.documentId)
      .order('created_at', { ascending: true });
    if (error) return portal.annotations || [];
    state.clientPortalPublic.annotations = (data || []).map(normalizeClientPortalAnnotation);
    return state.clientPortalPublic.annotations;
  }
  const url = `/api/client-portal-annotations?session=${encodeURIComponent(portal.session)}&document_id=${encodeURIComponent(portal.documentId)}`;
  const response = await fetch(url);
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) return [];
  state.clientPortalPublic.annotations = (payload.annotations || []).map(normalizeClientPortalAnnotation);
  writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
  return state.clientPortalPublic.annotations;
}

async function cpReloadPortalAnnotations(portalId) {
  const client = createSupabaseClient();
  if (!isLiveSupabaseSession() || !client || !portalId) return false;
  const { data, error } = await client.from('client_portal_annotations').select('*').eq('portal_id', portalId);
  if (error || !data) return false;
  const fresh = data.map(normalizeClientPortalAnnotation);
  state.clientPortalAnnotations = state.clientPortalAnnotations.filter((item) => item.portal_id !== portalId).concat(fresh);
  if (state.clientPortalPublic?.local && state.clientPortalPublic.portal?.id === portalId) {
    state.clientPortalPublic.annotations = fresh;
    writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
  }
  persistClientPortalCaches();
  return true;
}

async function mountClientPortalAnnotate() {
  const annotate = cpA();
  const frame = document.querySelector('[data-cp-frame]');
  if (!annotate || !frame) return;
  // Refresh markups from the DB the first time the annotate view opens.
  if (!annotate.synced) {
    annotate.synced = true;
    const portalId = cpIsGuest() ? state.clientPortalPublic?.portal?.id : annotate.portalId;
    const refreshed = (!cpIsGuest() || state.clientPortalPublic?.local)
      ? await cpWithTimeout(cpReloadPortalAnnotations(portalId), 5000, 'Markup refresh').catch((error) => {
        console.warn('Client portal markup refresh skipped:', error.message || error);
        return false;
      })
      : false;
    if (refreshed) {
      render();
      return;
    }
  }
  const doc = cpActiveDoc();
  if (!doc) return;
  if (cpIsGuest()) {
    state.clientPortalPublic.documentId = doc.id;
    if (!state.clientPortalPublic.local && !(state.clientPortalPublic.annotations || []).some((item) => item.document_id === doc.id)) {
      await cpWithTimeout(loadClientPortalAnnotations(), 5000, 'Markup refresh').catch((error) => {
        console.warn('Client portal markup refresh skipped:', error.message || error);
        return [];
      });
    }
  }
  let base;
  try {
    base = await cpResolveBase(doc, annotate.page);
  } catch (error) {
    frame.innerHTML = `<div class="cp-loading error">${h(error.message || 'Could not load this plan.')}</div>`;
    return;
  }
  cpRenderFrame(frame, doc, annotate.page, base);
  cpStartAnnotationPolling();
}

// --- Near-real-time markup sync -------------------------------------------------
// Poll the backend for new markups/comments so staff and clients see each other's
// activity live, without a manual Refresh. Works for both surfaces (owner: direct
// Supabase; guest: signed API). Re-renders only when something actually changed and
// the user isn't mid-draw or mid-type, so it never disrupts what they're doing.
let cpPollTimer = null;
let cpPollBusy = false;
let cpLastSig = null;

function cpStartAnnotationPolling() {
  if (cpPollTimer) return;
  cpLastSig = cpAnnotationSignature();
  cpPollTimer = setInterval(cpPollAnnotations, 5000);
}

function cpStopAnnotationPolling() {
  if (cpPollTimer) { clearInterval(cpPollTimer); cpPollTimer = null; }
  cpLastSig = null;
}

// A stable fingerprint of the active document's markups (id + last-change + reply
// count) so we can detect remote additions/edits/replies cheaply.
function cpAnnotationSignature() {
  const doc = cpActiveDoc();
  if (!doc) return '';
  const list = cpIsGuest()
    ? (state.clientPortalPublic?.annotations || [])
    : clientPortalAnnotationsForDocument(doc.id);
  return list
    .filter((annotation) => annotation.document_id === doc.id)
    .map((annotation) => `${annotation.id}:${annotation.updated_at || annotation.created_at || ''}:${(annotation.payload?.thread || []).length}`)
    .sort()
    .join('|');
}

// True while the user is actively drawing, placing, or typing — suppress the live
// re-render in those moments to avoid yanking focus or interrupting a stroke.
function cpUserIsBusy() {
  if (cpPointerState || cpA()?.placement) return true;
  const el = document.activeElement;
  return Boolean(el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') && el.closest('[data-cp-annotate]'));
}

async function cpPollAnnotations() {
  const annotate = cpA();
  const frame = document.querySelector('[data-cp-frame]');
  if (!annotate || !frame) { cpStopAnnotationPolling(); return; } // left the annotate view
  if (cpPollBusy) return;
  cpPollBusy = true;
  try {
    const portalId = cpIsGuest() ? state.clientPortalPublic?.portal?.id : annotate.portalId;
    if (!portalId) return;
    if (cpIsGuest() && !state.clientPortalPublic?.local) await loadClientPortalAnnotations();
    else await cpReloadPortalAnnotations(portalId);
    const sig = cpAnnotationSignature();
    if (sig !== cpLastSig && !cpUserIsBusy()) {
      cpLastSig = sig;
      render();
    }
  } catch {
    // Ignore transient network errors; the next tick retries.
  } finally {
    cpPollBusy = false;
  }
}

function cpRenderFrame(frame, doc, page, base) {
  const stage = frame.closest('.cp-stage');
  frame.dataset.baseW = base.w;
  frame.dataset.baseH = base.h;
  const annotations = cpAnnotationsFor(doc, page);
  frame.innerHTML = `
    <img class="cp-base" src="${base.dataUrl}" alt="${h(doc.file_name)}" draggable="false" />
    <svg class="cp-overlay" viewBox="0 0 ${base.w} ${base.h}" preserveAspectRatio="none">${cpAnnotationsSvg(annotations, base)}</svg>
    <div class="cp-pins">${cpAnnotationsPins(annotations)}</div>
  `;
  cpApplyView(frame, stage, base);
  cpBindFrame(frame, doc);
}

function cpAnnotationsSvg(annotations, base) {
  const selectedId = cpA().selectedId;
  return annotations.map((annotation) => {
    const payload = annotation.payload || {};
    const type = annotation.annotation_type;
    const color = payload.color || '#e66a1f';
    const sw = Number(payload.sw) || 2.5;
    const sel = annotation.id === selectedId ? ' cp-shape-sel' : '';
    const attr = `data-annotation-id="${h(annotation.id)}" class="cp-shape${sel}" style="--cp-c:${h(color)}"`;
    const W = base.w; const H = base.h;
    if (type === 'freehand' && Array.isArray(payload.points)) {
      const d = payload.points.map((pt, i) => `${i ? 'L' : 'M'}${(pt.x * W).toFixed(1)} ${(pt.y * H).toFixed(1)}`).join(' ');
      return `<path ${attr} d="${d}" fill="none" stroke="${h(color)}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/>`;
    }
    if (type === 'line' || type === 'arrow' || type === 'measure') {
      const x1 = (payload.x1 || 0) * W; const y1 = (payload.y1 || 0) * H;
      const x2 = (payload.x2 || 0) * W; const y2 = (payload.y2 || 0) * H;
      let extra = '';
      if (type === 'arrow') {
        const ang = Math.atan2(y2 - y1, x2 - x1); const head = 16;
        extra = `<path d="M${x2} ${y2} L${(x2 - head * Math.cos(ang - Math.PI / 6)).toFixed(1)} ${(y2 - head * Math.sin(ang - Math.PI / 6)).toFixed(1)} M${x2} ${y2} L${(x2 - head * Math.cos(ang + Math.PI / 6)).toFixed(1)} ${(y2 - head * Math.sin(ang + Math.PI / 6)).toFixed(1)}" stroke="${h(color)}" stroke-width="${sw}" vector-effect="non-scaling-stroke" fill="none" stroke-linecap="round"/>`;
      }
      if (type === 'measure') {
        const label = cpMeasureLabel(payload, base);
        extra = `<text x="${((x1 + x2) / 2).toFixed(0)}" y="${((y1 + y2) / 2 - 6).toFixed(0)}" fill="${h(color)}" font-size="${Math.round(base.w / 90)}" font-weight="700" text-anchor="middle" paint-order="stroke" stroke="#fff" stroke-width="3">${h(label)}</text>`;
      }
      return `<line ${attr} x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="${h(color)}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linecap="round"/>${extra}`;
    }
    if (type === 'rect' || type === 'highlight') {
      const x = (payload.x || 0) * W; const y = (payload.y || 0) * H;
      const w = (payload.w || 0) * W; const hgt = (payload.h || 0) * H;
      const fill = type === 'highlight' ? `${h(color)}` : 'none';
      const op = type === 'highlight' ? '0.28' : '1';
      return `<rect ${attr} x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${Math.abs(w).toFixed(1)}" height="${Math.abs(hgt).toFixed(1)}" fill="${fill}" fill-opacity="${op}" stroke="${h(color)}" stroke-width="${type === 'highlight' ? 0 : sw}" vector-effect="non-scaling-stroke"/>`;
    }
    if (type === 'circle') {
      const x = (payload.x || 0) * W; const y = (payload.y || 0) * H;
      const w = (payload.w || 0) * W; const hgt = (payload.h || 0) * H;
      return `<ellipse ${attr} cx="${(x + w / 2).toFixed(1)}" cy="${(y + hgt / 2).toFixed(1)}" rx="${Math.abs(w / 2).toFixed(1)}" ry="${Math.abs(hgt / 2).toFixed(1)}" fill="none" stroke="${h(color)}" stroke-width="${sw}" vector-effect="non-scaling-stroke"/>`;
    }
    return '';
  }).join('');
}

function cpMeasureLabel(payload, base) {
  const scale = payload.ftScale || 0;
  if (!scale) return 'set scale…';
  const dx = (payload.x2 - payload.x1);
  const dy = (payload.y2 - payload.y1) * (base.h / base.w);
  const len = Math.sqrt(dx * dx + dy * dy);
  const real = len * scale;
  const unit = payload.unit || 'ft';
  if (unit === 'in') return `${real.toFixed(real < 10 ? 1 : 0)}"`;
  if (unit === 'cm') return `${real.toFixed(real < 10 ? 1 : 0)} cm`;
  const ft = Math.floor(real);
  const inches = Math.round((real - ft) * 12);
  return inches ? `${ft}' ${inches}"` : `${ft}'`;
}

function cpAnnotationsPins(annotations) {
  const selectedId = cpA().selectedId;
  let commentIndex = 0;
  return annotations.map((annotation) => {
    const payload = annotation.payload || {};
    const type = annotation.annotation_type;
    if (type !== 'comment' && type !== 'label' && type !== 'marker') return '';
    const color = payload.color || '#e66a1f';
    const left = `${((payload.x || 0) * 100).toFixed(2)}%`;
    const top = `${((payload.y || 0) * 100).toFixed(2)}%`;
    const sel = annotation.id === selectedId ? ' sel' : '';
    const common = `data-cp-pin data-annotation-id="${h(annotation.id)}" style="left:${left};top:${top};--cp-c:${h(color)}"`;
    if (type === 'comment') {
      commentIndex += 1;
      return `<button class="cp-pin${sel}" ${common} title="${h(cpCommentTip(annotation))}" data-cp-comment-open><span class="cp-pin-bub">${commentIndex}</span></button>`;
    }
    if (type === 'label') {
      return `<button class="cp-label-tag${sel}" ${common}>${h(payload.text || 'Note')}</button>`;
    }
    const meta = CP_STATUS_META[payload.markerStatus];
    const markerLabel = meta ? meta.label : (payload.text || 'Mark');
    const markerIcon = meta ? meta.icon : 'ti-flag';
    return `<button class="cp-marker-tag${sel} ${h(meta ? payload.markerStatus : 'custom')}" ${common}><i class="ti ${markerIcon}"></i>${h(markerLabel)}</button>`;
  }).join('');
}

// Plain-text preview of a comment thread, used for the pin's hover tooltip.
function cpCommentTip(annotation) {
  const thread = Array.isArray(annotation.payload?.thread) ? annotation.payload.thread : [];
  const first = thread[0];
  const text = (first?.text || annotation.payload?.text || '').trim();
  if (!text) return 'Empty comment — click to open';
  const preview = text.length > 140 ? `${text.slice(0, 140)}…` : text;
  const replies = Math.max(0, thread.length - 1);
  const who = cpActorName(first?.author || 'draft');
  const tail = replies ? ` (+${replies} repl${replies === 1 ? 'y' : 'ies'})` : '';
  return `${who}: ${preview}${tail} — click to open`;
}

// Modal showing a comment pin's full thread + reply box (opened by tapping a pin).
function renderClientPortalCommentModal(annotation) {
  if (!annotation) return '';
  return `
    <div class="cp-modal-backdrop" data-action="cp-comment-close">
      <div class="cp-modal cp-comment-modal">
        <div class="cp-modal-head">
          <span class="cp-modal-ico comment"><i class="ti ti-message-2"></i></span>
          <h3>Comment</h3>
          <button class="cp-modal-x" type="button" data-action="cp-comment-close" title="Close"><i class="ti ti-x"></i></button>
        </div>
        <div class="cp-modal-body cp-comment-modal-body">
          ${renderClientPortalAnnoCard(annotation)}
        </div>
      </div>
    </div>`;
}

// Pointer position normalized to 0..1 within the frame.
function cpNormPoint(frame, event) {
  const rect = frame.getBoundingClientRect();
  const src = event.touches?.[0] || event.changedTouches?.[0] || event;
  return {
    x: Math.min(1, Math.max(0, (src.clientX - rect.left) / rect.width)),
    y: Math.min(1, Math.max(0, (src.clientY - rect.top) / rect.height)),
  };
}

function cpBindFrame(frame, doc) {
  const stage = frame.closest('.cp-stage');
  frame.onpointerdown = (event) => cpPointerDown(event, frame, doc, stage);
  frame.onpointermove = (event) => cpPointerMove(event, frame, doc);
  frame.onpointerup = (event) => cpPointerUp(event, frame, doc);
  // Wheel zooms the plan toward the cursor (Google-Maps style), and stops the
  // browser from scrolling/zooming the page behind it.
  if (stage) {
    stage.onwheel = (event) => {
      event.preventDefault();
      cpZoomAt(event.deltaY < 0 ? 1.12 : 1 / 1.12, event.clientX, event.clientY);
    };
  }
  cpBindKeyPan();
  cpFrameBound = doc.id;
}

// Cached base for the currently open document/page.
function cpCurrentBase() {
  const doc = cpActiveDoc();
  return doc ? cpBaseCache.get(cpCacheKey(doc.id, cpA().page)) : null;
}

// Unzoomed on-screen width (px) that lets the whole sheet fit inside the stage
// viewport. Everything else (zoom, pan) is layered on top of this via transform.
function cpFitWidth(stage, base) {
  const availW = Math.max(200, (stage?.clientWidth || 900) - 32);
  const availH = Math.max(200, (stage?.clientHeight || 600) - 32);
  const scale = Math.min(availW / base.w, availH / base.h, 2);
  return base.w * scale;
}

// Keep at least a sliver of the plan on-screen so it can never be lost off-canvas.
function cpClampPan(annotate, stage, dispW, dispH) {
  const margin = Math.min(140, dispW * 0.5, dispH * 0.5);
  annotate.panX = Math.min(stage.clientWidth - margin, Math.max(margin - dispW, annotate.panX));
  annotate.panY = Math.min(stage.clientHeight - margin, Math.max(margin - dispH, annotate.panY));
}

// Apply the current zoom + pan to the frame via a single CSS transform. The frame
// keeps its unzoomed fit-width; scale + translate handle the rest, so annotation
// coordinate math (which reads getBoundingClientRect) stays correct.
function cpApplyView(frame, stage, base) {
  const annotate = cpA();
  if (!frame || !stage || !base || !annotate) return;
  const fitW = cpFitWidth(stage, base);
  frame.style.width = `${Math.round(fitW)}px`;
  const dispW = fitW * annotate.zoom;
  const dispH = dispW * (base.h / base.w);
  if (annotate.panX == null || annotate.panY == null) {
    // Horizontally centre, but sit the sheet near the top of the canvas rather than
    // vertically centring it (leaves the empty space below, not above the plan).
    annotate.panX = (stage.clientWidth - dispW) / 2;
    annotate.panY = 16;
  }
  cpClampPan(annotate, stage, dispW, dispH);
  frame.style.transform = `translate(${annotate.panX.toFixed(1)}px, ${annotate.panY.toFixed(1)}px) scale(${annotate.zoom})`;
  const label = document.querySelector('[data-cp-zoom-label]');
  if (label) label.textContent = `${Math.round(annotate.zoom * 100)}%`;
}

// Zoom by a factor, keeping the point under the cursor (or stage centre) fixed.
function cpZoomAt(factor, clientX, clientY) {
  const annotate = cpA();
  const frame = document.querySelector('[data-cp-frame]');
  const stage = frame?.closest('.cp-stage');
  const base = cpCurrentBase();
  if (!annotate || !frame || !stage || !base) return;
  const prev = annotate.zoom;
  const next = Math.min(8, Math.max(0.25, prev * factor));
  if (next === prev) return;
  const stageRect = stage.getBoundingClientRect();
  const cx = (clientX == null ? stageRect.left + stage.clientWidth / 2 : clientX) - stageRect.left;
  const cy = (clientY == null ? stageRect.top + stage.clientHeight / 2 : clientY) - stageRect.top;
  // Content point under the cursor, in pre-zoom frame pixels, held fixed on screen.
  const fx = (cx - (annotate.panX ?? 0)) / prev;
  const fy = (cy - (annotate.panY ?? 0)) / prev;
  annotate.zoom = next;
  annotate.panX = cx - fx * next;
  annotate.panY = cy - fy * next;
  cpApplyView(frame, stage, base);
}

// Grab-cursor affordance: holding Ctrl/⌘ turns any tool into a pan handle.
let cpKeyPanBound = false;
function cpBindKeyPan() {
  if (cpKeyPanBound) return;
  cpKeyPanBound = true;
  const toggle = (on) => {
    const stage = document.querySelector('.cp-annotate .cp-stage');
    if (stage) stage.classList.toggle('cp-pan-ready', on);
  };
  window.addEventListener('keydown', (event) => { if (event.key === 'Control' || event.key === 'Meta') toggle(true); });
  window.addEventListener('keyup', (event) => { if (event.key === 'Control' || event.key === 'Meta') toggle(false); });
  window.addEventListener('blur', () => toggle(false));
}

function updateClientPortalAnnotateTool(toolId) {
  const annotate = cpA();
  if (!annotate) return;
  annotate.tool = toolId || 'select';
  document.querySelectorAll('[data-action="cp-tool"]').forEach((button) => {
    const active = button.dataset.tool === annotate.tool;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  const stage = document.querySelector('.cp-annotate .cp-stage');
  if (stage) stage.classList.toggle('cp-pan-ready', annotate.tool === 'pan');
}

function updateClientPortalAnnotateColor(color) {
  const annotate = cpA();
  if (!annotate) return;
  annotate.color = color || CP_PALETTE[0];
  document.querySelectorAll('[data-action="cp-color"]').forEach((button) => {
    button.classList.toggle('active', button.dataset.color === annotate.color);
  });
  document.querySelectorAll('[data-cp-color-input]').forEach((input) => { input.value = annotate.color; });
  document.querySelectorAll('.cp-custom-color').forEach((node) => {
    node.style.background = annotate.color;
    node.classList.toggle('active', !CP_PALETTE.includes(annotate.color));
  });
}

function updateClientPortalAnnotateStroke(value) {
  const annotate = cpA();
  if (!annotate) return;
  annotate.stroke = Math.max(1, Math.min(14, Number(value) || 2));
  document.querySelectorAll('[data-cp-stroke-input]').forEach((input) => { input.value = String(annotate.stroke); });
  document.querySelectorAll('[data-cp-stroke-val]').forEach((node) => { node.textContent = `${annotate.stroke}px`; });
  document.querySelectorAll('.cp-stroke-preview').forEach((node) => { node.style.height = `${Math.max(2, Math.min(14, annotate.stroke))}px`; });
}

function cpPointerDown(event, frame, doc, stage) {
  const annotate = cpA();
  const pinEl = event.target.closest('[data-cp-pin]');
  const capture = () => { try { frame.setPointerCapture(event.pointerId); } catch { /* ignore */ } };
  const startPan = () => {
    annotate.selectedId = null;
    cpPointerState = { mode: 'pan', x: event.clientX, y: event.clientY, px: annotate.panX ?? 0, py: annotate.panY ?? 0 };
    stage?.classList.add('cp-grabbing');
    capture();
  };
  // Ctrl/⌘ held: every tool becomes a pan handle, so Ctrl+drag always moves the
  // plan (like grabbing a Google Map) without drawing anything.
  if (event.ctrlKey || event.metaKey) {
    event.preventDefault();
    startPan();
    return;
  }
  // Select / drag pins, or select shapes
  if (annotate.tool === 'select') {
    const shapeEl = event.target.closest('[data-annotation-id]');
    if (pinEl) {
      annotate.selectedId = pinEl.dataset.annotationId;
      cpPointerState = { mode: 'drag-pin', id: pinEl.dataset.annotationId, startX: event.clientX, startY: event.clientY };
      capture();
      event.preventDefault();
      return;
    }
    if (shapeEl) {
      annotate.selectedId = shapeEl.dataset.annotationId;
      render();
      return;
    }
    // pan via drag on empty canvas
    startPan();
    return;
  }
  // Drawing tools
  event.preventDefault();
  const point = cpNormPoint(frame, event);
  // Pin-style tools open a modal at the clicked point instead of drawing.
  if (annotate.tool === 'comment' || annotate.tool === 'label' || annotate.tool === 'marker') {
    annotate.placement = { type: annotate.tool, x: point.x, y: point.y, color: annotate.color };
    render();
    return;
  }
  capture();
  if (annotate.tool === 'freehand') {
    cpPointerState = { mode: 'draw', tool: 'freehand', points: [point] };
    return;
  }
  cpPointerState = { mode: 'draw', tool: annotate.tool, start: point, current: point };
}

function cpPointerMove(event, frame, doc) {
  const ps = cpPointerState;
  if (!ps) return;
  if (ps.mode === 'pan') {
    const annotate = cpA();
    const stage = frame.closest('.cp-stage');
    annotate.panX = ps.px + (event.clientX - ps.x);
    annotate.panY = ps.py + (event.clientY - ps.y);
    cpApplyView(frame, stage, cpCurrentBase());
    return;
  }
  if (ps.mode === 'drag-pin') {
    const point = cpNormPoint(frame, event);
    const pin = frame.querySelector(`[data-cp-pin][data-annotation-id="${ps.id}"]`);
    if (pin) { pin.style.left = `${(point.x * 100).toFixed(2)}%`; pin.style.top = `${(point.y * 100).toFixed(2)}%`; }
    ps.point = point;
    return;
  }
  if (ps.mode === 'draw') {
    event.preventDefault();
    const point = cpNormPoint(frame, event);
    if (ps.tool === 'freehand') ps.points.push(point);
    else ps.current = point;
    cpDrawPreview(frame, ps);
  }
}

async function cpPointerUp(event, frame, doc) {
  const ps = cpPointerState;
  cpPointerState = null;
  if (!ps) return;
  if (ps.mode === 'pan') {
    frame.closest('.cp-stage')?.classList.remove('cp-grabbing');
    return;
  }
  if (ps.mode === 'drag-pin') {
    const movedPx = Math.hypot((event.clientX ?? ps.startX) - ps.startX, (event.clientY ?? ps.startY) - ps.startY);
    if (ps.point && movedPx > 6) {
      // Real drag → persist the pin's new position.
      const annotation = cpFindAnnotation(ps.id);
      if (annotation) {
        annotation.payload = { ...annotation.payload, x: ps.point.x, y: ps.point.y };
        await cpSaveAnnotation(annotation);
      }
    } else {
      // Tap (no meaningful drag) → open a comment's thread in a modal; other pins just select.
      const annotation = cpFindAnnotation(ps.id);
      if (annotation?.annotation_type === 'comment') cpA().openCommentId = ps.id;
    }
    render();
    return;
  }
  if (ps.mode === 'draw') {
    const annotate = cpA();
    const frameEl = frame.querySelector('.cp-measure-live');
    if (frameEl) frameEl.remove();
    let payload = { type: ps.tool, color: annotate.color, sw: annotate.stroke };
    if (ps.tool === 'freehand') {
      if (ps.points.length < 2) { render(); return; }
      payload.points = ps.points;
    } else {
      const a = ps.start; const b = ps.current || ps.start;
      if (Math.abs(a.x - b.x) < 0.004 && Math.abs(a.y - b.y) < 0.004) { render(); return; }
      if (ps.tool === 'line' || ps.tool === 'arrow' || ps.tool === 'measure') {
        payload = { ...payload, x1: a.x, y1: a.y, x2: b.x, y2: b.y };
        if (ps.tool === 'measure') {
          // Place the line immediately; calibrate via a clean modal on first use.
          const scale = doc.scale || cpProjectScale();
          payload.ftScale = scale || 0;
          payload.unit = doc.scale_unit || cpProjectUnit();
          const annotation = cpNewAnnotation(doc, 'measure', payload);
          await cpSaveAnnotation(annotation, true);
          await logClientPortalEvent(annotation.portal_id, 'annotation.added', { document_id: doc.id, type: 'measure' });
          cpA().selectedId = annotation.id;
          if (!scale) {
            cpA().placement = {
              type: 'measure',
              annotationId: annotation.id,
              baseW: Number(frame.dataset.baseW),
              baseH: Number(frame.dataset.baseH),
              x1: a.x, y1: a.y, x2: b.x, y2: b.y,
            };
          }
          render();
          return;
        }
      } else {
        payload = { ...payload, x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(b.x - a.x), h: Math.abs(b.y - a.y) };
      }
    }
    await cpCreateAnnotation(doc, ps.tool, payload);
  }
}

function cpDrawPreview(frame, ps) {
  const overlay = frame.querySelector('.cp-overlay');
  if (!overlay) return;
  const W = Number(frame.dataset.baseW || 1000); const H = Number(frame.dataset.baseH || 1000);
  const color = cpA().color;
  const sw = String(cpA().stroke || 2.5);
  let node = overlay.querySelector('.cp-preview');
  const ns = 'http://www.w3.org/2000/svg';
  if (ps.tool === 'freehand') {
    if (!node) { node = document.createElementNS(ns, 'path'); node.setAttribute('class', 'cp-preview'); node.setAttribute('fill', 'none'); node.setAttribute('stroke', color); node.setAttribute('stroke-width', sw); node.setAttribute('vector-effect', 'non-scaling-stroke'); overlay.appendChild(node); }
    node.setAttribute('d', ps.points.map((pt, i) => `${i ? 'L' : 'M'}${(pt.x * W).toFixed(1)} ${(pt.y * H).toFixed(1)}`).join(' '));
    return;
  }
  if (node) node.remove();
  const a = ps.start; const b = ps.current || ps.start;
  if (ps.tool === 'rect' || ps.tool === 'highlight' || ps.tool === 'circle') {
    const tag = ps.tool === 'circle' ? 'ellipse' : 'rect';
    node = document.createElementNS(ns, tag); node.setAttribute('class', 'cp-preview');
    const x = Math.min(a.x, b.x) * W; const y = Math.min(a.y, b.y) * H; const w = Math.abs(b.x - a.x) * W; const hh = Math.abs(b.y - a.y) * H;
    if (tag === 'ellipse') { node.setAttribute('cx', x + w / 2); node.setAttribute('cy', y + hh / 2); node.setAttribute('rx', w / 2); node.setAttribute('ry', hh / 2); }
    else { node.setAttribute('x', x); node.setAttribute('y', y); node.setAttribute('width', w); node.setAttribute('height', hh); }
    node.setAttribute('fill', ps.tool === 'highlight' ? color : 'none'); node.setAttribute('fill-opacity', ps.tool === 'highlight' ? '0.28' : '1');
    node.setAttribute('stroke', color); node.setAttribute('stroke-width', ps.tool === 'highlight' ? '0' : sw); node.setAttribute('vector-effect', 'non-scaling-stroke');
  } else {
    node = document.createElementNS(ns, 'line'); node.setAttribute('class', 'cp-preview');
    node.setAttribute('x1', a.x * W); node.setAttribute('y1', a.y * H); node.setAttribute('x2', b.x * W); node.setAttribute('y2', b.y * H);
    node.setAttribute('stroke', color); node.setAttribute('stroke-width', sw); node.setAttribute('vector-effect', 'non-scaling-stroke'); node.setAttribute('stroke-linecap', 'round');
  }
  overlay.appendChild(node);
  // Live measurement readout while dragging the ruler.
  if (ps.tool === 'measure') cpUpdateMeasureLive(frame, a, b, W, H);
}

// Floating "live" readout that follows the cursor while the ruler is dragged.
function cpUpdateMeasureLive(frame, a, b, W, H) {
  let chip = frame.querySelector('.cp-measure-live');
  if (!chip) {
    chip = document.createElement('div');
    chip.className = 'cp-measure-live';
    frame.appendChild(chip);
  }
  const doc = cpActiveDoc();
  const scale = (doc && doc.scale) || cpProjectScale();
  const unit = (doc && doc.scale_unit) || cpProjectUnit();
  const label = cpMeasureLabel({ x1: a.x, y1: a.y, x2: b.x, y2: b.y, ftScale: scale, unit }, { w: W, h: H });
  chip.textContent = scale ? label : 'set scale on release';
  chip.style.left = `${(b.x * 100).toFixed(2)}%`;
  chip.style.top = `${(b.y * 100).toFixed(2)}%`;
}

function cpFindAnnotation(id) {
  if (cpIsGuest()) return (state.clientPortalPublic?.annotations || []).find((item) => item.id === id) || null;
  return state.clientPortalAnnotations.find((item) => item.id === id) || null;
}

function cpNewAnnotation(doc, type, payload) {
  const annotate = cpA();
  const portal = cpIsGuest() ? state.clientPortalPublic.portal : clientPortalById(annotate.portalId);
  return normalizeClientPortalAnnotation({
    id: crypto.randomUUID(),
    company_id: portal?.company_id || activeCompanyId(),
    portal_id: portal?.id || annotate.portalId,
    document_id: doc.id,
    page_number: annotate.page + 1,
    guest_name: cpIsGuest() ? (state.clientPortalPublic.guestName || 'Client') : '',
    author_profile_id: cpIsGuest() ? '' : (activeSession()?.profile?.id || ''),
    annotation_type: type,
    payload: { ...payload, type, author: cpActorId(), author_name: cpActorName(cpActorId()) },
  });
}

async function cpCreateAnnotation(doc, type, payload) {
  const annotation = cpNewAnnotation(doc, type, payload);
  await cpSaveAnnotation(annotation, true);
  await logClientPortalEvent(annotation.portal_id, 'annotation.added', { document_id: doc.id, type });
  cpA().selectedId = annotation.id;
  render();
}

// Persist a new/updated annotation through the right adapter.
async function cpSaveAnnotation(annotation, isNew = false) {
  // A brand-new markup invalidates the redo history (unless it's Redo re-inserting one).
  if (isNew && cpA() && !cpA().suppressRedoClear) cpA().redoStack = [];
  if (cpIsGuest()) {
    const list = state.clientPortalPublic.annotations || [];
    state.clientPortalPublic.annotations = list.filter((item) => item.id !== annotation.id).concat([annotation]);
    writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
    await cpGuestPersist(annotation);
  } else {
    await persistClientPortalAnnotation(annotation);
  }
}

async function cpGuestPersist(annotation) {
  const portal = state.clientPortalPublic;
  if (!portal?.session) return;
  if (portal.local) {
    // Same-browser dev guest: write to the DB via the authenticated client so the
    // owner / main portal sees the markup. Without a backend, mirror to localStorage.
    upsertClientPortalAnnotationLocal(annotation);
    const client = createSupabaseClient();
    if (isLiveSupabaseSession() && client) {
      const { error } = await client.from('client_portal_annotations').upsert(clientPortalAnnotationPayload(annotation));
      if (error) showToast(error.message || 'Markup sync failed.', 'local', 'Client Portal');
    } else {
      persistClientPortalCaches();
    }
    return;
  }
  await fetch('/api/client-portal-annotations', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ session: portal.session, document_id: annotation.document_id, annotation }),
  }).catch(() => null);
}

async function cpDeleteAnnotation(id) {
  const annotation = cpFindAnnotation(id);
  if (!annotation) return;
  if (cpIsGuest()) {
    state.clientPortalPublic.annotations = (state.clientPortalPublic.annotations || []).filter((item) => item.id !== id);
    writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
    const portal = state.clientPortalPublic;
    if (portal.local) {
      state.clientPortalAnnotations = state.clientPortalAnnotations.filter((item) => item.id !== id);
      const client = createSupabaseClient();
      if (isLiveSupabaseSession() && client) {
        await client.from('client_portal_annotations').delete().eq('id', id);
      } else {
        persistClientPortalCaches();
      }
    } else {
      await fetch('/api/client-portal-annotations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session: portal.session, action: 'delete', annotation_id: id }),
      }).catch(() => null);
    }
  } else {
    await deleteClientPortalAnnotationRow(id);
  }
  if (cpA().selectedId === id) cpA().selectedId = null;
  render();
}

async function cpAddThreadReply(id, text) {
  const annotation = cpFindAnnotation(id);
  if (!annotation || !text.trim()) return;
  const message = { id: crypto.randomUUID(), author: cpActorId(), author_name: cpActorName(cpActorId()), text: text.trim(), at: new Date().toISOString() };
  annotation.payload = { ...annotation.payload, thread: [...(annotation.payload.thread || []), message] };
  await cpSaveAnnotation(annotation);
  render();
}

// Edit a single message in a comment thread (the first message is the comment itself).
async function cpEditThreadMessage(annotationId, messageId, text) {
  const annotation = cpFindAnnotation(annotationId);
  if (!annotation) return;
  const trimmed = String(text || '').trim();
  if (!trimmed) return;
  const thread = (annotation.payload?.thread || []).map((message) =>
    message.id === messageId ? { ...message, text: trimmed, edited_at: new Date().toISOString() } : message);
  annotation.payload = { ...annotation.payload, thread };
  if (cpA()) cpA().editingMessage = null;
  await cpSaveAnnotation(annotation);
  render();
}

// Delete a single message from a thread. If a comment's last message is removed, the
// whole comment pin goes with it (an empty comment has nothing to show).
async function cpDeleteThreadMessage(annotationId, messageId) {
  const annotation = cpFindAnnotation(annotationId);
  if (!annotation) return;
  const thread = (annotation.payload?.thread || []).filter((message) => message.id !== messageId);
  if (!thread.length && annotation.annotation_type === 'comment') {
    if (cpA()?.openCommentId === annotationId) cpA().openCommentId = null;
    await cpDeleteAnnotation(annotationId);
    render();
    return;
  }
  annotation.payload = { ...annotation.payload, thread };
  await cpSaveAnnotation(annotation);
  render();
}

// ---- Placement modals (comment / label / status stamp) ----------------------
function cpClosePlacement() {
  const placement = cpA()?.placement;
  if (cpA()) cpA().placement = null;
  // Cancelling calibration removes the uncalibrated line that was just drawn.
  if (placement?.type === 'measure' && placement.annotationId) {
    cpDeleteAnnotation(placement.annotationId).catch(() => null);
    return;
  }
  render();
}

async function cpCommitComment(text) {
  const placement = cpA()?.placement;
  const doc = cpActiveDoc();
  if (!placement || !doc) return;
  const annotation = cpNewAnnotation(doc, 'comment', { x: placement.x, y: placement.y, color: cpA().color });
  if (text && text.trim()) {
    annotation.payload.thread = [{ id: crypto.randomUUID(), author: cpActorId(), author_name: cpActorName(cpActorId()), text: text.trim(), at: new Date().toISOString() }];
  }
  cpA().placement = null;
  await cpSaveAnnotation(annotation, true);
  await logClientPortalEvent(annotation.portal_id, 'annotation.added', { document_id: doc.id, type: 'comment' });
  cpA().selectedId = annotation.id;
  render();
}

async function cpCommitLabel(text, color) {
  const placement = cpA()?.placement;
  const doc = cpActiveDoc();
  if (!placement || !doc || !text || !text.trim()) return;
  cpA().placement = null;
  await cpCreateAnnotation(doc, 'label', { x: placement.x, y: placement.y, text: text.trim(), color: color || placement.color || cpA().color });
}

async function cpCommitMarker(status, customText) {
  const placement = cpA()?.placement;
  const doc = cpActiveDoc();
  if (!placement || !doc) return;
  cpA().placement = null;
  const payload = { x: placement.x, y: placement.y, color: CP_PALETTE[0] };
  if (status === 'custom') {
    if (!customText || !customText.trim()) { render(); return; }
    payload.markerStatus = 'custom';
    payload.text = customText.trim();
  } else {
    if (!CP_STATUS_META[status]) { render(); return; }
    payload.markerStatus = status;
  }
  await cpCreateAnnotation(doc, 'marker', payload);
}

// Modal shown when placing a pin-style annotation (comment / label / marker)
// or calibrating the ruler.
// ---- Client portal placement dialog ----------------------------------------------------------------
// Body lives in ./portals/placement-modal.js and is fetched on first use.
let placementModalModule = null;
let placementModalPending = null;

function loadPlacementModal() {
  if (placementModalModule) return Promise.resolve(placementModalModule);
  if (!placementModalPending) {
    placementModalPending = import('./portals/placement-modal.js').then((mod) => {
      placementModalModule = mod.createPlacementModal({
        CP_LABEL_PRESETS, CP_PALETTE, CP_STATUS_META, cpProjectUnit, h,
      });
      return placementModalModule;
    }).catch((error) => {
      placementModalPending = null;
      throw error;
    });
  }
  return placementModalPending;
}

function renderClientPortalPlacementModal(placement) {
  if (placementModalModule) return placementModalModule.renderClientPortalPlacementModal(placement);
  loadPlacementModal().then(() => render()).catch((error) => console.error('Client portal placement dialog failed to load', error));
  return questLoader('Loading');
}


// All documents in the active annotate context (owner: portal; guest: session).
function cpAllDocs() {
  if (cpIsGuest()) return state.clientPortalPublic?.documents || [];
  return clientPortalDocumentsForPortal(cpA()?.portalId);
}

// The project-wide default scale: the first calibrated document's scale becomes
// the global default that every other plan references.
function cpProjectScale() {
  const calibrated = cpAllDocs().find((item) => item.scale);
  return calibrated ? calibrated.scale : null;
}

function cpProjectUnit() {
  const calibrated = cpAllDocs().find((item) => item.scale);
  if (calibrated && calibrated.scale_unit) return calibrated.scale_unit;
  return cpA()?.unit || 'ft';
}

// Switch the project measurement unit, converting any existing calibrated scale
// and measurements so they keep the same physical length.
const CP_FEET_PER_UNIT = { ft: 1, in: 1 / 12, cm: 1 / 30.48 };
async function cpChangeUnit(newUnit) {
  const annotate = cpA();
  if (!annotate || !CP_FEET_PER_UNIT[newUnit]) return;
  annotate.unit = newUnit;
  const calibrated = cpAllDocs().find((item) => item.scale);
  const current = calibrated?.scale_unit || 'ft';
  if (!calibrated || current === newUnit) { render(); return; }
  const conv = CP_FEET_PER_UNIT[current] / CP_FEET_PER_UNIT[newUnit];
  for (const doc of cpAllDocs()) {
    if (doc.scale) await cpApplyScaleToDoc(doc, doc.scale * conv, newUnit);
  }
  const list = cpIsGuest() ? (state.clientPortalPublic.annotations || []) : state.clientPortalAnnotations;
  const measures = list.filter((item) => item.annotation_type === 'measure' && item.payload?.ftScale
    && (cpIsGuest() || item.portal_id === annotate.portalId));
  for (const annotation of measures) {
    annotation.payload = { ...annotation.payload, ftScale: annotation.payload.ftScale * conv, unit: newUnit };
    await cpSaveAnnotation(annotation);
  }
  render();
}

// Persist a scale (and its unit) onto a document through the right adapter.
async function cpApplyScaleToDoc(doc, scale, unit) {
  doc.scale = scale;
  if (unit) doc.scale_unit = unit;
  if (cpIsGuest()) {
    const target = (state.clientPortalPublic.documents || []).find((item) => item.id === doc.id);
    if (target) { target.scale = scale; if (unit) target.scale_unit = unit; }
    writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
    if (state.clientPortalPublic.local) {
      const owned = clientPortalDocumentById(doc.id);
      if (owned) { owned.scale = scale; if (unit) owned.scale_unit = unit; }
      persistClientPortalCaches();
    }
  } else {
    await persistClientPortalDocument(doc);
  }
}

// Clear the calibrated scale across the whole project so the next ruler line
// re-establishes a new global default.
function cpClearProjectScale() {
  cpAllDocs().forEach((doc) => {
    if (!doc.scale) return;
    doc.scale = null;
    if (cpIsGuest()) {
      if (state.clientPortalPublic.local) {
        const owned = clientPortalDocumentById(doc.id);
        if (owned) owned.scale = null;
      }
    } else {
      persistClientPortalDocument(doc).catch(() => null);
    }
  });
  if (cpIsGuest()) {
    writeJson(CLIENT_PORTAL_SESSION_KEY, state.clientPortalPublic);
    if (state.clientPortalPublic.local) persistClientPortalCaches();
  }
}

// Parse a real-world length into the chosen unit's numeric value.
// ft also accepts feet-inches ("24'6\"") and inch input ("6in"/"6\"").
function cpParseLength(raw, unit = 'ft') {
  const value = String(raw || '').trim().toLowerCase();
  if (!value) return 0;
  if (unit === 'ft') {
    const feetInches = value.match(/^(\d+(?:\.\d+)?)\s*'\s*(\d+(?:\.\d+)?)?\s*"?$/);
    if (feetInches) return parseFloat(feetInches[1]) + (feetInches[2] ? parseFloat(feetInches[2]) / 12 : 0);
    const inchesOnly = value.match(/^(\d+(?:\.\d+)?)\s*(?:in|")$/);
    if (inchesOnly) return parseFloat(inchesOnly[1]) / 12;
  }
  const number = value.match(/(\d+(?:\.\d+)?)/);
  return number ? parseFloat(number[1]) : 0;
}

// Commit the calibration modal: derive the project scale (in the chosen unit)
// from the line that was just drawn.
async function cpCommitScale(text, unit = 'ft') {
  const placement = cpA()?.placement;
  if (!placement || placement.type !== 'measure') return;
  const cleanUnit = ['ft', 'in', 'cm'].includes(unit) ? unit : 'ft';
  const real = cpParseLength(text, cleanUnit);
  const dx = placement.x2 - placement.x1;
  const dy = (placement.y2 - placement.y1) * (placement.baseH / placement.baseW);
  const len = Math.sqrt(dx * dx + dy * dy);
  if (!real || !len) {
    showToast(cleanUnit === 'ft' ? 'Enter a length like 24, 24ft, or 24\'6".' : 'Enter a number like 18.5.', 'local', 'Client Portal');
    return;
  }
  const scale = real / len;
  const doc = cpActiveDoc();
  cpA().placement = null;
  if (doc) await cpApplyScaleToDoc(doc, scale, cleanUnit);
  const annotation = cpFindAnnotation(placement.annotationId);
  if (annotation) {
    annotation.payload = { ...annotation.payload, ftScale: scale, unit: cleanUnit };
    await cpSaveAnnotation(annotation);
  }
  render();
}

async function cpSetDocStatus(status) {
  const doc = cpActiveDoc();
  if (!doc || !CP_STATUS_META[status]) return;
  doc.review_status = status;
  if (cpIsGuest()) {
    const portal = state.clientPortalPublic;
    const target = (portal.documents || []).find((item) => item.id === doc.id);
    if (target) target.review_status = status;
    writeJson(CLIENT_PORTAL_SESSION_KEY, portal);
    if (portal.local) {
      const owned = clientPortalDocumentById(doc.id);
      if (owned) { owned.review_status = status; }
      const client = createSupabaseClient();
      if (isLiveSupabaseSession() && client) {
        await client.from('client_portal_documents').update({ review_status: status }).eq('id', doc.id);
        await logClientPortalEvent(portal.portal?.id || cpA()?.portalId, 'document.status', { document_id: doc.id, review_status: status });
      } else {
        persistClientPortalCaches();
      }
    } else {
      await fetch('/api/client-portal-document-status', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session: portal.session, document_id: doc.id, review_status: status }),
      }).catch(() => null);
    }
  } else {
    await persistClientPortalDocument(doc);
    await logClientPortalEvent(cpA().portalId, 'document.status', { document_id: doc.id, label: CP_STATUS_META[status].label });
  }
  render();
}

async function cpUndoLast() {
  const doc = cpActiveDoc();
  if (!doc) return;
  // Only undo your own markups — never remove the other party's work.
  const mine = cpAnnotationsFor(doc, cpA().page)
    .filter((annotation) => (annotation.payload?.author || (annotation.guest_name ? 'guest' : 'draft')) === cpActorId());
  const last = mine[mine.length - 1];
  if (!last) return;
  // Snapshot the markup before removing it so Redo can restore it verbatim.
  const snapshot = JSON.parse(JSON.stringify(last));
  await cpDeleteAnnotation(last.id);
  (cpA().redoStack = cpA().redoStack || []).push(snapshot);
  render();
}

async function cpRedoLast() {
  const stack = cpA()?.redoStack;
  if (!stack || !stack.length) return;
  const annotation = stack.pop();
  // Re-insert the undone markup (same id) without clearing the rest of the redo stack.
  cpA().suppressRedoClear = true;
  try {
    await cpSaveAnnotation(annotation, true);
  } finally {
    cpA().suppressRedoClear = false;
  }
  render();
}

async function exportClientPortalMarkedPdf() {
  const doc = cpActiveDoc();
  if (!doc) throw new Error('Open a document first.');
  const { saveClientPortalMarkedPdf } = await loadPdfExportRuntime();
  await saveClientPortalMarkedPdf({
    documentRecord: doc,
    resolveBase: (page) => cpResolveBase(doc, page),
    annotationsFor: (page) => cpAnnotationsFor(doc, page),
    measureLabel: cpMeasureLabel,
    statusMeta: CP_STATUS_META,
    createCanvas: () => document.createElement('canvas'),
    loadImage: loadClientPortalImage,
    fileName: `Quest-Portal-Markups-${new Date().toISOString().slice(0, 10)}.pdf`,
  });
  if (cpIsGuest()) {
    await fetch('/api/client-portal-export-event', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ session: state.clientPortalPublic?.session, details: { document_id: doc.id } }),
    }).catch(() => null);
  } else {
    await logClientPortalEvent(cpA().portalId, 'portal.exported', { document_id: doc.id });
  }
}

function loadClientPortalImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = 'anonymous';
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}

function createDriveFolder(form) {
  const fields = Object.fromEntries(new FormData(form).entries());
  const companyId = canonicalCompanyId(fields.company_id || activeCompanyId());
  if (!requirePermission('files.manage', companyId, 'Your role can view files but cannot create folders.', 'Files')) return;
  const name = String(fields.name || '').trim();
  if (!name) {
    state.sync = { label: 'Folder name is required', mode: 'local' };
    render();
    return;
  }
  const folder = normalizeDriveFolder({
    id: `folder-${crypto.randomUUID()}`,
    company_id: companyId,
    name,
    parent_key: fields.parent_key || 'home',
    created_by_label: activeSession().profile.full_name || 'Questbase',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });
  state.driveFolders.unshift(folder);
  state.modal = '';
  state.sync = { label: 'Folder created locally', mode: 'local' };
  notifyLocalEvent('file.folder', 'Folder created', `${actorName()} created ${folder.name}.`, companyPath('files', { folder: folder.id }, folder.company_id), 'folder', folder.id, folder.company_id);
  persistAll();
  render();
}

async function saveFinanceInvoice(form) {
  const fields = Object.fromEntries(new FormData(form).entries());
  const companyId = activeCompanyId();
  const linkedJob = jobById(fields.job_id);
  const previous = String(fields.id || '').trim() ? financeInvoiceById(String(fields.id).trim()) : null;
  const invoice = normalizeFinanceInvoice({
    ...fields,
    id: String(fields.id || '').trim() || `invoice-${crypto.randomUUID()}`,
    company_id: companyId,
    client_name: String(fields.client_name || linkedJob?.client_name || '').trim(),
    total: number(fields.subtotal) + number(fields.tax),
    updated_at: new Date().toISOString(),
  });
  const persisted = await persistFinanceRow('finance_invoices', invoicePayload(invoice), 'Invoice save failed');
  if (!persisted) return;
  upsertFinanceInvoice(invoice);
  if (previous?.job_id && previous.job_id !== invoice.job_id) syncJobInvoiceTotal(previous.job_id);
  syncJobInvoiceTotal(invoice.job_id);
  state.modal = '';
  state.sync = { label: state.session?.auth === 'supabase' ? 'Invoice saved securely' : 'Finance saved locally', mode: state.session?.auth === 'supabase' ? 'live' : 'local' };
  notifyLocalEvent('finance.invoice', previous ? 'Invoice updated' : 'Invoice created', `${actorName()} ${previous ? 'updated' : 'created'} ${invoice.invoice_number}.`, companyPath('finance', { invoice: invoice.id }, companyId), 'invoice', invoice.id, companyId);
  navigate(companyPath('finance', { invoice: invoice.id }, companyId), { replace: true });
}

async function saveFinancePayment(form) {
  const fields = Object.fromEntries(new FormData(form).entries());
  const companyId = activeCompanyId();
  const invoice = financeInvoiceById(fields.invoice_id);
  if (!invoice || invoice.company_id !== companyId) {
    state.sync = { label: 'Create an invoice before recording a payment', mode: 'local' };
    render();
    return;
  }
  const payment = normalizeFinancePayment({
    ...fields,
    id: `payment-${crypto.randomUUID()}`,
    company_id: companyId,
    created_at: new Date().toISOString(),
  });
  const persistedPayment = await persistFinanceRow('finance_payments', paymentPayload(payment), 'Payment save failed');
  if (!persistedPayment) return;
  invoice.status = invoiceBalance(invoice.id) - payment.amount <= 0 ? 'Paid' : 'Partially paid';
  invoice.updated_at = new Date().toISOString();
  const persistedInvoice = await persistFinanceRow('finance_invoices', invoicePayload(invoice), 'Invoice status update failed');
  if (!persistedInvoice) return;
  state.financePayments.unshift(payment);
  syncJobInvoiceTotal(invoice.job_id);
  persistAll();
  state.modal = '';
  state.sync = { label: state.session?.auth === 'supabase' ? 'Payment recorded securely' : 'Payment recorded locally', mode: state.session?.auth === 'supabase' ? 'live' : 'local' };
  notifyLocalEvent('finance.payment', 'Payment recorded', `${actorName()} recorded ${money(payment.amount)} for ${invoice.invoice_number}.`, companyPath('finance', { invoice: payment.invoice_id }, companyId), 'payment', payment.id, companyId);
  navigate(companyPath('finance', payment.invoice_id ? { invoice: payment.invoice_id } : {}, companyId), { replace: true });
}

