// Writes the clock wherever this session keeps its data.
//
// It used to return early for every Supabase session and write nothing at all, which is why
// a signed-in person's timer vanished on refresh: the local cache was skipped, and there was
// no server row to reload from either. `closedEntry` is the shift stopClock just finished,
// passed in so only that one row is inserted rather than the whole list re-sent.
function persistTimeState(closedEntry = null) {
  if (isReadOnlyDemo()) return;
  if (isLiveSupabaseSession()) {
    persistTimeStateToSupabase(closedEntry).catch((error) => console.warn('Clock write failed', error));
    return;
  }
  writeJson(TIME_ENTRY_CACHE_KEY, state.timeEntries);
  writeJson(ACTIVE_TIMER_KEY, state.activeTimer);
}

async function persistTimeStateToSupabase(closedEntry) {
  const client = createSupabaseClient();
  const profileId = activeSession()?.profile?.id;
  if (!client || !profileId) return;
  if (closedEntry) {
    const insert = await client.from('company_time_entries').insert({
      company_id: closedEntry.company_id,
      profile_id: profileId,
      task_id: closedEntry.task_id || '',
      task_title: closedEntry.task_title || '',
      started_at: closedEntry.started_at,
      ended_at: closedEntry.ended_at,
      duration_ms: closedEntry.duration_ms,
      notes: closedEntry.notes || '',
    }).select().single();
    // Swap the optimistic row for the stored one so its id is the server's, not a local
    // uuid that nothing else would ever match.
    if (!insert.error && insert.data) {
      const at = state.timeEntries.findIndex((row) => row.id === closedEntry.id);
      if (at >= 0) state.timeEntries[at] = normalizeTimeEntry(insert.data);
    } else if (insert.error) {
      notifySyncFailure(insert.error, 'Clock');
    }
  }
  const timer = state.activeTimer;
  // One row per person, upserted on the primary key: starting a clock while another runs
  // replaces it, which is the rule startClock already enforces in memory.
  const result = timer
    ? await client.from('company_active_timers').upsert({
      profile_id: profileId,
      company_id: timer.company_id,
      task_id: timer.task_id || '',
      task_title: timer.task_title || '',
      started_at: timer.started_at,
    }, { onConflict: 'profile_id' })
    : await client.from('company_active_timers').delete().eq('profile_id', profileId);
  if (result.error) notifySyncFailure(result.error, 'Clock');
}

function persistNotifications() {
  if (isReadOnlyDemo()) return;
  if (state.session?.auth === 'supabase') return;
  writeJson(NOTIFICATION_CACHE_KEY, state.notifications);
}

function persistCalendarEvents() {
  if (isReadOnlyDemo()) return;
  if (state.session?.auth === 'supabase') return;
  writeJson(CALENDAR_EVENT_CACHE_KEY, state.calendarEvents);
}

function persistMessages() {
  if (isReadOnlyDemo()) return;
  if (state.session?.auth === 'supabase') return;
  writeJson(MESSAGE_CONVERSATION_CACHE_KEY, state.messageConversations);
  writeJson(MESSAGE_ACCESS_CACHE_KEY, state.messageAccess);
  writeJson(MESSAGE_CACHE_KEY, state.messages);
  writeJson(MESSAGE_READ_CACHE_KEY, state.messageReads);
  writeJson(MESSAGE_ATTACHMENT_CACHE_KEY, state.messageAttachments);
}

function messageAccessFromForm(data, conversation, type) {
  if (type === 'company') {
    return [normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: conversation.company_id, conversation_id: conversation.id, target_type: 'all_company', target_id: 'all' })];
  }
  const rows = [];
  data.getAll('role_ids').forEach((roleId) => {
    if (roleId) rows.push(normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: conversation.company_id, conversation_id: conversation.id, target_type: 'role', target_id: roleId }));
  });
  data.getAll('profile_ids').forEach((profileId) => {
    if (profileId) rows.push(normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: conversation.company_id, conversation_id: conversation.id, target_type: 'profile', target_id: profileId }));
  });
  return rows.length ? rows : [normalizeMessageAccess({ id: `msg-access-${crypto.randomUUID()}`, company_id: conversation.company_id, conversation_id: conversation.id, target_type: 'profile', target_id: activeSession().profile.id })];
}

function markConversationRead(conversationId, sync = true) {
  if (!conversationId) return;
  const conversation = state.messageConversations.find((item) => item.id === conversationId);
  if (!conversation) return;
  const now = new Date().toISOString();
  const profileId = activeSession().profile.id;
  const read = normalizeMessageRead({ conversation_id: conversationId, company_id: conversation.company_id, profile_id: profileId, last_read_at: now });
  state.messageReads = [read].concat(state.messageReads.filter((item) => item.conversation_id !== conversationId || item.profile_id !== profileId));
  persistMessages();
  if (sync && isLiveSupabaseSession()) {
    const client = createSupabaseClient();
    if (client) settleObserved(
      client.from('message_reads').upsert(messageReadPayload(read), { onConflict: 'conversation_id,profile_id' }),
      (error) => console.warn('Message read sync failed', error),
      'Message read sync failed',
    );
  }
}

function notifyMessageEvents(conversation, message, attachments = []) {
  const href = companyPath('messages', { conversation: conversation.id }, conversation.company_id);
  const senderName = profileName(message.sender_profile_id);
  const participants = conversationNotificationRecipients(conversation)
    .filter((profileId) => profileId !== notificationProfileId(conversation.company_id, message.sender_profile_id));
  const mentioned = mentionedProfileIds(message.body, conversation.company_id)
    .filter((profileId) => profileId !== notificationProfileId(conversation.company_id, message.sender_profile_id));
  if (conversation.type === 'direct') {
    notifyLocalEvent('message.direct', 'New direct message', `${senderName} sent a direct message in ${conversation.title}.`, href, 'message', message.id, conversation.company_id, participants);
  }
  mentioned.forEach((profileId) => {
    notifyEvent({
      company_id: conversation.company_id,
      recipients: [profileId],
      type: 'message.mention',
      title: 'Mentioned in chat',
      body: `${senderName} mentioned you in ${conversation.title}.`,
      href,
      sourceType: 'message',
      sourceId: message.id,
    }).catch((error) => console.warn('Message mention notification failed', error));
  });
  if (attachments.length) {
    notifyLocalEvent('message.attachment', 'Attachment shared', `${senderName} shared ${attachments.length} attachment${attachments.length === 1 ? '' : 's'} in ${conversation.title}.`, href, 'message', message.id, conversation.company_id, participants);
  }
}

function mentionedProfileIds(body = '', companyId = activeCompanyId()) {
  const lower = String(body || '').toLowerCase();
  if (!lower.includes('@')) return [];
  return companyAccessUsers(companyId)
    .filter((user) => lower.includes(`@${String(user.name || '').split(/\s+/)[0].toLowerCase()}`) || lower.includes(`@${String(user.name || '').toLowerCase()}`))
    .map((user) => notificationProfileId(companyId, user.profile_id || user.member_id))
    .filter(Boolean);
}

function messageSenderProfile(profileId) {
  const profile = profileById(profileId);
  if (profile) return profile;
  const member = state.teamMembers.find((item) => item.id === profileId);
  return {
    id: profileId,
    full_name: member?.full_name || member?.name || profileId || 'Quest user',
    email: member?.email || '',
    avatar_url: member?.avatar_url || '',
  };
}

function accessUserName(user) {
  const name = String(user?.name || '').trim();
  if (name && !isOpaqueUserId(name)) return name;
  const email = String(user?.email || '').trim();
  if (email) return email.split('@')[0] || email;
  return 'Workspace user';
}

function accessUserMeta(user) {
  const parts = compactUnique([user?.email, user?.role_label || titleCase(user?.role || ''), titleCase(user?.status || '')]);
  return parts.join(' / ') || 'Company member';
}

function accessUserProfile(user) {
  return {
    id: user?.profile_id || user?.member_id || '',
    full_name: accessUserName(user),
    email: user?.email || '',
    avatar_url: user?.avatar_url || '',
  };
}

/**
 * Keep the "N selected" count and the Select all / Clear all toggle in step with the boxes.
 *
 * Done against the DOM rather than through render(), because re-rendering the dialog would
 * throw away what has been typed into the person search -- the same trap the workspace search
 * boxes fell into.
 */
function syncMessagePeopleSelection(scope) {
  const form = scope?.closest?.('.message-modal-form');
  if (!form) return;
  const boxes = Array.from(form.querySelectorAll('input[name="profile_ids"]'));
  const chosen = boxes.filter((box) => box.checked);
  const count = form.querySelector('[data-message-selected-count]');
  if (count) count.textContent = `${chosen.length} selected`;
  const toggle = form.querySelector('[data-message-select-all]');
  if (!toggle) return;
  // "Select all" means the people you can currently see. With a search term typed, ticking
  // everything in the company would be a nasty surprise.
  const visible = boxes.filter((box) => !box.closest('[data-message-person-row]')?.hidden);
  const allOn = visible.length > 0 && visible.every((box) => box.checked);
  toggle.dataset.mode = allOn ? 'clear' : 'select';
  toggle.textContent = allOn ? 'Clear all' : 'Select all';
}

function toggleMessagePeopleSelectAll(button) {
  const form = button.closest('.message-modal-form');
  if (!form) return;
  const select = button.dataset.mode !== 'clear';
  form.querySelectorAll('input[name="profile_ids"]').forEach((box) => {
    if (box.closest('[data-message-person-row]')?.hidden) return;
    box.checked = select;
  });
  syncMessagePeopleSelection(button);
}

function filterMessagePeopleList(input) {
  const query = String(input.value || '').trim().toLowerCase();
  const modal = input.closest('.message-modal-form');
  const rows = Array.from(modal?.querySelectorAll('[data-message-person-row]') || []);
  let visible = 0;
  rows.forEach((row) => {
    const checked = row.querySelector('input[type="checkbox"]')?.checked;
    const match = !query || String(row.dataset.filterText || '').includes(query);
    const show = checked || match;
    row.hidden = !show;
    if (show) visible += 1;
  });
  const count = modal?.querySelector('[data-message-filter-count]');
  if (count) count.textContent = query ? `${visible} match${visible === 1 ? '' : 'es'}` : `${rows.length} member${rows.length === 1 ? '' : 's'}`;
  syncMessagePeopleSelection(input);
}

function messageTypeSymbol(type) {
  return {
    company: 'q-symbol-company-chat',
    role: 'q-symbol-role-chat',
    custom: 'q-symbol-messages',
    direct: 'q-symbol-direct-chat',
  }[type] || 'q-symbol-messages';
}

function accessSummary(conversation) {
  const rows = conversationAccessRows(conversation.id);
  if (conversation.type === 'company' || rows.some((row) => row.target_type === 'all_company')) return 'Everyone in this company';
  const roles = rows.filter((row) => row.target_type === 'role').map((row) => roleById(conversation.company_id, row.target_id)?.name || 'Role');
  const profiles = rows.filter((row) => row.target_type === 'profile').map((row) => profileName(row.target_id));
  return roles.concat(profiles).slice(0, 5).join(', ') || 'Private chat';
}

function linkifyMentions(body) {
  return h(body).replace(/(^|\s)@([\w.-]+)/g, '$1<strong>@$2</strong>');
}

function fileSize(bytes) {
  const value = Number(bytes || 0);
  if (value >= 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MB`;
  if (value >= 1024) return `${Math.round(value / 1024)} KB`;
  return `${value} B`;
}

function fileToDataUrl(file) {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => resolve('');
    reader.readAsDataURL(file);
  });
}

// True when the user is actively typing somewhere — a full render() now would
// wipe the focused input/textarea (message composer or any open edit form).
function anEditableIsFocused() {
  const el = document.activeElement;
  if (!el) return false;
  return el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable === true;
}

/**
 * Is now a bad moment to rebuild the page from state?
 *
 * A render throws away everything that lives only in the DOM, and a half-filled form is exactly
 * that -- so any refresh the user did not ask for has to wait for one of these to clear. One
 * predicate rather than one per caller: the presence feed learned this the hard way, by wiping
 * what somebody had typed whenever a colleague opened the app.
 */
function renderWouldInterrupt() {
  return shouldDeferRealtimeRefresh({
    editableFocused: anEditableIsFocused(),
    builderModal: state.builderModal,
    modal: state.modal,
    recycleModal: state.recycleModal,
    dataLoading: state.dataLoading,
    backgroundRefreshing: state.backgroundRefreshing,
  });
}

function subscribeToMessageRealtime(companyId, conversationId) {
  const client = createSupabaseClient();
  if (state.session?.auth !== 'supabase' || !client?.channel || !conversationId) return;
  const key = `${companyId}:${conversationId}`;
  if (state.messageRealtimeKey === key) return;
  if (state.messageRealtimeChannel) client.removeChannel(state.messageRealtimeChannel);
  state.messageRealtimeKey = key;
  // Refresh on inbound changes, but never yank the DOM out from under someone
  // who is mid-type — defer the reload until they stop typing.
  const refreshFromRealtime = () => {
    if (anEditableIsFocused()) {
      clearTimeout(state.messageRealtimeRetry);
      state.messageRealtimeRetry = setTimeout(refreshFromRealtime, 1500);
      return;
    }
    refreshRealtimeDomains(['messages']).catch((error) => console.warn('Message refresh failed', error));
  };
  state.messageRealtimeChannel = client
    .channel(`quest-messages-${conversationId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'messages', filter: `conversation_id=eq.${conversationId}` }, refreshFromRealtime)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'message_attachments', filter: `conversation_id=eq.${conversationId}` }, refreshFromRealtime)
    .subscribe();
}

async function loadRealtimeDomain(client, domain) {
  if (domain === 'production') {
    // The five child tables of a job file. Fetched together because opening a job shows all
    // of them: five sequential round trips would be five visible gaps in one screen.
    const [dailies, buckets, draws, changeOrders, coLines, plans] = await Promise.all([
      safeSupabaseQuery(client.from('job_dailies').select('*').order('report_date', { ascending: false })),
      safeSupabaseQuery(client.from('job_cost_buckets').select('*').order('sort_order', { ascending: true })),
      safeSupabaseQuery(client.from('job_draws').select('*').order('sort_order', { ascending: true })),
      safeSupabaseQuery(client.from('job_change_orders').select('*').order('created_at', { ascending: false })),
      safeSupabaseQuery(client.from('job_change_order_lines').select('*').order('sort_order', { ascending: true })),
      safeSupabaseQuery(client.from('job_plans').select('*').order('created_at', { ascending: false })),
    ]);
    if (!dailies.error) state.jobDailies = (dailies.data || []).map(normalizeDaily);
    if (!buckets.error) state.jobCostBuckets = (buckets.data || []).map(normalizeCostBucket);
    if (!draws.error) state.jobDraws = (draws.data || []).map(normalizeDraw);
    if (!changeOrders.error) state.jobChangeOrders = (changeOrders.data || []).map(normalizeChangeOrder);
    if (!coLines.error) state.jobChangeOrderLines = (coLines.data || []).map(normalizeChangeOrderLine);
    if (!plans.error) state.jobPlans = (plans.data || []).map(normalizePlan);
    return;
  }
  if (domain === 'operations') {
    const [jobs, tasks, calendar] = await Promise.all([
      client.from('jobs').select('*').order('updated_at', { ascending: false }),
      client.from('tasks').select('*').order('updated_at', { ascending: false }),
      client.from('calendar_events').select('*').order('starts_at', { ascending: true }),
    ]);
    if (!jobs.error) state.jobs = activeRows(jobs.data || []).map(normalizeJob);
    if (!tasks.error) state.tasks = activeRows(tasks.data || []).map(normalizeTask);
    if (!calendar.error) state.calendarEvents = activeRows(calendar.data || []).map(normalizeCalendarEvent);
    return;
  }
  if (domain === 'crm') {
    const [contacts, stages, accounts, deals, sites, proposals, activities] = await Promise.all([
      client.from('contacts').select('*').order('updated_at', { ascending: false }),
      client.from('pipeline_stages').select('*').order('position', { ascending: true }),
      client.from('accounts').select('*').order('name', { ascending: true }),
      client.from('deals').select('*').order('updated_at', { ascending: false }),
      safeSupabaseQuery(client.from('crm_sites').select('*').order('updated_at', { ascending: false })),
      safeSupabaseQuery(client.from('proposal_documents').select('*').order('updated_at', { ascending: false })),
      client.from('activities').select('*').order('created_at', { ascending: false }).limit(500),
    ]);
    if (!contacts.error) state.contacts = activeRows(contacts.data || []).map(normalizeContact);
    if (!stages.error) { state.pipelineStages = stages.data || []; applyPipelineStagesForCompany(activeCompanyId()); }
    if (!accounts.error) state.accounts = activeRows(accounts.data || []).map(normalizeAccount);
    if (!deals.error) state.deals = activeRows(deals.data || []).map(normalizeDeal);
    if (!sites.error) state.sites = (sites.data || []).map(normalizeCrmSite);
    if (!proposals.error) state.proposals = activeRows(proposals.data || []).map(normalizeProposal);
    if (!activities.error) state.activities = activeRows(activities.data || []).map(normalizeActivity);
    return;
  }
  if (domain === 'files') {
    const result = await client.from('job_files').select('*').is('deleted_at', null).order('created_at', { ascending: false });
    if (!result.error) { state.files = (result.data || []).map(normalizeFile); wbReconstructAppDriveFolders(); }
    return;
  }
  if (domain === 'forms') {
    const [forms, responses] = await Promise.all([
      client.from('forms').select('*').order('updated_at', { ascending: false }),
      client.from('form_responses').select('*').order('created_at', { ascending: false }).limit(500),
    ]);
    if (!forms.error) state.forms = activeRows(forms.data || []).map(normalizeForm);
    if (!responses.error) state.formResponses = activeRows(responses.data || []).map(normalizeFormResponse);
    return;
  }
  if (domain === 'finance') {
    const [invoices, payments, expenses, vendors] = await Promise.all([
      client.from('finance_invoices').select('*').order('updated_at', { ascending: false }),
      client.from('finance_payments').select('*').order('received_at', { ascending: false }),
      client.from('finance_expenses').select('*').order('spent_at', { ascending: false }),
      client.from('finance_vendors').select('*').order('name', { ascending: true }),
    ]);
    if (!invoices.error) state.financeInvoices = activeRows(invoices.data || []).map(normalizeFinanceInvoice);
    if (!payments.error) state.financePayments = activeRows(payments.data || []).map(normalizeFinancePayment);
    if (!expenses.error) state.financeExpenses = activeRows(expenses.data || []).map(normalizeFinanceExpense);
    if (!vendors.error) state.financeVendors = activeRows(vendors.data || []).map(normalizeFinanceVendor);
    return;
  }
  return loadSecondaryRealtimeDomain(client, domain);
}

async function loadSecondaryRealtimeDomain(client, domain) {
  if (domain === 'portals') {
    const [portals, documents, annotations, events] = await Promise.all([
      safeSupabaseQuery(client.from('client_portals').select('*').order('updated_at', { ascending: false })),
      safeSupabaseQuery(client.from('client_portal_documents').select('*').order('created_at', { ascending: false })),
      safeSupabaseQuery(client.from('client_portal_annotations').select('*').order('created_at', { ascending: true })),
      safeSupabaseQuery(client.from('client_portal_events').select('*').order('created_at', { ascending: false }).limit(500)),
    ]);
    if (!portals.error) state.clientPortals = activeRows(portals.data || []).map(normalizeClientPortal);
    if (!documents.error) state.clientPortalDocuments = activeRows(documents.data || []).map(normalizeClientPortalDocument);
    if (!annotations.error) state.clientPortalAnnotations = (annotations.data || []).map(normalizeClientPortalAnnotation);
    if (!events.error) state.clientPortalEvents = (events.data || []).map(normalizeClientPortalEvent);
    return;
  }
  if (domain === 'pricebook') {
    const [vendors, materials, prices] = await Promise.all([
      safeSupabaseQuery(client.from('pricebook_vendors').select('*').order('name', { ascending: true })),
      safeSupabaseQuery(client.from('pricebook_materials').select('*').order('name', { ascending: true })),
      safeSupabaseQuery(client.from('pricebook_vendor_prices').select('*').order('updated_at', { ascending: false })),
    ]);
    if (!vendors.error) state.pricebookVendors = activeRows(vendors.data || []).map(normalizePricebookVendor);
    if (!materials.error) state.pricebookMaterials = activeRows(materials.data || []).map(normalizePricebookMaterial);
    if (!prices.error) state.pricebookPrices = activeRows(prices.data || []).map(normalizePricebookPrice);
    return;
  }
  if (domain === 'notifications') {
    const result = await client.from('notifications').select('*').order('created_at', { ascending: false }).limit(200);
    if (!result.error) state.notifications = (result.data || []).map(normalizeNotification);
    return;
  }
  if (domain === 'labels') {
    const [labels, assignments] = await Promise.all([
      safeSupabaseQuery(client.from('contact_labels').select('*').order('name', { ascending: true })),
      safeSupabaseQuery(client.from('contact_label_assignments').select('*')),
    ]);
    if (!labels.error) state.contactLabels = labels.data || [];
    if (!assignments.error) state.contactLabelAssignments = assignments.data || [];
    return;
  }
  if (domain === 'audit') {
    const result = await safeSupabaseQuery(client.from('audit_events').select('*').order('created_at', { ascending: false }).limit(100));
    if (!result.error) state.auditEvents = result.data || [];
    return;
  }
  if (domain === 'underwriting') {
    const [result, calculators] = await Promise.all([
      safeSupabaseQuery(client.from('underwriting_cases').select('*').order('updated_at', { ascending: false })),
      safeSupabaseQuery(client.from('underwriting_calculators').select('*').order('position', { ascending: true })),
    ]);
    if (!result.error) state.underwritingCases = activeRows(result.data || []).map(normalizeUnderwritingCase);
    // Kept as the server sent them: the takeoff module owns this shape and normalizes on read,
    // so the entry bundle does not carry a copy of the calculator's schema for a page most
    // sessions never open.
    if (!calculators.error) state.underwritingCalculators = calculators.data || [];
    return;
  }
  if (domain === 'proposals') {
    const result = await safeSupabaseQuery(client.from('proposal_documents').select('*').order('updated_at', { ascending: false }));
    if (!result.error) state.proposals = activeRows(result.data || []).map(normalizeProposal);
    return;
  }
  if (domain === 'recycle') {
    const result = await safeSupabaseQuery(client.from('recycle_bin_items').select('*').order('deleted_at', { ascending: false }));
    if (!result.error) state.recycleBinItems = (result.data || []).map(normalizeRecycleBinItem);
    return;
  }
  if (domain === 'workspace') {
    const { WORKSPACE_BACKUP_METADATA_COLUMNS } = await import('./data/workspace-backups.js');
    const [backups, builder, records, transfers] = await Promise.all([
      safeSupabaseQuery(client.from('workspace_backups').select(WORKSPACE_BACKUP_METADATA_COLUMNS).order('created_at', { ascending: false })),
      safeSupabaseQuery(client.from('workspace_builder_state').select('*')),
      safeSupabaseQuery(client.from('wb_records').select('*')),
      safeSupabaseQuery(client.from('wb_data_transfers').select('*').order('created_at', { ascending: false }).limit(200)),
    ]);
    if (!backups.error) state.workspaceBackups = (backups.data || []).map(normalizeWorkspaceBackup);
    if (!builder.error) applyWorkspaceBuilderRows(builder.data, records.error ? null : (records.data || []));
    if (!transfers.error) state.wbTransfers = transfers.data || [];
    return;
  }
  return loadIdentityRealtimeDomain(client, domain);
}

